export default "t_output.set(input_value=language_model_component.text_response)\\n\\n    return Graph(start=chat_input, end=chat_output)\\n\\n\\nasync def test_vector_store_rag(ingestion_graph, rag_graph):\\n    assert ingestion_graph is not None\\n    ingestion_ids = [\\n        \\\"file-123\\\",\\n        \\\"text-splitter-123\\\",\\n    ]\\n    assert rag_graph is not None\\n    rag_ids = [\\n        \\\"chatinput-123\\\",\\n        \\\"chatoutput-123\\\",\\n        \\\"language-model-123\\\",\\n        \\\"parse-data-123\\\",\\n        \\\"prompt-123\\\",\\n        \\\"rag-file-123\\\",\\n        \\\"rag-text-splitter-123\\\",\\n    ]\\n    for ids, graph in [(ingestion_ids, ingestion_graph), (rag_ids, rag_graph)]:\\n        results = [result async for result in graph.async_start(reset_output_values=False)]\\n        vids = [result.vertex.id for result in results if hasattr(result, \\\"vertex\\\")]\\n        assert all(vid in ids for vid in vids), f\\\"Diff: {set(vids) - set(ids)}\\\"\\n        assert results[-1] == Finish()\\n\\n\\ndef test_vector_store_rag_dump_components_and_edges(ingestion_graph, rag_graph):\\n    ingestion_graph_dump = ingestion_graph.dump(\\n        name=\\\"Ingestion Graph\\\", description=\\\"Graph for data ingestion\\\", endpoint_name=\\\"ingestion\\\"\\n    )\\n\\n    ingestion_data = ingestion_graph_dump[\\\"data\\\"]\\n    ingestion_nodes = ingestion_data[\\\"nodes\\\"]\\n    ingestion_edges = ingestion_data[\\\"edges\\\"]\\n\\n    expected_nodes = {\\n        \\\"file-123\\\": \\\"File\\\",\\n        \\\"text-splitter-123\\\": \\\"SplitText\\\",\\n    }\\n\\n    assert len(ingestion_nodes) == len(expected_nodes), \\\"Unexpected number of nodes\\\"\\n\\n    node_map = {node[\\\"id\\\"]: node[\\\"data\\\"] for node in ingestion_nodes}\\n\\n    for node_id, expected_type in expected_nodes.items():\\n        assert node_id in node_map, f\\\"Missing node {node_id}\\\"\\n        assert node_map[node_id][\\\"type\\\"] == expected_type, (\\n            f\\\"Node {node_id} has incorrect type. Expected {expected_type}, got {node_map[node_id]['type']}\\\"\\n        )\\n\\n    unexpected_nodes = set(node_map.keys()) - set(expected_nodes.keys())\\n    assert not unexpected_nodes, f\\\"Found unexpected nodes: {unexpected_nodes}\\\"\\n\\n    expected_ingestion_edges = [\\n        (\\\"file-123\\\", \\\"text-splitter-123\\\"),\\n    ]\\n    assert len(ingestion_edges) == len(expected_ingestion_edges)\\n\\n    for edge in ingestion_edges:\\n        source = edge[\\\"source\\\"]\\n        target = edge[\\\"target\\\"]\\n        assert (source, target) in expected_ingestion_edges, edge\\n\\n    rag_graph_dump = rag_graph.dump(\\n        name=\\\"RAG Graph\\\", description=\\\"Graph for Retrieval-Augmented Generation\\\", endpoint_name=\\\"rag\\\"\\n    )\\n\\n    rag_data = rag_graph_dump[\\\"data\\\"]\\n    rag_nodes = sorted(rag_data[\\\"nodes\\\"], key=operator.itemgetter(\\\"id\\\"))\\n    rag_edges = rag_data[\\\"edges\\\"]\\n\\n    expected_rag_nodes = sorted(\\n        [\\n            {\\\"id\\\": \\\"chatinput-123\\\", \\\"type\\\": \\\"ChatInput\\\"},\\n            {\\\"id\\\": \\\"chatoutput-123\\\", \\\"type\\\": \\\"ChatOutput\\\"},\\n            {\\\"id\\\": \\\"language-model-123\\\", \\\"type\\\": \\\"LanguageModelComponent\\\"},\\n            {\\\"id\\\": \\\"parse-data-123\\\", \\\"type\\\": \\\"ParserComponent\\\"},\\n            {\\\"id\\\": \\\"prompt-123\\\", \\\"type\\\": \\\"Prompt Template\\\"},\\n            {\\\"id\\\": \\\"rag-file-123\\\", \\\"type\\\": \\\"File\\\"},\\n            {\\\"id\\\": \\\"rag-text-splitter-123\\\", \\\"type\\\": \\\"SplitText\\\"},\\n        ],\\n        key=operator.itemgetter(\\\"id\\\"),\\n    )\\n\\n    for expected_node, node in zip(expected_rag_nodes, rag_nodes, strict=True):\\n        assert node[\\\"data\\\"][\\\"type\\\"] == expected_node[\\\"type\\\"]\\n        assert node[\\\"id\\\"] == expected_node[\\\"id\\\"]\\n\\n    expected_rag_edges = [\\n        (\\\"chatinput-123\\\", \\\"prompt-123\\\"),\\n        (\\\"language-model-123\\\", \\\"chatoutput-123\\\"),\\n        (\\\"parse-data-123\\\", \\\"prompt-123\\\"),\\n        (\\\"prompt-123\\\", \\\"language-model-123\\\"),\\n        (\\\"rag-file-123\\\", \\\"rag-text-splitter-123\\\"),\\n        (\\\"rag-text-splitter-123\\\", \\\"parse-data-123\\\"),\\n    ]\\n    assert len(rag_edges) == len(expected_rag_edges), rag_edges\\n\\n    for edge in rag_edges:\\n        source = edge[\\\"source\\\"]\\n        target = edge[\\\"target\\\"]\\n        assert (source, target) in expected_rag_edges, f\\\"Edge {source} -> {target} not found\\\"\\n\\n\\ndef test_vector_store_rag_add(ingestion_graph: Graph, rag_graph: Graph):\\n    ingestion_graph_copy = copy.deepcopy(ingestion_graph)\\n    rag_graph_copy = copy.deepcopy(rag_graph)\\n    ingestion_graph_copy += rag_graph_copy\\n\\n    assert len(ingestion_graph_copy.vertices) == len(ingestion_graph.vertices) + len(rag_graph.vertices), (\\n        f\\\"Vertices mismatch: {len(ingestion_graph_copy.vertices)} \\\"\\n        f\\\"!= {len(ingestion_graph.vertices)} + {len(rag_graph.vertices)}\\\"\\n    )\\n    assert len(ingestion_graph_copy.edges) == len(ingestion_graph.edges) + len(rag_graph.edges), (\\n        f\\\"Edges mismatch: {len(ingestion_graph_copy.edges)} != {len(ingestion_graph.edges)} + {len(rag_graph.edges)}\\\"\\n    )\\n\\n    combined_graph_dump = ingestion_graph_copy.dump(\\n        name=\\\"Combined Graph\\\", description=\\\"Graph for data ingestion and RAG\\\", endpoint_name=\\\"combined\\\"\\n    )\\n\\n    combined_data = combined_graph_dump[\\\"data\\\"]\\n    combined_nodes = sorted(combined_data[\\\"nodes\\\"], key=operator.itemgetter(\\\"id\\\"))\\n    combined_edges = combined_data[\\\"edges\\\"]\\n\\n    expected_nodes = sorted(\\n        [\\n            {\\\"id\\\": \\\"file-123\\\", \\\"type\\\": \\\"File\\\"},\\n            {\\\"id\\\": \\\"text-splitter-123\\\", \\\"type\\\": \\\"SplitText\\\"},\\n            {\\\"id\\\": \\\"chatinput-123\\\", \\\"type\\\": \\\"ChatInput\\\"},\\n            {\\\"id\\\": \\\"chatoutput-123\\\", \\\"type\\\": \\\"ChatOutput\\\"},\\n            {\\\"id\\\": \\\"language-model-123\\\", \\\"type\\\": \\\"LanguageModelComponent\\\"},\\n            {\\\"id\\\": \\\"parse-data-123\\\", \\\"type\\\": \\\"ParserComponent\\\"},\\n            {\\\"id\\\": \\\"prompt-123\\\", \\\"type\\\": \\\"Prompt Template\\\"},\\n            {\\\"id\\\": \\\"rag-file-123\\\", \\\"type\\\": \\\"File\\\"},\\n            {\\\"id\\\": \\\"rag-text-splitter-123\\\", \\\"type\\\": \\\"SplitText\\\"},\\n        ],\\n        key=operator.itemgetter(\\\"id\\\"),\\n    )\\n\\n    for expected_node, combined_node in zip(expected_nodes, combined_nodes, strict=True):\\n        assert combined_node[\\\"data\\\"][\\\"type\\\"] == expected_node[\\\"type\\\"]\\n        assert combined_node[\\\"id\\\"] == expected_node[\\\"id\\\"]\\n\\n    expected_combined_edges = [\\n        (\\\"file-123\\\", \\\"text-splitter-123\\\"),\\n        (\\\"chatinput-123\\\", \\\"prompt-123\\\"),\\n        (\\\"language-model-123\\\", \\\"chatoutput-123\\\"),\\n        (\\\"parse-data-123\\\", \\\"prompt-123\\\"),\\n        (\\\"prompt-123\\\", \\\"language-model-123\\\"),\\n        (\\\"rag-file-123\\\", \\\"rag-text-splitter-123\\\"),\\n        (\\\"rag-text-splitter-123\\\", \\\"parse-data-123\\\"),\\n    ]\\n\\n    assert len(combined_edges) == len(expected_combined_edges), combined_edges\\n\\n    for edge in combined_edges:\\n        source = edge[\\\"source\\\"]\\n        target = edge[\\\"target\\\"]\\n        assert (source, target) in expected_combined_edges, f\\\"Edge {source} -> {target} not found\\\"\\n\\n\\ndef test_vector_store_rag_dump(ingestion_graph, rag_graph):\\n    ingestion_graph_dump = ingestion_graph.dump(\\n        name=\\\"Ingestion Graph\\\", description=\\\"Graph for data ingestion\\\", endpoint_name=\\\"ingestion\\\"\\n    )\\n    assert isinstance(ingestion_graph_dump, dict)\\n\\n    ingestion_data = ingestion_graph_dump[\\\"data\\\"]\\n    assert \\\"nodes\\\" in ingestion_data\\n    assert \\\"edges\\\" in ingestion_data\\n    assert \\\"description\\\" in ingestion_graph_dump\\n    assert \\\"endpoint_name\\\" in ingestion_graph_dump\\n\\n    ingestion_nodes = ingestion_data[\\\"nodes\\\"]\\n    ingestion_edges = ingestion_data[\\\"edges\\\"]\\n    assert len(ingestion_nodes) == 2\\n    assert len(ingestion_edges) == 1\\n\\n    rag_graph_dump = rag_graph.dump(\\n        name=\\\"RAG Graph\\\", description=\\\"Graph for Retrieval-Augmented Generation\\\", endpoint_name=\\\"rag\\\"\\n    )\\n    assert isinstance(rag_graph_dump, dict)\\n\\n    rag_data = rag_graph_dump[\\\"data\\\"]\\n    assert \\\"nodes\\\" in rag_data\\n    assert \\\"edges\\\" in rag_data\\n    assert \\\"description\\\" in rag_graph_dump\\n    assert \\\"endpoint_name\\\" in rag_graph_dump\\n\\n    rag_nodes = rag_data[\\\"nodes\\\"]\\n    rag_edges = rag_data[\\\"edges\\\"]\\n    assert len(rag_nodes) == 7\\n    assert len(rag_edges) == 6\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/initial_setup/test_setup_functions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"edeb29e380e78cb935930d3964b40b1649f0365501838a87de5e6fcc12ef6b49\",\"content\":\"import asyncio\\nfrom copy import deepcopy\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.initial_setup.constants import STARTER_FOLDER_NAME\\nfrom langflow.initial_setup.setup import (\\n    get_or_create_default_folder,\\n    get_or_create_starter_folder,\\n    session_scope,\\n    update_projects_components_with_latest_component_versions,\\n)\\nfrom langflow.services.database.models.folder.constants import DEFAULT_FOLDER_NAME\\nfrom langflow.services.database.models.folder.model import Folder, FolderRead\\nfrom sqlmodel import select\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_get_or_create_default_folder_creation() -> None:\\n    \\\"\\\"\\\"Test that a default project is created for a new user.\\n\\n    This test verifies that when no default project exists for a given user,\\n    get_or_create_default_folder creates one with the expected name and assigns it an ID.\\n    \\\"\\\"\\\"\\n    test_user_id = uuid4()\\n    async with session_scope() as session:\\n        folder = await get_or_create_default_folder(session, test_user_id)\\n        assert folder.name == DEFAULT_FOLDER_NAME, \\\"The project name should match the default.\\\"\\n        assert hasattr(folder, \\\"id\\\"), \\\"The project should have an 'id' attribute after creation.\\\"\\n\\n\\nasync def test_get_or_create_starter_folder_ignores_user_owned_name_collision(async_session) -> None:\\n    \\\"\\\"\\\"A user project named like the reserved project must not become the system Starter Project.\\\"\\\"\\\"\\n    user_folder = Folder(user_id=uuid4(), name=STARTER_FOLDER_NAME, description=\\\"User project\\\")\\n    async_session.add(user_folder)\\n    await async_session.flush()\\n\\n    starter_folder = await get_or_create_starter_folder(async_session)\\n\\n    assert starter_folder.user_id is None\\n    assert starter_folder.id != user_folder.id\\n    matching_folders = (await async_session.exec(select(Folder).where(Folder.name == STARTER_FOLDER_NAME))).all()\\n    assert {folder.id for folder in matching_folders} == {user_folder.id, starter_folder.id}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_get_or_create_default_folder_idempotency() -> None:\\n    \\\"\\\"\\\"Test that subsequent calls to get_or_create_default_folder return the same project.\\n\\n    The function should be idempotent such that if a default project already exists,\\n    calling the function again does not create a new one.\\n    \\\"\\\"\\\"\\n    test_user_id = uuid4()\\n    async with session_scope() as session:\\n        folder_first = await get_or_create_default_folder(session, test_user_id)\\n        folder_second = await get_or_create_default_folder(session, test_user_id)\\n        assert folder_first.id == folder_second.id, \\\"Both calls should return the same folder instance.\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_get_or_create_default_folder_concurrent_calls() -> None:\\n    \\\"\\\"\\\"Test concurrent invocations of get_or_create_default_folder.\\n\\n    This test ensures that when multiple concurrent calls are made for the same user,\\n    only one default project is created, demonstrating idempotency under concurrent access.\\n    \\\"\\\"\\\"\\n    test_user_id = uuid4()\\n\\n    async def get_folder() -> FolderRead:\\n        async with session_scope() as session:\\n            return await get_or_create_default_folder(session, test_user_id)\\n\\n    results = await asyncio.gather(get_folder(), get_folder(), get_folder())\\n    folder_ids = {folder.id for folder in results}\\n    assert len(folder_ids) == 1, \\\"Concurrent calls must return a single, consistent folder instance.\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_get_or_create_default_folder_respects_rename() -> None:\\n    \\\"\\\"\\\"Regression test: renaming the default folder must persist across calls.\\n\\n    Reproduces the reported bug where the server would recreate a \\\"Starter Project\\\" folder\\n    on every login or server restart, even though the user had already renamed it to something\\n    like \\\"My Flows\\\". After the fix, get_or_create_default_folder must detect the user's existing\\n    (renamed) folder and return it instead of forcing a new default folder back into the UI.\\n    \\\"\\\"\\\"\\n    test_user_id = uuid4()\\n    renamed_folder_name = \\\"My Flows\\\"\\n\\n    # First call creates the default folder.\\n    async with session_scope() as session:\\n        folder_first = await get_or_create_default_folder(session, test_user_id)\\n        assert folder_first.name == DEFAULT_FOLDER_NAME\\n        original_id = folder_first.id\\n\\n    # Simulate the user renaming the default folder from the UI.\\n    async with session_scope() as session:\\n        stmt = select(Folder).where(Folder.id == original_id)\\n        folder_row = (await session.exec(stmt)).first()\\n        assert folder_row is not None\\n        folder_row.name = renamed_folder_name\\n        session.add(folder_row)\\n        await session.flush()\\n\\n    # Second call (simulating next login / server restart) must honor the rename\\n    # rather than creating a new \\\"Starter Project\\\" alongside the renamed one.\\n    async with session_scope() as session:\\n        folder_second = await get_or_create_default_folder(session, test_user_id)\\n        assert folder_second.id == original_id, (\\n            \\\"The renamed folder should be returned instead of creating a new default.\\\"\\n        )\\n        assert folder_second.name == renamed_folder_name, (\\n            \\\"The folder's user-assigned name must be preserved across calls.\\\"\\n        )\\n\\n        # There should still be exactly one folder for this user \u2014 no phantom duplicate.\\n        all_folders_stmt = select(Folder).where(Folder.user_id == test_user_id)\\n        all_folders = (await session.exec(all_folders_stmt)).all()\\n        folder_names = sorted(f.name for f in all_folders)\\n        assert folder_names == [renamed_folder_name], (\\n            f\\\"Expected only the renamed folder to exist, found: {folder_names}\\\"\\n        )\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_get_or_create_default_folder_respects_other_existing_folder() -> None:\\n    \\\"\\\"\\\"Respect existing folders when the default folder is absent.\\n\\n    If the user already has any folder (e.g. they moved everything into 'Ideas' and\\n    deleted the default), we must not resurrect the default folder on the next call.\\n    \\\"\\\"\\\"\\n    test_user_id = uuid4()\\n    other_folder_name = \\\"Ideas\\\"\\n\\n    # Simulate an existing user who has a non-default folder but no \\\"Starter Project\\\".\\n    async with session_scope() as session:\\n        session.add(Folder(user_id=test_user_id, name=other_folder_name, description=\\\"My ideas\\\"))\\n        await session.flush()\\n\\n    async with session_scope() as session:\\n        returned = await get_or_create_default_folder(session, test_user_id)\\n        assert returned.name == other_folder_name, (\\n            \\\"Should return the user's existing folder rather than creating a new default.\\\"\\n        )\\n\\n        all_folders_stmt = select(Folder).where(Folder.user_id == test_user_id)\\n        all_folders = (await session.exec(all_folders_stmt)).all()\\n        folder_names = sorted(f.name for f in all_folders)\\n        assert folder_names == [other_folder_name], f\\\"No new default folder should be created; found: {folder_names}\\\"\\n\\n\\ndef _make_all_types_dict():\\n    \\\"\\\"\\\"Create a minimal all_types_dict for testing shared reference isolation.\\\"\\\"\\\"\\n    return {\\n        \\\"test_category\\\": {\\n            \\\"TestComponent\\\": {\\n                \\\"template\\\": {\\n                    \\\"_type\\\": \\\"Component\\\",\\n                    \\\"code\\\": {\\n                        \\\"type\\\": \\\"code\\\",\\n                        \\\"value\\\": \\\"original_code\\\",\\n                        \\\"advanced\\\": True,\\n                    },\\n                    \\\"field_a\\\": {\\n                        \\\"type\\\": \\\"str\\\",\\n                        \\\"value\\\": \\\"original_value\\\",\\n                        \\\"display_name\\\": \\\"Field A\\\",\\n                    },\\n                },\\n                \\\"outputs\\\": [{\\\"name\\\": \\\"out\\\", \\\"types\\\": [\\\"Message\\\"], \\\"selected\\\": \\\"Message\\\"}],\\n                \\\"description\\\": \\\"Test\\\",\\n                \\\"display_name\\\": \\\"Test\\\",\\n                \\\"beta\\\": False,\\n                \\\"metadata\\\": {\\\"key\\\": \\\"original_metadata\\\"},\\n            }\\n        }\\n    }\\n\\n\\ndef _make_project_data():\\n    \\\"\\\"\\\"Create minimal project data containing a TestComponent node.\\\"\\\"\\\"\\n    return {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"id\\\": \\\"TestComponent-abc\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"TestComponent\\\",\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"_type\\\": \\\"Component\\\",\\n                            \\\"code\\\": {\\n                                \\\"type\\\": \\\"code\\\",\\n                                \\\"value\\\": \\\"original_code\\\",\\n                                \\\"advanced\\\": True,\\n                            },\\n                            \\\"field_a\\\": {\\n                                \\\"type\\\": \\\"str\\\",\\n                                \\\"value\\\": \\\"my_custom_value\\\",\\n                                \\\"display_name\\\": \\\"Field A\\\",\\n                            },\\n                        },\\n                        \\\"outputs\\\": [{\\\"name\\\": \\\"out\\\", \\\"types\\\": [\\\"Message\\\"], \\\"selected\\\": \\\"Message\\\"}],\\n                        \\\"tool_mode\\\": False,\\n                    },\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n\\n\\ndef test_update_components_does_not_mutate_all_types_dict_via_code():\\n    \\\"\\\"\\\"Verify that modifying the returned project data's template code does not mutate all_types_dict.\\\"\\\"\\\"\\n    all_types_dict = _make_all_types_dict()\\n    snapshot = deepcopy(all_types_dict)\\n\\n    result = update_projects_components_with_latest_component_versions(_make_project_data(), all_types_dict)\\n\\n    # Mutate the returned data\\n    for node in result[\\\"nodes\\\"]:\\n        node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] = \\\"MUTATED!\\\"\\n\\n    assert all_types_dict == snapshot, \\\"all_types_dict must not be mutated by modifying the returned project data\\\"\\n\\n\\ndef test_update_components_does_not_mutate_all_types_dict_via_attrs():\\n    \\\"\\\"\\\"Verify that modifying returned project data's node attributes does not mutate all_types_dict.\\\"\\\"\\\"\\n    all_types_dict = _make_all_types_dict()\\n    snapshot = deepcopy(all_types_dict)\\n\\n    result = update_projects_components_with_latest_component_versions(_make_project_data(), all_types_dict)\\n\\n    # Mutate a NODE_FORMAT_ATTRIBUTE on the returned data\\n    for node in result[\\\"nodes\\\"]:\\n        node_data = node[\\\"data\\\"][\\\"node\\\"]\\n        if \\\"metadata\\\" in node_data:\\n            node_data[\\\"metadata\\\"][\\\"key\\\"] = \\\"MUTATED!\\\"\\n\\n    assert all_types_dict == snapshot, \\\"all_types_dict must not be mutated via node format attributes\\\"\\n\\n\\ndef test_update_components_does_not_leak_between_projects():\\n    \\\"\\\"\\\"Verify that processing one project does not affect the next project's results.\\\"\\\"\\\"\\n    all_types_dict = _make_all_types_dict()\\n\\n    # Process first project and mutate its result\\n    result_a = update_projects_components_with_latest_component_versions(_make_project_data(), all_types_dict)\\n    for node in result_a[\\\"nodes\\\"]:\\n        node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] = \\\"MUTATED_BY_A!\\\"\\n\\n    # Process second project \u2014 should get original values\\n    result_b = update_projects_components_with_latest_component_versions(_make_project_data(), all_types_dict)\\n    for node in result_b[\\\"nodes\\\"]:\\n        code_value = node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n        assert code_value == \\\"original_code\\\", (\\n            f\\\"Second project got '{code_value}' instead of 'original_code' \u2014 \\\"\\n            \\\"mutation from first project leaked via all_types_dict\\\"\\n        )\\n\\n\\ndef test_update_components_does_not_mutate_when_type_changes():\\n    \\\"\\\"\\\"Verify no shared refs when _type differs and the full template is replaced.\\\"\\\"\\\"\\n    all_types_dict = _make_all_types_dict()\\n    snapshot = deepcopy(all_types_dict)\\n\\n    # Create project data with a different _type to trigger the full template replacement path\\n    project_data = _make_project_data()\\n    project_data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"_type\\\"] = \\\"OldType\\\"\\n\\n    result = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n\\n    # Mutate the returned data's template\\n    for node in result[\\\"nodes\\\"]:\\n        node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] = \\\"MUTATED!\\\"\\n\\n    assert all_types_dict == snapshot, (\\n        \\\"all_types_dict must not be mutated when _type differs and full template is replaced\\\"\\n    )\\n\\n\\ndef test_update_components_does_not_mutate_field_format_attributes():\\n    \\\"\\\"\\\"Verify that mutable FIELD_FORMAT_ATTRIBUTES (e.g. input_types) are deepcopied, not shared.\\\"\\\"\\\"\\n    all_types_dict = {\\n        \\\"test_category\\\": {\\n            \\\"TestComponent\\\": {\\n                \\\"template\\\": {\\n                    \\\"_type\\\": \\\"Component\\\",\\n                    \\\"code\\\": {\\\"type\\\": \\\"code\\\", \\\"value\\\": \\\"original_code\\\", \\\"advanced\\\": True},\\n                    \\\"field_a\\\": {\\n                        \\\"type\\\": \\\"str\\\",\\n                        \\\"value\\\": \\\"original_value\\\",\\n                        \\\"display_name\\\": \\\"Field A\\\",\\n                        \\\"input_types\\\": [\\\"Message\\\"],\\n                    },\\n                },\\n                \\\"outputs\\\": [{\\\"name\\\": \\\"out\\\", \\\"types\\\": [\\\"Message\\\"], \\\"selected\\\": \\\"Message\\\"}],\\n                \\\"description\\\": \\\"Test\\\",\\n                \\\"display_name\\\": \\\"Test\\\",\\n                \\\"beta\\\": False,\\n            }\\n        }\\n    }\\n    snapshot = deepcopy(all_types_dict)\\n\\n    # Project has a different input_types so the FIELD_FORMAT_ATTRIBUTES path is triggered\\n    project_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"id\\\": \\\"TestComponent-abc\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"TestComponent\\\",\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"_type\\\": \\\"Component\\\",\\n                            \\\"code\\\": {\\\"type\\\": \\\"code\\\", \\\"value\\\": \\\"original_code\\\", \\\"advanced\\\": True},\\n                            \\\"field_a\\\": {\\n                                \\\"type\\\": \\\"str\\\",\\n                                \\\"value\\\": \\\"my_custom_value\\\",\\n                                \\\"display_name\\\": \\\"Field A\\\",\\n                                \\\"input_types\\\": [\\\"Data\\\"],  # differs \u2192 triggers attr update at line 192\\n                            },\\n                        },\\n                        \\\"outputs\\\": [{\\\"name\\\": \\\"out\\\", \\\"types\\\": [\\\"Message\\\"], \\\"selected\\\": \\\"Message\\\"}],\\n                        \\\"tool_mode\\\": False,\\n                    },\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n\\n    result = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n\\n    # Mutate the returned mutable field attribute\\n    for node in result[\\\"nodes\\\"]:\\n        node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"field_a\\\"][\\\"input_types\\\"].append(\\\"MUTATED!\\\")\\n\\n    assert all_types_dict == snapshot, (\\n        \\\"all_types_dict must not be mutated via mutable FIELD_FORMAT_ATTRIBUTES (e.g. input_types)\\\"\\n    )\\n\\n\\ndef _with_metadata(project_metadata, latest_metadata):\\n    \\\"\\\"\\\"Build (project_data, all_types_dict) pairs carrying the given node metadata.\\\"\\\"\\\"\\n    all_types_dict = _make_all_types_dict()\\n    all_types_dict[\\\"test_category\\\"][\\\"TestComponent\\\"][\\\"metadata\\\"] = latest_metadata\\n    project_data = _make_project_data()\\n    project_data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"metadata\\\"] = project_metadata\\n    return project_data, all_types_dict\\n\\n\\ndef test_update_components_preserves_importable_module_over_runtime_ext_namespace():\\n    \\\"\\\"\\\"A runtime ``_lfx_ext.*`` module from the live template must not be persisted.\\n\\n    The live template of a moved (ext) component reports its runtime\\n    ``_lfx_ext.*`` module, which is not importable outside a running extension\\n    loader. The updater must keep the node's stored legacy path (the bundle\\n    shims keep it importable, and the migration table + template tests resolve\\n    it) while still syncing the rest of the metadata.\\n    \\\"\\\"\\\"\\n    project_data, all_types_dict = _with_metadata(\\n        project_metadata={\\\"module\\\": \\\"lfx.components.test.test_component.TestComponent\\\"},\\n        latest_metadata={\\\"module\\\": \\\"_lfx_ext.official.test.test_component\\\", \\\"dependencies\\\": [\\\"dep\\\"]},\\n    )\\n\\n    result = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n\\n    merged = result[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"metadata\\\"]\\n    assert merged[\\\"module\\\"] == \\\"lfx.components.test.test_component.TestComponent\\\"\\n    assert merged[\\\"dependencies\\\"] == [\\\"dep\\\"]\\n\\n\\ndef test_update_components_syncs_module_for_in_tree_components():\\n    \\\"\\\"\\\"A normal (importable) module path from the live template still syncs.\\\"\\\"\\\"\\n    project_data, all_types_dict = _with_metadata(\\n        project_metadata={\\\"module\\\": \\\"lfx.components.test.old_location.TestComponent\\\"},\\n        latest_metadata={\\\"module\\\": \\\"lfx.components.test.test_component.TestComponent\\\"},\\n    )\\n\\n    result = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n\\n    merged = result[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"metadata\\\"]\\n    assert merged[\\\"module\\\"] == \\\"lfx.components.test.test_component.TestComponent\\\"\\n\\n\\ndef test_update_components_syncs_metadata_for_skipped_language_model():\\n    \\\"\\\"\\\"Refreshing skipped dynamic components must keep source metadata consistent.\\\"\\\"\\\"\\n    project_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"LanguageModelComponent\\\",\\n                    \\\"node\\\": {\\n                        \\\"metadata\\\": {\\\"code_hash\\\": \\\"old-hash\\\", \\\"module\\\": \\\"old.module\\\"},\\n                        \\\"template\\\": {\\n                            \\\"_type\\\": \\\"Component\\\",\\n                            \\\"code\\\": {\\\"type\\\": \\\"code\\\", \\\"value\\\": \\\"old source\\\"},\\n                            \\\"model\\\": {\\\"value\\\": \\\"persisted-model\\\"},\\n                        },\\n                    },\\n                }\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n    all_types_dict = {\\n        \\\"models_and_agents\\\": {\\n            \\\"LanguageModelComponent\\\": {\\n                \\\"metadata\\\": {\\\"code_hash\\\": \\\"new-hash\\\", \\\"module\\\": \\\"new.module\\\"},\\n                \\\"template\\\": {\\n                    \\\"_type\\\": \\\"Component\\\",\\n                    \\\"code\\\": {\\\"type\\\": \\\"code\\\", \\\"value\\\": \\\"new source\\\"},\\n                    \\\"model\\\": {\\\"value\\\": \\\"default-model\\\"},\\n                },\\n            }\\n        }\\n    }\\n\\n    result = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n    node = result[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"]\\n\\n    assert node[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == \\\"new source\\\"\\n    assert node[\\\"template\\\"][\\\"model\\\"][\\\"value\\\"] == \\\"persisted-model\\\"\\n    assert node[\\\"metadata\\\"] == {\\\"code_hash\\\": \\\"new-hash\\\", \\\"module\\\": \\\"new.module\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/initial_setup/test_starter_projects_mcp_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"33709ddbb75a0b685e36848dd5966f56ae1a8c7630ec785d45f2f33e6b15f71a\",\"content\":\"\\\"\\\"\\\"Regression guard: shipped starter projects must advertise their inputs over MCP.\\n\\nA project's flows are published on its MCP server, and the very first flow a new user creates comes\\nfrom this template picker. ``api_editable`` \u2014 the Inspector's per-field \\\"API\\\" toggle \u2014 defaults to\\nFalse, is written only by the frontend, and has no backfill, so gating the advertised schema on it\\nwithout a per-flow fallback publishes every one of these templates with an input schema containing\\nnothing but the optional ``session_id``. The failure is silent at both ends: the tool call returns\\n``isError: false`` with empty content and the flow runs on an empty message.\\n\\nThese tests are file-system level on purpose: they read the shipped JSON the same way the seeder\\ndoes at first boot, then run the real ``tools/list`` schema derivation over it.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom langflow.helpers.flow import json_schema_from_flow\\nfrom lfx.graph.schema import INPUT_COMPONENTS\\n\\nSTARTER_PROJECTS_DIR = Path(__file__).resolve().parents[3] / \\\"base\\\" / \\\"langflow\\\" / \\\"initial_setup\\\" / \\\"starter_projects\\\"\\n\\n\\ndef _starter_project_files() -> list[Path]:\\n    if not STARTER_PROJECTS_DIR.is_dir():\\n        msg = f\\\"starter_projects directory not found at {STARTER_PROJECTS_DIR}\\\"\\n        raise FileNotFoundError(msg)\\n    return sorted(STARTER_PROJECTS_DIR.glob(\\\"*.json\\\"))\\n\\n\\ndef _input_node_types(flow_data: dict) -> list[str]:\\n    return [\\n        node.get(\\\"data\\\", {}).get(\\\"type\\\")\\n        for node in flow_data.get(\\\"nodes\\\", [])\\n        if node.get(\\\"data\\\", {}).get(\\\"type\\\") in INPUT_COMPONENTS\\n    ]\\n\\n\\n@pytest.mark.parametrize(\\\"starter_path\\\", _starter_project_files(), ids=lambda path: path.stem)\\ndef test_starter_project_advertises_its_flow_inputs_over_mcp(starter_path: Path):\\n    \\\"\\\"\\\"A shipped template with an input node must advertise more than the injected session_id.\\\"\\\"\\\"\\n    flow_data = json.loads(starter_path.read_text(encoding=\\\"utf-8\\\")).get(\\\"data\\\") or {}\\n    input_types = _input_node_types(flow_data)\\n    if not input_types:\\n        pytest.skip(f\\\"{starter_path.stem} has no input component; MCP has nothing to advertise\\\")\\n\\n    schema = json_schema_from_flow(SimpleNamespace(data=flow_data))\\n    advertised = set(schema[\\\"properties\\\"]) - {\\\"session_id\\\"}\\n\\n    assert advertised, (\\n        f\\\"{starter_path.stem} publishes an MCP tool whose only input is the optional session_id. \\\"\\n        f\\\"A caller obeying that schema runs the flow with no message.\\\"\\n    )\\n    if \\\"ChatInput\\\" in input_types:\\n        assert \\\"input_value\\\" in advertised, (\\n            f\\\"{starter_path.stem} accepts input_value at call time but does not advertise it.\\\"\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/initial_setup/test_starter_projects_streaming.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5881df35b2ccaa7d4aa420d0b6eb6d7a7d7078abd6f81b1122b2c825a4f5a2c7\",\"content\":\"\\\"\\\"\\\"Regression guards for streaming wiring inside bundled starter projects.\\n\\nEvery starter project that ships an ``Agent`` node MUST embed the post-PR-13358\\n``AgentComponent`` code \u2014 the one whose ``_get_llm`` hard-codes ``stream=True``.\\nWithout this, users importing a starter template inherit the legacy streaming\\nbug (``openrag_agent.json``-class regression) on the very first flow they\\nencounter inside Langflow, before the backward-compat shim in\\n``ToolCallingAgentComponent`` even has a chance to kick in (it covers the\\nToolCallingAgent-Classic path; starter projects targeting the modern LangGraph\\n``AgentComponent`` build a different runnable, so the shim does NOT apply).\\n\\nThese tests are intentionally file-system level: they read the shipped JSON\\ntemplates directly, the same way the seeder does at first boot.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nSTARTER_PROJECTS_DIR = Path(__file__).resolve().parents[3] / \\\"base\\\" / \\\"langflow\\\" / \\\"initial_setup\\\" / \\\"starter_projects\\\"\\nBUNDLE_STARTER_PROJECTS_DIR = Path(__file__).resolve().parents[4] / \\\"bundles\\\"\\n\\n\\ndef _starter_project_files() -> list[Path]:\\n    if not STARTER_PROJECTS_DIR.is_dir():\\n        msg = f\\\"starter_projects directory not found at {STARTER_PROJECTS_DIR}\\\"\\n        raise FileNotFoundError(msg)\\n    return sorted(\\n        [\\n            *STARTER_PROJECTS_DIR.glob(\\\"*.json\\\"),\\n            *BUNDLE_STARTER_PROJECTS_DIR.glob(\\\"**/starter_projects/*.json\\\"),\\n        ]\\n    )\\n\\n\\ndef _agent_nodes_in(path: Path) -> list[dict]:\\n    flow = json.loads(path.read_text(encoding=\\\"utf-8\\\"))\\n    return [n for n in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []) if n.get(\\\"data\\\", {}).get(\\\"type\\\") == \\\"Agent\\\"]\\n\\n\\ndef test_should_find_at_least_one_agent_starter_project_so_other_tests_are_meaningful():\\n    \\\"\\\"\\\"Smoke test: if no Agent node is found, the rest of this file is vacuous.\\n\\n    Catches an accidental refactor that renames the ``Agent`` node type\\n    string (e.g. to ``AgentV2``) \u2014 which would otherwise let these scans\\n    silently skip every flow.\\n    \\\"\\\"\\\"\\n    files = _starter_project_files()\\n    total_agents = sum(len(_agent_nodes_in(fp)) for fp in files)\\n    assert total_agents > 0, (\\n        f\\\"Expected at least one Agent node across {len(files)} starter projects. \\\"\\n        \\\"If the node type string changed, update _agent_nodes_in().\\\"\\n    )\\n\\n\\n@pytest.mark.parametrize(\\\"starter_path\\\", _starter_project_files(), ids=lambda p: p.name)\\ndef test_should_embed_stream_true_in_get_llm_when_starter_project_contains_agent(starter_path: Path):\\n    r\\\"\\\"\\\"Every bundled Agent must ship ``_get_llm`` that hard-codes ``stream=True``.\\n\\n    The starter project JSONs embed a frozen snapshot of the ``AgentComponent``\\n    class body in ``template['code']['value']``. Langflow ``exec``\\\\s that snapshot\\n    when the flow loads, so a stale snapshot bypasses any fix made in the live\\n    ``agent.py`` source \u2014 exactly the regression that broke ``openrag_agent.json``\\n    (code_hash ``154c71cf7441``) and prompted the backward-compat shim in\\n    ``ToolCallingAgentComponent``.\\n    \\\"\\\"\\\"\\n    agent_nodes = _agent_nodes_in(starter_path)\\n    if not agent_nodes:\\n        pytest.skip(f\\\"{starter_path.name} has no Agent node\\\")\\n\\n    for idx, node in enumerate(agent_nodes):\\n        template = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n        code_entry = template.get(\\\"code\\\", {})\\n        code_value = code_entry.get(\\\"value\\\", \\\"\\\") if isinstance(code_entry, dict) else \\\"\\\"\\n\\n        assert \\\"def _get_llm\\\" in code_value, (\\n            f\\\"{starter_path.name}[Agent#{idx}] does not embed _get_llm \u2014 the bundled AgentComponent code is malformed.\\\"\\n        )\\n        assert \\\"stream=True\\\" in code_value, (\\n            f\\\"{starter_path.name}[Agent#{idx}] embeds an AgentComponent whose \\\"\\n            \\\"_get_llm() does NOT hard-code stream=True. The starter project is stale; \\\"\\n            \\\"regenerate it from the live AgentComponent class. Without this, \\\"\\n            \\\"loading the starter template silently disables Playground streaming.\\\"\\n        )\\n\\n\\n@pytest.mark.parametrize(\\\"starter_path\\\", _starter_project_files(), ids=lambda p: p.name)\\ndef test_should_share_same_agent_code_hash_across_starter_projects(starter_path: Path):\\n    \\\"\\\"\\\"All bundled Agents must share a single code_hash.\\n\\n    Drift between starter projects (e.g. one bundles the new agent.py, another\\n    still bundles the pre-#13358 version) creates a confusing UX where some\\n    templates stream and others don't. A single hash is the cheapest invariant\\n    to assert.\\n    \\\"\\\"\\\"\\n    agent_nodes = _agent_nodes_in(starter_path)\\n    if not agent_nodes:\\n        pytest.skip(f\\\"{starter_path.name} has no Agent node\\\")\\n\\n    # Collect hashes from every starter project at module level.\\n    all_hashes: set[str] = set()\\n    for fp in _starter_project_files():\\n        for node in _agent_nodes_in(fp):\\n            ch = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"metadata\\\", {}).get(\\\"code_hash\\\")\\n            if ch:\\n                all_hashes.add(ch)\\n\\n    assert len(all_hashes) == 1, (\\n        f\\\"Starter projects bundle {len(all_hashes)} distinct Agent code_hashes: \\\"\\n        f\\\"{sorted(all_hashes)!r}. Regenerate the stale templates so streaming behavior \\\"\\n        \\\"is consistent across all bundled flows.\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/inputs/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/inputs/test_inputs.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e6ceba007f904b775c6d67484380a3cf0ac32d0c0ba544175f85be5f98bccf6c\",\"content\":\"import pytest\\nfrom lfx.inputs.inputs import (\\n    BoolInput,\\n    CodeInput,\\n    DataInput,\\n    DictInput,\\n    DropdownInput,\\n    FileInput,\\n    FloatInput,\\n    HandleInput,\\n    InputTypesMap,\\n    IntInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    MultilineSecretInput,\\n    MultiselectInput,\\n    NestedDictInput,\\n    PromptInput,\\n    SecretStrInput,\\n    SliderInput,\\n    StrInput,\\n    TabInput,\\n    TableInput,\\n    instantiate_input,\\n)\\nfrom lfx.schema.message import Message\\nfrom pydantic import ValidationError\\n\\n\\ndef test_table_input_valid():\\n    data = TableInput(name=\\\"valid_table\\\", value=[{\\\"key\\\": \\\"value\\\"}, {\\\"key2\\\": \\\"value2\\\"}])\\n    assert data.value == [{\\\"key\\\": \\\"value\\\"}, {\\\"key2\\\": \\\"value2\\\"}]\\n\\n\\ndef test_slider_input_valid():\\n    data = SliderInput(name=\\\"valid_slider\\\", value=10)\\n    assert data.value == 10\\n\\n\\ndef test_table_input_invalid():\\n    with pytest.raises(ValidationError):\\n        TableInput(name=\\\"invalid_table\\\", value=\\\"invalid\\\")\\n\\n    with pytest.raises(ValidationError):\\n        TableInput(name=\\\"invalid_table\\\", value=[{\\\"key\\\": \\\"value\\\"}, \\\"invalid\\\"])\\n\\n\\ndef test_str_input_valid():\\n    data = StrInput(name=\\\"valid_str\\\", value=\\\"This is a string\\\")\\n    assert data.value == \\\"This is a string\\\"\\n\\n\\ndef test_str_input_invalid():\\n    with pytest.warns(UserWarning, match=\\\"Invalid value type.*for input\\\"):\\n        StrInput(name=\\\"invalid_str\\\", value=1234)\\n\\n\\ndef test_message_text_input_valid():\\n    data = MessageTextInput(name=\\\"valid_msg\\\", value=\\\"This is a message\\\")\\n    assert data.value == \\\"This is a message\\\"\\n\\n    msg = Message(text=\\\"This is a message\\\")\\n    data = MessageTextInput(name=\\\"valid_msg\\\", value=msg)\\n    assert data.value == \\\"This is a message\\\"\\n\\n\\ndef test_message_text_input_invalid():\\n    with pytest.raises(ValidationError):\\n        MessageTextInput(name=\\\"invalid_msg\\\", value=1234)\\n\\n\\ndef test_instantiate_input_valid():\\n    data = {\\\"name\\\": \\\"valid_input\\\", \\\"value\\\": \\\"This is a string\\\"}\\n    input_instance = instantiate_input(\\\"StrInput\\\", data)\\n    assert isinstance(input_instance, StrInput)\\n    assert input_instance.value == \\\"This is a string\\\"\\n\\n\\ndef test_instantiate_input_invalid():\\n    with pytest.raises(ValueError, match=\\\"Invalid input type: InvalidInput\\\"):\\n        instantiate_input(\\\"InvalidInput\\\", {\\\"name\\\": \\\"invalid_input\\\", \\\"value\\\": \\\"This is a string\\\"})\\n\\n\\ndef test_handle_input_valid():\\n    data = HandleInput(name=\\\"valid_handle\\\", input_types=[\\\"BaseLanguageModel\\\"])\\n    assert data.input_types == [\\\"BaseLanguageModel\\\"]\\n\\n\\ndef test_handle_input_invalid():\\n    with pytest.raises(ValidationError):\\n        HandleInput(name=\\\"invalid_handle\\\", input_types=\\\"BaseLanguageModel\\\")\\n\\n\\ndef test_data_input_valid():\\n    data_input = DataInput(name=\\\"valid_data\\\", input_types=[\\\"Data\\\"])\\n    assert data_input.input_types == [\\\"Data\\\"]\\n\\n\\ndef test_prompt_input_valid():\\n    prompt_input = PromptInput(name=\\\"valid_prompt\\\", value=\\\"Enter your name\\\")\\n    assert prompt_input.value == \\\"Enter your name\\\"\\n\\n\\ndef test_code_input_valid():\\n    code_input = CodeInput(name=\\\"valid_code\\\", value=\\\"def hello():\\\\n    print('Hello, World!')\\\")\\n    assert code_input.value == \\\"def hello():\\\\n    print('Hello, World!')\\\"\\n\\n\\ndef test_multiline_input_valid():\\n    multiline_input = MultilineInput(name=\\\"valid_multiline\\\", value=\\\"This is a\\\\nmultiline input\\\")\\n    assert multiline_input.value == \\\"This is a\\\\nmultiline input\\\"\\n    assert multiline_input.multiline is True\\n\\n\\ndef test_multiline_input_invalid():\\n    with pytest.raises(ValidationError):\\n        MultilineInput(name=\\\"invalid_multiline\\\", value=1234)\\n\\n\\ndef test_multiline_secret_input_valid():\\n    multiline_secret_input = MultilineSecretInput(name=\\\"valid_multiline_secret\\\", value=\\\"secret\\\")\\n    assert multiline_secret_input.value == \\\"secret\\\"\\n    assert multiline_secret_input.password is True\\n\\n\\ndef test_multiline_secret_input_invalid():\\n    with pytest.raises(ValidationError):\\n        MultilineSecretInput(name=\\\"invalid_multiline_secret\\\", value=1234)\\n\\n\\ndef test_secret_str_input_valid():\\n    secret_str_input = SecretStrInput(name=\\\"valid_secret_str\\\", value=\\\"supersecret\\\")\\n    assert secret_str_input.value == \\\"supersecret\\\"\\n    assert secret_str_input.password is True\\n\\n\\ndef test_secret_str_input_invalid():\\n    with pytest.raises(ValidationError):\\n        SecretStrInput(name=\\\"invalid_secret_str\\\", value=1234)\\n\\n\\ndef test_int_input_valid():\\n    int_input = IntInput(name=\\\"valid_int\\\", value=10)\\n    assert int_input.value == 10\\n\\n\\ndef test_int_input_invalid():\\n    with pytest.raises(ValidationError):\\n        IntInput(name=\\\"invalid_int\\\", value=\\\"not_an_int\\\")\\n\\n\\ndef test_float_input_valid():\\n    float_input = FloatInput(name=\\\"valid_float\\\", value=10.5)\\n    assert float_input.value == 10.5\\n\\n\\ndef test_float_input_invalid():\\n    with pytest.raises(ValidationError):\\n        FloatInput(name=\\\"invalid_float\\\", value=\\\"not_a_float\\\")\\n\\n\\ndef test_bool_input_valid():\\n    bool_input = BoolInput(name=\\\"valid_bool\\\", value=True)\\n    assert bool_input.value is True\\n\\n\\ndef test_bool_input_invalid():\\n    with pytest.raises(ValidationError):\\n        BoolInput(name=\\\"invalid_bool\\\", value=\\\"not_a_bool\\\")\\n\\n\\ndef test_bool_input_accepts_message():\\n    \\\"\\\"\\\"Regression test for #9424.\\n\\n    BoolInput must coerce Message values so that MCP-tool boolean fields can be\\n    wired from Message-producing components.\\n    \\\"\\\"\\\"\\n    bool_input = BoolInput(name=\\\"bool_from_message\\\", value=Message(text=\\\"true\\\"))\\n    assert bool_input.value is True\\n\\n    bool_input_false = BoolInput(name=\\\"bool_from_message_false\\\", value=Message(text=\\\"false\\\"))\\n    assert bool_input_false.value is False\\n\\n\\ndef test_nested_dict_input_valid():\\n    nested_dict_input = NestedDictInput(name=\\\"valid_nested_dict\\\", value={\\\"key\\\": \\\"value\\\"})\\n    assert nested_dict_input.value == {\\\"key\\\": \\\"value\\\"}\\n\\n\\ndef test_nested_dict_input_invalid():\\n    with pytest.raises(ValidationError):\\n        NestedDictInput(name=\\\"invalid_nested_dict\\\", value=\\\"not_a_dict\\\")\\n\\n\\ndef test_dict_input_valid():\\n    dict_input = DictInput(name=\\\"valid_dict\\\", value={\\\"key\\\": \\\"value\\\"})\\n    assert dict_input.value == {\\\"key\\\": \\\"value\\\"}\\n\\n\\ndef test_dict_input_invalid():\\n    with pytest.raises(ValidationError):\\n        DictInput(name=\\\"invalid_dict\\\", value=\\\"not_a_dict\\\")\\n\\n\\ndef test_dict_input_accepts_json_message():\\n    \\\"\\\"\\\"Regression test for #9424.\\n\\n    DictInput must accept Message/JSON-string payloads so MCP-tool dict/JSON\\n    fields can be wired from upstream components.\\n    \\\"\\\"\\\"\\n    dict_input = DictInput(name=\\\"dict_from_message\\\", value=Message(text='{\\\"k\\\": \\\"v\\\"}'))\\n    assert dict_input.value == {\\\"k\\\": \\\"v\\\"}\\n\\n\\ndef test_dropdown_input_valid():\\n    dropdown_input = DropdownInput(name=\\\"valid_dropdown\\\", options=[\\\"option1\\\", \\\"option2\\\"])\\n    assert dropdown_input.options == [\\\"option1\\\", \\\"option2\\\"]\\n\\n\\ndef test_dropdown_input_invalid():\\n    with pytest.raises(ValidationError):\\n        DropdownInput(name=\\\"invalid_dropdown\\\", options=\\\"option1\\\")\\n\\n\\ndef test_multiselect_input_valid():\\n    multiselect_input = MultiselectInput(name=\\\"valid_multiselect\\\", value=[\\\"option1\\\", \\\"option2\\\"])\\n    assert multiselect_input.value == [\\\"option1\\\", \\\"option2\\\"]\\n\\n\\ndef test_multiselect_input_invalid():\\n    with pytest.raises(ValidationError):\\n        MultiselectInput(name=\\\"invalid_multiselect\\\", value=\\\"option1\\\")\\n\\n\\ndef test_file_input_valid():\\n    file_input = FileInput(name=\\\"valid_file\\\", value=[\\\"/path/to/file\\\"])\\n    assert file_input.value == [\\\"/path/to/file\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"test_id\\\", \\\"options\\\", \\\"value\\\", \\\"expected_options\\\", \\\"expected_value\\\"),\\n    [\\n        (\\n            \\\"standard_valid\\\",\\n            [\\\"Tab1\\\", \\\"Tab2\\\", \\\"Tab3\\\"],\\n            \\\"Tab1\\\",\\n            [\\\"Tab1\\\", \\\"Tab2\\\", \\\"Tab3\\\"],\\n            \\\"Tab1\\\",\\n        ),\\n        (\\n            \\\"fewer_options\\\",\\n            [\\\"Tab1\\\", \\\"Tab2\\\"],\\n            \\\"Tab2\\\",\\n            [\\\"Tab1\\\", \\\"Tab2\\\"],\\n            \\\"Tab2\\\",\\n        ),\\n        (\\n            \\\"empty_options\\\",\\n            [],\\n            \\\"\\\",\\n            [],\\n            \\\"\\\",\\n        ),\\n    ],\\n)\\ndef test_tab_input_valid(test_id, options, value, expected_options, expected_value):\\n    \\\"\\\"\\\"Test TabInput validation with valid inputs.\\\"\\\"\\\"\\n    data = TabInput(\\n        name=f\\\"valid_tab_{test_id}\\\",\\n        options=options,\\n        value=value,\\n    )\\n    assert data.options == expected_options\\n    assert data.value == expected_value\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"test_id\\\", \\\"options\\\", \\\"value\\\", \\\"error_expected\\\"),\\n    [\\n        (\\n            \\\"too_many_options\\\",\\n            [\\\"Tab1\\\", \\\"Tab2\\\", \\\"Tab3\\\", \\\"Tab4\\\"],\\n            \\\"Tab1\\\",\\n            ValidationError,\\n        ),\\n        (\\n            \\\"option_too_long\\\",\\n            [\\n                \\\"Tab1\\\",\\n                \\\"ThisTabValueIsTooLongAndExceedsTwentyCharacters\\\",\\n                \\\"Tab3\\\",\\n            ],\\n            \\\"Tab1\\\",\\n            ValidationError,\\n        ),\\n        (\\n            \\\"non_string_value\\\",\\n            [\\\"Tab1\\\", \\\"Tab2\\\", \\\"Tab3\\\"],\\n            123,\\n            TypeError,\\n        ),\\n    ],\\n)\\ndef test_tab_input_invalid(test_id, options, value, error_expected):\\n    \\\"\\\"\\\"Test TabInput validation with invalid inputs.\\\"\\\"\\\"\\n    if error_expected:\\n        with pytest.raises(error_expected):\\n            TabInput(\\n                name=f\\\"invalid_tab_{test_id}\\\",\\n                options=options,\\n                value=value,\\n            )\\n\\n\\ndef test_instantiate_input_comprehensive():\\n    valid_data = {\\n        \\\"StrInput\\\": {\\\"name\\\": \\\"str_input\\\", \\\"value\\\": \\\"A string\\\"},\\n        \\\"IntInput\\\": {\\\"name\\\": \\\"int_input\\\", \\\"value\\\": 10},\\n        \\\"FloatInput\\\": {\\\"name\\\": \\\"float_input\\\", \\\"value\\\": 10.5},\\n        \\\"BoolInput\\\": {\\\"name\\\": \\\"bool_input\\\", \\\"value\\\": True},\\n        \\\"DictInput\\\": {\\\"name\\\": \\\"dict_input\\\", \\\"value\\\": {\\\"key\\\": \\\"value\\\"}},\\n        \\\"MultiselectInput\\\": {\\n            \\\"name\\\": \\\"multiselect_input\\\",\\n            \\\"value\\\": [\\\"option1\\\", \\\"option2\\\"],\\n        },\\n        \\\"TabInput\\\": {\\n            \\\"name\\\": \\\"tab_input\\\",\\n            \\\"options\\\": [\\\"Tab1\\\", \\\"Tab2\\\", \\\"Tab3\\\"],\\n            \\\"value\\\": \\\"Tab1\\\",\\n        },\\n    }\\n\\n    for input_type, data in valid_data.items():\\n        input_instance = instantiate_input(input_type, data)\\n        assert isinstance(input_instance, InputTypesMap[input_type])\\n\\n    with pytest.raises(ValueError, match=\\\"Invalid input type: InvalidInput\\\"):\\n        instantiate_input(\\\"InvalidInput\\\", {\\\"name\\\": \\\"invalid_input\\\", \\\"value\\\": \\\"Invalid\\\"})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/interface/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6bea06ee8ae326d38039119fc8357ed2d35fd5dc4014793cbd6ec702e5a5d274\",\"content\":\"# Unit tests for interface module\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/interface/initialize/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e8b2d8a150d1f1b8a460dad80d1de930c875cd024e0bb1e1328c0e3187f4dd6d\",\"content\":\"# Unit tests for initialize module\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/interface/initialize/test_loading.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a24846671c348b316b118162a49e2890e122e8562170842621a3bef4a72701c0\",\"content\":\"import os\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.interface.initialize.loading import (\\n    update_params_with_load_from_db_fields,\\n    update_table_params_with_load_from_db_fields,\\n)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_params_fallback_to_env_when_variable_not_found():\\n    \\\"\\\"\\\"Test that when a variable is not found in database and fallback_to_env_vars is True.\\n\\n    It falls back to environment variables. This specifically tests the fix for the bug\\n    where 'variable not found.' error would always raise, even with fallback enabled.\\n    \\\"\\\"\\\"\\n    # Set up environment variable\\n    os.environ[\\\"TEST_API_KEY\\\"] = \\\"test-secret-key-123\\\"\\n\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n    # Use \\\"variable not found.\\\" error to specifically test the fix\\n    # Previously this would always raise, even with fallback_to_env_vars=True\\n    custom_component.get_variable = AsyncMock(side_effect=ValueError(\\\"TEST_API_KEY variable not found.\\\"))\\n\\n    # Set up params with a field that should load from db\\n    params = {\\\"api_key\\\": \\\"TEST_API_KEY\\\"}\\n    load_from_db_fields = [\\\"api_key\\\"]\\n\\n    # Call the function with fallback enabled\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_params_with_load_from_db_fields(\\n            custom_component, params, load_from_db_fields, fallback_to_env_vars=True\\n        )\\n\\n    # Should have fallen back to environment variable\\n    assert result[\\\"api_key\\\"] == \\\"test-secret-key-123\\\"\\n\\n    # Clean up\\n    del os.environ[\\\"TEST_API_KEY\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_params_raises_when_variable_not_found_and_no_fallback():\\n    \\\"\\\"\\\"Test that when a variable is not found and fallback_to_env_vars is False.\\n\\n    It raises the error.\\n    \\\"\\\"\\\"\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n    custom_component.get_variable = AsyncMock(side_effect=ValueError(\\\"TEST_API_KEY variable not found.\\\"))\\n\\n    # Set up params\\n    params = {\\\"api_key\\\": \\\"TEST_API_KEY\\\"}\\n    load_from_db_fields = [\\\"api_key\\\"]\\n\\n    # Call the function with fallback disabled\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        with pytest.raises(ValueError, match=\\\"TEST_API_KEY variable not found\\\"):\\n            await update_params_with_load_from_db_fields(\\n                custom_component, params, load_from_db_fields, fallback_to_env_vars=False\\n            )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_params_uses_database_variable_when_found():\\n    \\\"\\\"\\\"Test that when a variable is found in database, it uses that value.\\n\\n    It doesn't check environment variables.\\n    \\\"\\\"\\\"\\n    # Set up environment variable (should not be used)\\n    os.environ[\\\"TEST_API_KEY\\\"] = \\\"env-value\\\"\\n\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n    custom_component.get_variable = AsyncMock(return_value=\\\"db-value\\\")\\n\\n    # Set up params\\n    params = {\\\"api_key\\\": \\\"TEST_API_KEY\\\"}\\n    load_from_db_fields = [\\\"api_key\\\"]\\n\\n    # Call the function\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_params_with_load_from_db_fields(\\n            custom_component, params, load_from_db_fields, fallback_to_env_vars=True\\n        )\\n\\n    # Should use database value, not environment value\\n    assert result[\\\"api_key\\\"] == \\\"db-value\\\"\\n\\n    # Clean up\\n    del os.environ[\\\"TEST_API_KEY\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_params_sets_none_when_no_env_var_and_fallback_enabled():\\n    \\\"\\\"\\\"Test that when variable not found in db and env var doesn't exist.\\n\\n    The field is set to None.\\n    \\\"\\\"\\\"\\n    # Make sure env var doesn't exist\\n    if \\\"NONEXISTENT_KEY\\\" in os.environ:\\n        del os.environ[\\\"NONEXISTENT_KEY\\\"]\\n\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n    # Change this error message to avoid triggering re-raise\\n    custom_component.get_variable = AsyncMock(side_effect=ValueError(\\\"Database connection failed\\\"))\\n\\n    # Set up params\\n    params = {\\\"api_key\\\": \\\"NONEXISTENT_KEY\\\"}\\n    load_from_db_fields = [\\\"api_key\\\"]\\n\\n    # Call the function with fallback enabled\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_params_with_load_from_db_fields(\\n            custom_component, params, load_from_db_fields, fallback_to_env_vars=True\\n        )\\n\\n    # Should be set to None\\n    assert result[\\\"api_key\\\"] is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_params_raises_on_user_id_not_set():\\n    \\\"\\\"\\\"Test that 'User id is not set' error is always raised regardless of fallback setting.\\\"\\\"\\\"\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n    custom_component.get_variable = AsyncMock(side_effect=ValueError(\\\"User id is not set\\\"))\\n\\n    # Set up params\\n    params = {\\\"api_key\\\": \\\"SOME_KEY\\\"}\\n    load_from_db_fields = [\\\"api_key\\\"]\\n\\n    # Should raise with fallback enabled\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        with pytest.raises(ValueError, match=\\\"User id is not set\\\"):\\n            await update_params_with_load_from_db_fields(\\n                custom_component, params, load_from_db_fields, fallback_to_env_vars=True\\n            )\\n\\n    # Should also raise with fallback disabled\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        with pytest.raises(ValueError, match=\\\"User id is not set\\\"):\\n            await update_params_with_load_from_db_fields(\\n                custom_component, params, load_from_db_fields, fallback_to_env_vars=False\\n            )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_params_skips_empty_fields():\\n    \\\"\\\"\\\"Test that empty or None fields in params are skipped.\\\"\\\"\\\"\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n    custom_component.get_variable = AsyncMock(return_value=\\\"some-value\\\")\\n\\n    # Set up params with empty and None values\\n    params = {\\\"api_key\\\": \\\"\\\", \\\"another_key\\\": None, \\\"valid_key\\\": \\\"VALID_KEY\\\"}\\n    load_from_db_fields = [\\\"api_key\\\", \\\"another_key\\\", \\\"valid_key\\\"]\\n\\n    # Call the function\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session = MagicMock()\\n        mock_session_scope.return_value.__aenter__.return_value = mock_session\\n\\n        result = await update_params_with_load_from_db_fields(\\n            custom_component, params, load_from_db_fields, fallback_to_env_vars=True\\n        )\\n\\n    # Only valid_key should have been processed\\n    assert result[\\\"api_key\\\"] == \\\"\\\"\\n    assert result[\\\"another_key\\\"] is None\\n    assert result[\\\"valid_key\\\"] == \\\"some-value\\\"\\n\\n    # get_variable should only be called once for valid_key\\n    # Use ANY to match any session object instead of the specific mock\\n    from unittest.mock import ANY\\n\\n    custom_component.get_variable.assert_called_once_with(name=\\\"VALID_KEY\\\", field=\\\"valid_key\\\", session=ANY)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_params_handles_multiple_fields():\\n    \\\"\\\"\\\"Test that multiple fields are processed correctly with mixed results.\\\"\\\"\\\"\\n    # Set up environment variables\\n    os.environ[\\\"ENV_KEY\\\"] = \\\"env-value\\\"\\n\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n\\n    # Set up different responses for different fields\\n    async def mock_get_variable(name, **_kwargs):\\n        if name == \\\"DB_KEY\\\":\\n            return \\\"db-value\\\"\\n        # Use error messages that won't trigger the re-raise condition\\n        if name == \\\"ENV_KEY\\\":\\n            error_msg = \\\"Database connection failed\\\"  # This won't trigger re-raise\\n            raise ValueError(error_msg)\\n        error_msg = \\\"Database unavailable\\\"  # This won't trigger re-raise\\n        raise ValueError(error_msg)\\n\\n    custom_component.get_variable = AsyncMock(side_effect=mock_get_variable)\\n\\n    # Set up params\\n    params = {\\\"field1\\\": \\\"DB_KEY\\\", \\\"field2\\\": \\\"ENV_KEY\\\", \\\"field3\\\": \\\"MISSING_KEY\\\"}\\n    load_from_db_fields = [\\\"field1\\\", \\\"field2\\\", \\\"field3\\\"]\\n\\n    # Call the function with proper mocking - NOTICE THE CORRECT PATCH PATH\\n    with (\\n        patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope,\\n        patch(\\\"lfx.services.deps.get_settings_service\\\") as mock_get_settings,\\n    ):\\n        # Create a proper mock session that won't be detected as NoopSession\\n        mock_session = MagicMock()\\n        mock_session.__aenter__ = AsyncMock(return_value=mock_session)\\n        mock_session.__aexit__ = AsyncMock(return_value=None)\\n        mock_session_scope.return_value = mock_session\\n\\n        # Mock settings service to ensure it doesn't use noop database\\n        mock_settings_service = MagicMock()\\n        mock_settings_service.settings.use_noop_database = False\\n        mock_get_settings.return_value = mock_settings_service\\n\\n        result = await update_params_with_load_from_db_fields(\\n            custom_component, params, load_from_db_fields, fallback_to_env_vars=True\\n        )\\n\\n    # Check results\\n    assert result[\\\"field1\\\"] == \\\"db-value\\\"  # From database\\n    assert result[\\\"field2\\\"] == \\\"env-value\\\"  # From environment (fallback)\\n    assert result[\\\"field3\\\"] is None  # Not found anywhere\\n\\n    # Clean up\\n    del os.environ[\\\"ENV_KEY\\\"]\\n\\n\\n# =====================================================================================\\n# TABLE LOAD_FROM_DB TESTS\\n# =====================================================================================\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_table_params_with_load_from_db_fields_basic():\\n    \\\"\\\"\\\"Test basic table load_from_db functionality.\\\"\\\"\\\"\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n\\n    # Mock database values\\n    async def mock_get_variable(name, **_kwargs):\\n        mock_values = {\\n            \\\"ADMIN_USER\\\": \\\"actual_admin_user\\\",\\n            \\\"ADMIN_EMAIL\\\": \\\"admin@company.com\\\",\\n        }\\n        if name in mock_values:\\n            return mock_values[name]\\n        msg = f\\\"{name} variable not found.\\\"\\n        raise ValueError(msg)\\n\\n    custom_component.get_variable = AsyncMock(side_effect=mock_get_variable)\\n\\n    # Set up table params\\n    params = {\\n        \\\"table_data\\\": [\\n            {\\\"username\\\": \\\"ADMIN_USER\\\", \\\"email\\\": \\\"ADMIN_EMAIL\\\", \\\"role\\\": \\\"admin\\\"},\\n            {\\\"username\\\": \\\"static_user\\\", \\\"email\\\": \\\"static@example.com\\\", \\\"role\\\": \\\"user\\\"},\\n        ],\\n        \\\"table_data_load_from_db_columns\\\": [\\\"username\\\", \\\"email\\\"],\\n    }\\n\\n    # Call the function\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_table_params_with_load_from_db_fields(\\n            custom_component, params, \\\"table_data\\\", fallback_to_env_vars=False\\n        )\\n\\n    # Check results\\n    table_data = result[\\\"table_data\\\"]\\n    assert len(table_data) == 2\\n\\n    # First row should have resolved values\\n    assert table_data[0][\\\"username\\\"] == \\\"actual_admin_user\\\"\\n    assert table_data[0][\\\"email\\\"] == \\\"admin@company.com\\\"\\n    assert table_data[0][\\\"role\\\"] == \\\"admin\\\"  # unchanged\\n\\n    # Unmarked values that are not variables should stay literal.\\n    assert table_data[1][\\\"username\\\"] == \\\"static_user\\\"\\n    assert table_data[1][\\\"email\\\"] == \\\"static@example.com\\\"\\n    assert table_data[1][\\\"role\\\"] == \\\"user\\\"  # unchanged\\n\\n    # Metadata should be removed\\n    assert \\\"table_data_load_from_db_columns\\\" not in result\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_table_params_respects_cell_level_literal_marker():\\n    \\\"\\\"\\\"Explicit literal table cells should not be resolved as global variables.\\\"\\\"\\\"\\n    custom_component = MagicMock()\\n    custom_component.get_variable = AsyncMock(return_value=\\\"resolved_value\\\")\\n\\n    params = {\\n        \\\"table_data\\\": [\\n            {\\n                \\\"header\\\": \\\"GLOBAL_VAR_NAME\\\",\\n                \\\"__load_from_db_fields\\\": {\\\"header\\\": False},\\n            },\\n        ],\\n        \\\"table_data_load_from_db_columns\\\": [\\\"header\\\"],\\n    }\\n\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_table_params_with_load_from_db_fields(\\n            custom_component, params, \\\"table_data\\\", fallback_to_env_vars=False\\n        )\\n\\n    assert result[\\\"table_data\\\"] == [{\\\"header\\\": \\\"GLOBAL_VAR_NAME\\\"}]\\n    custom_component.get_variable.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_table_params_respects_cell_level_global_variable_marker():\\n    \\\"\\\"\\\"Explicit global-variable table cells should resolve via load_from_db.\\\"\\\"\\\"\\n    custom_component = MagicMock()\\n    custom_component.get_variable = AsyncMock(return_value=\\\"resolved_value\\\")\\n\\n    params = {\\n        \\\"table_data\\\": [\\n            {\\n                \\\"header\\\": \\\"GLOBAL_VAR_NAME\\\",\\n                \\\"__load_from_db_fields\\\": {\\\"header\\\": True},\\n            },\\n        ],\\n        \\\"table_data_load_from_db_columns\\\": [\\\"header\\\"],\\n    }\\n\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_table_params_with_load_from_db_fields(\\n            custom_component, params, \\\"table_data\\\", fallback_to_env_vars=False\\n        )\\n\\n    assert result[\\\"table_data\\\"] == [{\\\"header\\\": \\\"resolved_value\\\"}]\\n    custom_component.get_variable.assert_awaited_once()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_table_params_with_fallback_to_env():\\n    \\\"\\\"\\\"Test table load_from_db with environment variable fallback.\\\"\\\"\\\"\\n    # Set up environment variables\\n    os.environ[\\\"DB_USERNAME\\\"] = \\\"env_username\\\"\\n    os.environ[\\\"DB_EMAIL\\\"] = \\\"env@example.com\\\"\\n\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n    # graph.context is a dict in production; set it explicitly so no_env_fallback resolves\\n    # to False (a bare MagicMock's .context.get(...) returns a truthy mock and would\\n    # silently disable env fallback).\\n    custom_component.graph.context = {}\\n    custom_component.get_variable = AsyncMock(side_effect=ValueError(\\\"variable not found.\\\"))\\n\\n    # Set up table params\\n    params = {\\n        \\\"table_data\\\": [\\n            {\\\"username\\\": \\\"DB_USERNAME\\\", \\\"email\\\": \\\"DB_EMAIL\\\", \\\"active\\\": True},\\n        ],\\n        \\\"table_data_load_from_db_columns\\\": [\\\"username\\\", \\\"email\\\"],\\n    }\\n\\n    # Call the function with fallback enabled\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_table_params_with_load_from_db_fields(\\n            custom_component, params, \\\"table_data\\\", fallback_to_env_vars=True\\n        )\\n\\n    # Check results - should use environment variables\\n    table_data = result[\\\"table_data\\\"]\\n    assert table_data[0][\\\"username\\\"] == \\\"env_username\\\"\\n    assert table_data[0][\\\"email\\\"] == \\\"env@example.com\\\"\\n    assert table_data[0][\\\"active\\\"] is True  # unchanged\\n\\n    # Clean up\\n    del os.environ[\\\"DB_USERNAME\\\"]\\n    del os.environ[\\\"DB_EMAIL\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_table_params_mixed_db_and_env():\\n    \\\"\\\"\\\"Test table with some values from DB and some from environment.\\\"\\\"\\\"\\n    # Set up environment variables\\n    os.environ[\\\"ENV_KEY\\\"] = \\\"from_environment\\\"\\n\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n    # graph.context is a dict in production; set it explicitly so no_env_fallback resolves\\n    # to False (a bare MagicMock's .context.get(...) returns a truthy mock and would\\n    # silently disable env fallback).\\n    custom_component.graph.context = {}\\n\\n    async def mock_get_variable(name, **_kwargs):\\n        if name == \\\"DB_KEY\\\":\\n            return \\\"from_database\\\"\\n        msg = f\\\"{name} variable not found.\\\"\\n        raise ValueError(msg)\\n\\n    custom_component.get_variable = AsyncMock(side_effect=mock_get_variable)\\n\\n    # Set up table params\\n    params = {\\n        \\\"table_data\\\": [\\n            {\\\"field1\\\": \\\"DB_KEY\\\", \\\"field2\\\": \\\"ENV_KEY\\\", \\\"field3\\\": \\\"static_value\\\"},\\n        ],\\n        \\\"table_data_load_from_db_columns\\\": [\\\"field1\\\", \\\"field2\\\"],\\n    }\\n\\n    # Call the function with fallback enabled\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_table_params_with_load_from_db_fields(\\n            custom_component, params, \\\"table_data\\\", fallback_to_env_vars=True\\n        )\\n\\n    # Check results\\n    table_data = result[\\\"table_data\\\"]\\n    assert table_data[0][\\\"field1\\\"] == \\\"from_database\\\"  # From DB\\n    assert table_data[0][\\\"field2\\\"] == \\\"from_environment\\\"  # From env fallback\\n    assert table_data[0][\\\"field3\\\"] == \\\"static_value\\\"  # Not in load_from_db_columns\\n\\n    # Clean up\\n    del os.environ[\\\"ENV_KEY\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_table_params_empty_table():\\n    \\\"\\\"\\\"Test table load_from_db with empty table data.\\\"\\\"\\\"\\n    custom_component = MagicMock()\\n\\n    params = {\\n        \\\"table_data\\\": [],\\n        \\\"table_data_load_from_db_columns\\\": [\\\"username\\\", \\\"email\\\"],\\n    }\\n\\n    result = await update_table_params_with_load_from_db_fields(\\n        custom_component, params, \\\"table_data\\\", fallback_to_env_vars=False\\n    )\\n\\n    # Should return empty table and remove metadata\\n    assert result[\\\"table_data\\\"] == []\\n    assert \\\"table_data_load_from_db_columns\\\" not in result\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_table_params_no_load_from_db_columns():\\n    \\\"\\\"\\\"Test table with no load_from_db columns.\\\"\\\"\\\"\\n    custom_component = MagicMock()\\n\\n    params = {\\n        \\\"table_data\\\": [{\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\"}],\\n        \\\"table_data_load_from_db_columns\\\": [],\\n    }\\n\\n    result = await update_table_params_with_load_from_db_fields(\\n        custom_component, params, \\\"table_data\\\", fallback_to_env_vars=False\\n    )\\n\\n    # Should return unchanged table and remove metadata\\n    assert result[\\\"table_data\\\"] == [{\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\"}]\\n    assert \\\"table_data_load_from_db_columns\\\" not in result\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_table_params_non_dict_rows():\\n    \\\"\\\"\\\"Test table with non-dictionary rows (should be left unchanged).\\\"\\\"\\\"\\n    custom_component = MagicMock()\\n    custom_component.get_variable = AsyncMock(return_value=\\\"resolved_value\\\")\\n\\n    params = {\\n        \\\"table_data\\\": [\\n            {\\\"username\\\": \\\"DB_USER\\\"},  # dict row\\n            \\\"string_row\\\",  # non-dict row\\n            123,  # non-dict row\\n        ],\\n        \\\"table_data_load_from_db_columns\\\": [\\\"username\\\"],\\n    }\\n\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_table_params_with_load_from_db_fields(\\n            custom_component, params, \\\"table_data\\\", fallback_to_env_vars=False\\n        )\\n\\n    # Check results\\n    table_data = result[\\\"table_data\\\"]\\n    assert len(table_data) == 3\\n    assert table_data[0][\\\"username\\\"] == \\\"resolved_value\\\"  # dict row processed\\n    assert table_data[1] == \\\"string_row\\\"  # non-dict row unchanged\\n    assert table_data[2] == 123  # non-dict row unchanged\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_params_with_table_fields():\\n    \\\"\\\"\\\"Test the main update_params function with table: prefix fields.\\\"\\\"\\\"\\n    # Set up environment variable\\n    os.environ[\\\"TABLE_VAR\\\"] = \\\"table_env_value\\\"\\n\\n    # Create mock custom component\\n    custom_component = MagicMock()\\n\\n    async def mock_get_variable(name, **_kwargs):\\n        if name == \\\"REGULAR_VAR\\\":\\n            return \\\"regular_db_value\\\"\\n        if name == \\\"TABLE_VAR\\\":\\n            return \\\"table_db_value\\\"\\n        msg = f\\\"{name} variable not found.\\\"\\n        raise ValueError(msg)\\n\\n    custom_component.get_variable = AsyncMock(side_effect=mock_get_variable)\\n\\n    # Set up params with both regular and table fields\\n    params = {\\n        \\\"regular_field\\\": \\\"REGULAR_VAR\\\",\\n        \\\"table_data\\\": [\\n            {\\\"username\\\": \\\"TABLE_VAR\\\", \\\"role\\\": \\\"admin\\\"},\\n        ],\\n        \\\"table_data_load_from_db_columns\\\": [\\\"username\\\"],\\n    }\\n\\n    load_from_db_fields = [\\\"regular_field\\\", \\\"table:table_data\\\"]\\n\\n    # Call the main function (lfx version with table support)\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        result = await update_params_with_load_from_db_fields(\\n            custom_component, params, load_from_db_fields, fallback_to_env_vars=False\\n        )\\n\\n    # Check results\\n    assert result[\\\"regular_field\\\"] == \\\"regular_db_value\\\"  # Regular field from DB\\n\\n    table_data = result[\\\"table_data\\\"]\\n    assert table_data[0][\\\"username\\\"] == \\\"table_db_value\\\"  # Table field from DB\\n    assert table_data[0][\\\"role\\\"] == \\\"admin\\\"  # Unchanged\\n\\n    # Metadata should be removed\\n    assert \\\"table_data_load_from_db_columns\\\" not in result\\n\\n    # Clean up\\n    del os.environ[\\\"TABLE_VAR\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_table_params_handles_user_id_not_set_error():\\n    \\\"\\\"\\\"Test that 'User id is not set' error is properly raised for table fields.\\\"\\\"\\\"\\n    custom_component = MagicMock()\\n    custom_component.get_variable = AsyncMock(side_effect=ValueError(\\\"User id is not set\\\"))\\n\\n    params = {\\n        \\\"table_data\\\": [{\\\"username\\\": \\\"SOME_VAR\\\"}],\\n        \\\"table_data_load_from_db_columns\\\": [\\\"username\\\"],\\n    }\\n\\n    with patch(\\\"lfx.interface.initialize.loading.session_scope\\\") as mock_session_scope:\\n        mock_session_scope.return_value.__aenter__.return_value = MagicMock()\\n\\n        with pytest.raises(ValueError, match=\\\"User id is not set\\\"):\\n            await update_table_params_with_load_from_db_fields(\\n                custom_component, params, \\\"table_data\\\", fallback_to_env_vars=True\\n            )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/io/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/io/test_io_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ac7eef22097b409e917bc47856d00825a2431e11eec14931a7b832b549da3eba\",\"content\":\"from typing import TYPE_CHECKING, Literal\\n\\nimport pytest\\nfrom lfx.components.input_output import ChatInput\\nfrom lfx.inputs.inputs import DropdownInput, FileInput, IntInput, NestedDictInput, StrInput\\nfrom lfx.io.schema import create_input_schema\\n\\nif TYPE_CHECKING:\\n    from pydantic.fields import FieldInfo\\n\\n\\ndef test_create_input_schema():\\n    schema = create_input_schema(ChatInput.inputs)\\n    assert schema.__name__ == \\\"InputSchema\\\"\\n\\n\\nclass TestCreateInputSchema:\\n    # Single input type is converted to list and processed correctly\\n    def test_single_input_type_conversion(self):\\n        input_instance = StrInput(name=\\\"test_field\\\")\\n        schema = create_input_schema([input_instance])\\n        assert schema.__name__ == \\\"InputSchema\\\"\\n        assert \\\"test_field\\\" in schema.model_fields\\n\\n    # Multiple input types are processed and included in the schema\\n    def test_multiple_input_types(self):\\n        inputs = [StrInput(name=\\\"str_field\\\"), IntInput(name=\\\"int_field\\\")]\\n        schema = create_input_schema(inputs)\\n        assert schema.__name__ == \\\"InputSchema\\\"\\n        assert \\\"str_field\\\" in schema.model_fields\\n        assert \\\"int_field\\\" in schema.model_fields\\n\\n    # Fields are correctly created with appropriate types and attributes\\n    def test_fields_creation_with_correct_types_and_attributes(self):\\n        input_instance = StrInput(name=\\\"test_field\\\", info=\\\"Test Info\\\", required=True)\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.description == \\\"Test Info\\\"\\n        assert field_info.is_required() is True\\n\\n    # Schema model is created and returned successfully\\n    def test_schema_model_creation(self):\\n        input_instance = StrInput(name=\\\"test_field\\\")\\n        schema = create_input_schema([input_instance])\\n        assert schema.__name__ == \\\"InputSchema\\\"\\n\\n    # Default values are correctly assigned to fields\\n    def test_default_values_assignment(self):\\n        input_instance = StrInput(name=\\\"test_field\\\", value=\\\"default_value\\\")\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.default == \\\"default_value\\\"\\n\\n    # Empty list of inputs is handled without errors\\n    def test_empty_list_of_inputs(self):\\n        schema = create_input_schema([])\\n        assert schema.__name__ == \\\"InputSchema\\\"\\n\\n    # Input with missing optional attributes (e.g., display_name, info) is processed correctly\\n    def test_missing_optional_attributes(self):\\n        input_instance = StrInput(name=\\\"test_field\\\")\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.title == \\\"Test Field\\\"\\n        assert field_info.description == \\\"\\\"\\n\\n    # Input with is_list attribute set to True is processed correctly\\n    def test_is_list_attribute_processing(self):\\n        input_instance = StrInput(name=\\\"test_field\\\", is_list=True)\\n        schema = create_input_schema([input_instance])\\n        field_info: FieldInfo = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.annotation == list[str]\\n\\n    # Input with options attribute is processed correctly\\n    def test_options_attribute_processing(self):\\n        input_instance = DropdownInput(name=\\\"test_field\\\", options=[\\\"option1\\\", \\\"option2\\\"])\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.annotation == Literal[\\\"option1\\\", \\\"option2\\\"]\\n\\n    # Non-standard field types are handled correctly\\n    def test_non_standard_field_types_handling(self):\\n        input_instance = FileInput(name=\\\"file_field\\\")\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"file_field\\\"]\\n        assert field_info.annotation is str\\n\\n    # Inputs with mixed required and optional fields are processed correctly\\n    def test_mixed_required_optional_fields_processing(self):\\n        inputs = [\\n            StrInput(name=\\\"required_field\\\", required=True),\\n            IntInput(name=\\\"optional_field\\\", required=False),\\n        ]\\n        schema = create_input_schema(inputs)\\n        required_field_info = schema.model_fields[\\\"required_field\\\"]\\n        optional_field_info = schema.model_fields[\\\"optional_field\\\"]\\n\\n        assert required_field_info.is_required() is True\\n        assert optional_field_info.is_required() is False\\n\\n    # Inputs with complex nested structures are handled correctly\\n    def test_complex_nested_structures_handling(self):\\n        nested_input = NestedDictInput(name=\\\"nested_field\\\", value={\\\"key\\\": \\\"value\\\"})\\n        schema = create_input_schema([nested_input])\\n\\n        field_info = schema.model_fields[\\\"nested_field\\\"]\\n\\n        assert isinstance(field_info.default, dict)\\n        assert field_info.default[\\\"key\\\"] == \\\"value\\\"\\n\\n    # Creating a schema from a single input type\\n    def test_single_input_type_replica(self):\\n        input_instance = StrInput(name=\\\"test_field\\\")\\n        schema = create_input_schema([input_instance])\\n        assert schema.__name__ == \\\"InputSchema\\\"\\n        assert \\\"test_field\\\" in schema.model_fields\\n\\n    # Creating a schema from a list of input types\\n    def test_passing_input_type_directly(self):\\n        inputs = StrInput(name=\\\"str_field\\\"), IntInput(name=\\\"int_field\\\")\\n        with pytest.raises(TypeError):\\n            create_input_schema(inputs)\\n\\n    # Handling input types with options correctly\\n    def test_options_handling(self):\\n        input_instance = DropdownInput(name=\\\"test_field\\\", options=[\\\"option1\\\", \\\"option2\\\"])\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.annotation == Literal[\\\"option1\\\", \\\"option2\\\"]\\n\\n    # Handling input types with is_list attribute correctly\\n    def test_is_list_handling(self):\\n        input_instance = StrInput(name=\\\"test_field\\\", is_list=True)\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.annotation == list[str]\\n\\n    # Converting FieldTypes to corresponding Python types\\n    def test_field_types_conversion(self):\\n        input_instance = IntInput(name=\\\"int_field\\\")\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"int_field\\\"]\\n        assert field_info.annotation is int  # Use 'is' for type comparison\\n\\n    # Setting default values for non-required fields\\n    def test_default_values_for_non_required_fields(self):\\n        input_instance = StrInput(name=\\\"test_field\\\", value=\\\"default_value\\\")\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.default == \\\"default_value\\\"\\n\\n    # Handling input types with missing attributes\\n    def test_missing_attributes_handling(self):\\n        input_instance = StrInput(name=\\\"test_field\\\")\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.title == \\\"Test Field\\\"\\n        assert field_info.description == \\\"\\\"\\n\\n    # Handling invalid field types\\n\\n    # Handling input types with None as default value\\n    def test_none_default_value_handling(self):\\n        input_instance = StrInput(name=\\\"test_field\\\", value=None)\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"test_field\\\"]\\n        assert field_info.default is None\\n\\n    # Handling input types with special characters in names\\n    def test_special_characters_in_names_handling(self):\\n        input_instance = StrInput(name=\\\"test@field#name\\\")\\n        schema = create_input_schema([input_instance])\\n        assert \\\"test@field#name\\\" in schema.model_fields\\n\\n    # numpy scalar defaults (from DB round-trip) are coerced to native Python types.\\n    # Regression test for Agent build failing with TypeError when KnowledgeBase /\\n    # MemoryBase top_k arrives as numpy.int64 \u2014 Pydantic Field fails to introspect\\n    # the non-native scalar and raises:\\n    #   TypeError(\\\"'numpy.int64' object is not iterable\\\")\\n    #   TypeError(\\\"vars() argument must have __dict__ attribute\\\")\\n    def test_numpy_scalar_default_value_coerced(self):\\n        numpy = pytest.importorskip(\\\"numpy\\\")\\n        # Bypass IntInput's value validator to simulate the post-deserialization\\n        # state where the field already holds a numpy scalar.\\n        input_instance = IntInput(name=\\\"top_k\\\", required=False)\\n        object.__setattr__(input_instance, \\\"value\\\", numpy.int64(5))\\n        schema = create_input_schema([input_instance])\\n        field_info = schema.model_fields[\\\"top_k\\\"]\\n        assert field_info.default == 5\\n        assert type(field_info.default) is int\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/io/test_table_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d5d1f775e03a223f82e9bd8bd2008c8e23830c2f3ccfe368a9acfbc3bb817fe4\",\"content\":\"# Generated by qodo Gen\\n\\nimport pytest\\nfrom lfx.schema.table import Column, FormatterType\\n\\n\\nclass TestColumn:\\n    # Creating a Column instance without display_name sets it to the name\\n    def test_create_column_without_display_name(self):\\n        column = Column(name=\\\"test_column\\\")\\n        assert column.display_name == \\\"test_column\\\"\\n\\n    # Creating a Column instance with valid formatter values\\n    def test_create_column_with_valid_formatter(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\", formatter=\\\"date\\\")\\n        assert column.formatter == FormatterType.date\\n\\n    # Formatter is set based on provided formatter value\\n    def test_formatter_set_based_on_value(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\", formatter=\\\"int\\\")\\n        assert column.formatter == FormatterType.number\\n\\n    # Default values for sortable and filterable are set to True\\n    def test_default_sortable_filterable(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\")\\n        assert column.sortable is True\\n        assert column.filterable is True\\n\\n    # Ensure formatter field is correctly set when provided a FormatterType\\n    def test_formatter_explicitly_set_to_enum(self):\\n        column = Column(display_name=\\\"Date Column\\\", name=\\\"date_column\\\", formatter=FormatterType.date)\\n        assert column.formatter == FormatterType.date\\n\\n    # Invalid formatter raises ValueError\\n    def test_invalid_formatter_raises_value_error(self):\\n        with pytest.raises(ValueError, match=\\\"'invalid' is not a valid FormatterType\\\"):\\n            Column(display_name=\\\"Invalid Column\\\", name=\\\"invalid_column\\\", formatter=\\\"invalid\\\")\\n\\n    # Formatter is None when not provided\\n    def test_formatter_none_when_not_provided(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\")\\n        assert column.formatter is None\\n\\n    # Description and default can be set\\n    def test_description_and_default(self):\\n        column = Column(\\n            display_name=\\\"Test Column\\\", name=\\\"test_column\\\", description=\\\"A test column\\\", default=\\\"default_value\\\"\\n        )\\n        assert column.description == \\\"A test column\\\"\\n        assert column.default == \\\"default_value\\\"\\n\\n    def test_create_with_type_instead_of_formatter(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\", type=\\\"date\\\")\\n        assert column.formatter == FormatterType.date\\n\\n    # Test load_from_db functionality\\n    def test_column_load_from_db_default_false(self):\\n        \\\"\\\"\\\"Test that load_from_db defaults to False.\\\"\\\"\\\"\\n        column = Column(name=\\\"test_column\\\")\\n        assert column.load_from_db is False\\n\\n    def test_column_load_from_db_can_be_set_true(self):\\n        \\\"\\\"\\\"Test that load_from_db can be explicitly set to True.\\\"\\\"\\\"\\n        column = Column(name=\\\"test_column\\\", load_from_db=True)\\n        assert column.load_from_db is True\\n\\n    def test_column_load_from_db_with_default_value(self):\\n        \\\"\\\"\\\"Test that load_from_db works with default values.\\\"\\\"\\\"\\n        column = Column(name=\\\"username\\\", display_name=\\\"Username\\\", default=\\\"admin\\\", load_from_db=True)\\n        assert column.load_from_db is True\\n        assert column.default == \\\"admin\\\"\\n\\n    def test_column_load_from_db_false_uses_static_default(self):\\n        \\\"\\\"\\\"Test that when load_from_db is False, static defaults are used.\\\"\\\"\\\"\\n        column = Column(name=\\\"role\\\", display_name=\\\"User Role\\\", default=\\\"user\\\", load_from_db=False)\\n        assert column.load_from_db is False\\n        assert column.default == \\\"user\\\"\\n\\n    def test_multiple_columns_mixed_load_from_db(self):\\n        \\\"\\\"\\\"Test creating multiple columns with different load_from_db settings.\\\"\\\"\\\"\\n        columns = [\\n            Column(name=\\\"username\\\", load_from_db=True, default=\\\"admin\\\"),\\n            Column(name=\\\"email\\\", load_from_db=True, default=\\\"user@example.com\\\"),\\n            Column(name=\\\"role\\\", load_from_db=False, default=\\\"user\\\"),\\n            Column(name=\\\"active\\\", load_from_db=False, default=True, type=\\\"boolean\\\"),\\n        ]\\n\\n        # Check load_from_db settings\\n        assert columns[0].load_from_db is True\\n        assert columns[1].load_from_db is True\\n        assert columns[2].load_from_db is False\\n        assert columns[3].load_from_db is False\\n\\n        # Check defaults are preserved\\n        assert columns[0].default == \\\"admin\\\"\\n        assert columns[1].default == \\\"user@example.com\\\"\\n        assert columns[2].default == \\\"user\\\"\\n        assert columns[3].default is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/mock_language_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a1aaafdc0b7e8e55233cef1e4de7d06008e8b80bf7f699a3d78c4f25ad024bc8\",\"content\":\"from unittest.mock import MagicMock\\n\\nfrom langchain_core.language_models import BaseLanguageModel\\nfrom pydantic import BaseModel, Field\\nfrom typing_extensions import override\\n\\n\\nclass MockLanguageModel(BaseLanguageModel, BaseModel):\\n    \\\"\\\"\\\"A mock language model for testing purposes.\\\"\\\"\\\"\\n\\n    tools: list = Field(default_factory=list)\\n    response_generator: callable = Field(default_factory=lambda: lambda msg: f\\\"Response for {msg}\\\")\\n\\n    def __init__(self, response_generator=None, **kwargs):\\n        \\\"\\\"\\\"Initialize the mock model with an optional response generator function.\\\"\\\"\\\"\\n        super().__init__(**kwargs)\\n        if response_generator:\\n            self.response_generator = response_generator\\n\\n    @override\\n    def with_config(self, *args, **kwargs):\\n        return self\\n\\n    @override\\n    def with_structured_output(self, *args, **kwargs):\\n        return self\\n\\n    @override\\n    async def abatch(self, messages, *args, **kwargs):\\n        if not messages:\\n            return []\\n        # If message is a list of dicts (chat format), get the last user message\\n        responses = []\\n        for msg_list in messages:\\n            content = msg_list[-1][\\\"content\\\"] if isinstance(msg_list, list) else msg_list\\n            mock_response = MagicMock()\\n            mock_response.content = self.response_generator(content)\\n            responses.append(mock_response)\\n        return responses\\n\\n    @override\\n    def invoke(self, *args, **kwargs):\\n        return self\\n\\n    @override\\n    def generate_prompt(self, *args, **kwargs):\\n        raise NotImplementedError\\n\\n    @override\\n    async def agenerate_prompt(self, *args, **kwargs):\\n        raise NotImplementedError\\n\\n    @override\\n    def predict(self, *args, **kwargs):\\n        raise NotImplementedError\\n\\n    @override\\n    def predict_messages(self, *args, **kwargs):\\n        raise NotImplementedError\\n\\n    @override\\n    async def apredict(self, *args, **kwargs):\\n        raise NotImplementedError\\n\\n    @override\\n    async def apredict_messages(self, *args, **kwargs):\\n        raise NotImplementedError\\n\\n    def bind_tools(self, tools, tool_choice=None):  # noqa: ARG002\\n        \\\"\\\"\\\"Bind tools to the model for testing.\\\"\\\"\\\"\\n        self.tools = tools\\n        return self\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/schema/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0be1c1b20a7adde42a8f5675072179c2bdd79d5445f300537753568fe97bccfc\",\"content\":\"\\\"\\\"\\\"Unit tests for schema classes.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/schema/test_cross_module.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"91d9eeb489b40cda9896b060058d1d3512f135529f8ce4c997ea50ee5b45a318\",\"content\":\"\\\"\\\"\\\"Unit tests for cross-module isinstance functionality.\\n\\nThese tests verify that isinstance checks work correctly when classes are\\nre-exported from different modules (e.g., lfx.schema.Message vs langflow.schema.Message).\\n\\\"\\\"\\\"\\n\\nfrom langflow.schema import Data as LangflowData\\nfrom langflow.schema import Message as LangflowMessage\\nfrom lfx.schema.data import Data as LfxData\\nfrom lfx.schema.message import Message as LfxMessage\\n\\n\\nclass TestDuckTypingData:\\n    \\\"\\\"\\\"Tests for duck-typing Data class across module boundaries.\\\"\\\"\\\"\\n\\n    def test_lfx_data_isinstance_langflow_data(self):\\n        \\\"\\\"\\\"Test that lfx.Data instance is recognized as langflow.Data.\\\"\\\"\\\"\\n        lfx_data = LfxData(data={\\\"key\\\": \\\"value\\\"})\\n        assert isinstance(lfx_data, LangflowData)\\n\\n    def test_langflow_data_isinstance_lfx_data(self):\\n        \\\"\\\"\\\"Test that langflow.Data instance is recognized as lfx.Data.\\\"\\\"\\\"\\n        langflow_data = LangflowData(data={\\\"key\\\": \\\"value\\\"})\\n        assert isinstance(langflow_data, LfxData)\\n\\n    def test_data_equality_across_modules(self):\\n        \\\"\\\"\\\"Test that Data objects from different modules are equal.\\\"\\\"\\\"\\n        lfx_data = LfxData(data={\\\"key\\\": \\\"value\\\"})\\n        langflow_data = LangflowData(data={\\\"key\\\": \\\"value\\\"})\\n        assert lfx_data == langflow_data\\n\\n    def test_data_interchangeable_in_functions(self):\\n        \\\"\\\"\\\"Test that Data from different modules work interchangeably.\\\"\\\"\\\"\\n\\n        def process_data(data: LangflowData) -> str:\\n            return data.get_text()\\n\\n        lfx_data = LfxData(data={\\\"text\\\": \\\"hello\\\"})\\n        # Should not raise type error\\n        result = process_data(lfx_data)\\n        assert result == \\\"hello\\\"\\n\\n    def test_data_model_dump_compatible(self):\\n        \\\"\\\"\\\"Test that model_dump works across module boundaries.\\\"\\\"\\\"\\n        lfx_data = LfxData(data={\\\"key\\\": \\\"value\\\"})\\n        langflow_data = LangflowData(**lfx_data.model_dump())\\n        assert langflow_data.data == {\\\"key\\\": \\\"value\\\"}\\n\\n\\nclass TestDuckTypingMessage:\\n    \\\"\\\"\\\"Tests for duck-typing Message class across module boundaries.\\\"\\\"\\\"\\n\\n    def test_lfx_message_isinstance_langflow_message(self):\\n        \\\"\\\"\\\"Test that lfx.Message instance is recognized as langflow.Message.\\\"\\\"\\\"\\n        lfx_message = LfxMessage(text=\\\"hello\\\")\\n        assert isinstance(lfx_message, LangflowMessage)\\n\\n    def test_langflow_message_isinstance_lfx_message(self):\\n        \\\"\\\"\\\"Test that langflow.Message instance is recognized as lfx.Message.\\\"\\\"\\\"\\n        langflow_message = LangflowMessage(text=\\\"hello\\\")\\n        assert isinstance(langflow_message, LfxMessage)\\n\\n    def test_message_equality_across_modules(self):\\n        \\\"\\\"\\\"Test that Message objects from different modules are equal.\\\"\\\"\\\"\\n        lfx_message = LfxMessage(text=\\\"hello\\\", sender=\\\"user\\\")\\n        langflow_message = LangflowMessage(text=\\\"hello\\\", sender=\\\"user\\\")\\n        # Note: Direct equality might not work due to timestamps\\n        assert lfx_message.text == langflow_message.text\\n        assert lfx_message.sender == langflow_message.sender\\n\\n    def test_message_interchangeable_in_functions(self):\\n        \\\"\\\"\\\"Test that Message from different modules work interchangeably.\\\"\\\"\\\"\\n\\n        def process_message(msg: LangflowMessage) -> str:\\n            return f\\\"Processed: {msg.text}\\\"\\n\\n        lfx_message = LfxMessage(text=\\\"hello\\\")\\n        # Should not raise type error\\n        result = process_message(lfx_message)\\n        assert result == \\\"Processed: hello\\\"\\n\\n    def test_message_model_dump_compatible(self):\\n        \\\"\\\"\\\"Test that model_dump works across module boundaries.\\\"\\\"\\\"\\n        lfx_message = LfxMessage(text=\\\"hello\\\", sender=\\\"user\\\")\\n        dump = lfx_message.model_dump()\\n        langflow_message = LangflowMessage(**dump)\\n        assert langflow_message.text == \\\"hello\\\"\\n        assert langflow_message.sender == \\\"user\\\"\\n\\n    def test_message_inherits_data_duck_typing(self):\\n        \\\"\\\"\\\"Test that Message inherits duck-typing from Data.\\\"\\\"\\\"\\n        lfx_message = LfxMessage(text=\\\"hello\\\")\\n        # Should work as Data too\\n        assert isinstance(lfx_message, LangflowData)\\n        assert isinstance(lfx_message, LfxData)\\n\\n\\nclass TestContentBlockExcludeUnsetCrossModule:\\n    \\\"\\\"\\\"langflow and lfx ``ContentBlock`` copies must share the ``exclude_unset`` contract.\\n\\n    Both ``__init__`` overrides mark only the ``type`` discriminator as set, so\\n    a partial patch like ``ContentBlock(title=\\\"...\\\")`` dumps just the fields the\\n    caller touched. Marking every field set (the prior langflow-base behavior)\\n    re-emitted defaulted ``duration`` / ``header`` / ``contents`` / ``media_url``\\n    and clobbered persisted values on the ``aupdate_messages`` merge.\\n    \\\"\\\"\\\"\\n\\n    def test_langflow_content_block_exclude_unset_matches_lfx(self):\\n        from langflow.schema.content_types import ContentBlock as LangflowContentBlock\\n        from lfx.schema.content_types import ContentBlock as LfxContentBlock\\n\\n        langflow_dump = LangflowContentBlock(title=\\\"new\\\", allow_markdown=False).model_dump(exclude_unset=True)\\n        lfx_dump = LfxContentBlock(title=\\\"new\\\", allow_markdown=False).model_dump(exclude_unset=True)\\n\\n        assert langflow_dump == lfx_dump\\n        assert langflow_dump[\\\"type\\\"] == \\\"group\\\"\\n        assert langflow_dump.keys() <= {\\\"type\\\", \\\"title\\\", \\\"allow_markdown\\\"}\\n\\n\\nclass TestDuckTypingWithInputs:\\n    \\\"\\\"\\\"Tests for duck-typing with input validation.\\\"\\\"\\\"\\n\\n    def test_message_input_accepts_lfx_message(self):\\n        \\\"\\\"\\\"Test that MessageInput accepts lfx.Message.\\\"\\\"\\\"\\n        from lfx.inputs.inputs import MessageInput\\n\\n        lfx_message = LfxMessage(text=\\\"hello\\\")\\n        msg_input = MessageInput(name=\\\"test\\\", value=lfx_message)\\n        assert isinstance(msg_input.value, (LfxMessage, LangflowMessage))\\n\\n    def test_message_input_converts_cross_module(self):\\n        \\\"\\\"\\\"Test that MessageInput handles cross-module Messages.\\\"\\\"\\\"\\n        from lfx.inputs.inputs import MessageInput\\n\\n        langflow_message = LangflowMessage(text=\\\"hello\\\")\\n        msg_input = MessageInput(name=\\\"test\\\", value=langflow_message)\\n        # Should recognize it as a Message\\n        assert msg_input.value.text == \\\"hello\\\"\\n\\n    def test_data_input_accepts_lfx_data(self):\\n        \\\"\\\"\\\"Test that DataInput accepts lfx.Data.\\\"\\\"\\\"\\n        from lfx.inputs.inputs import DataInput\\n\\n        lfx_data = LfxData(data={\\\"key\\\": \\\"value\\\"})\\n        data_input = DataInput(name=\\\"test\\\", value=lfx_data)\\n        assert data_input.value == lfx_data\\n\\n\\nclass TestDuckTypingEdgeCases:\\n    \\\"\\\"\\\"Tests for edge cases in cross-module isinstance checks.\\\"\\\"\\\"\\n\\n    def test_different_class_name_not_cross_module(self):\\n        \\\"\\\"\\\"Test that objects with different class names are not recognized as cross-module compatible.\\\"\\\"\\\"\\n        from lfx.schema.cross_module import CrossModuleModel\\n\\n        class CustomModel(CrossModuleModel):\\n            value: str\\n\\n        custom = CustomModel(value=\\\"test\\\")\\n        # Should not be considered a Data\\n        assert not isinstance(custom, LfxData)\\n        assert not isinstance(custom, LangflowData)\\n\\n    def test_non_pydantic_model_not_cross_module(self):\\n        \\\"\\\"\\\"Test that non-Pydantic objects are not recognized as cross-module compatible.\\\"\\\"\\\"\\n\\n        class FakeData:\\n            def __init__(self):\\n                self.data = {}\\n\\n        fake = FakeData()\\n        assert not isinstance(fake, LfxData)\\n        assert not isinstance(fake, LangflowData)\\n\\n    def test_missing_fields_not_cross_module(self):\\n        \\\"\\\"\\\"Test that objects missing required fields are not recognized as cross-module compatible.\\\"\\\"\\\"\\n        from lfx.schema.cross_module import CrossModuleModel\\n\\n        class PartialData(CrossModuleModel):\\n            text_key: str\\n\\n        partial = PartialData(text_key=\\\"text\\\")\\n        # Should not be considered a full Data (missing data field)\\n        assert not isinstance(partial, LfxData)\\n        assert not isinstance(partial, LangflowData)\\n\\n\\nclass TestDuckTypingInputMixin:\\n    \\\"\\\"\\\"Tests for cross-module isinstance checks in BaseInputMixin and subclasses.\\\"\\\"\\\"\\n\\n    def test_base_input_mixin_is_cross_module(self):\\n        \\\"\\\"\\\"Test that BaseInputMixin uses CrossModuleModel.\\\"\\\"\\\"\\n        from lfx.inputs.input_mixin import BaseInputMixin\\n        from lfx.schema.cross_module import CrossModuleModel\\n\\n        # Check that BaseInputMixin inherits from CrossModuleModel\\n        assert issubclass(BaseInputMixin, CrossModuleModel)\\n\\n    def test_input_subclasses_inherit_cross_module(self):\\n        \\\"\\\"\\\"Test that all input types inherit cross-module support.\\\"\\\"\\\"\\n        from lfx.inputs.inputs import (\\n            BoolInput,\\n            DataInput,\\n            FloatInput,\\n            IntInput,\\n            MessageInput,\\n            StrInput,\\n        )\\n        from lfx.schema.cross_module import CrossModuleModel\\n\\n        for input_class in [StrInput, IntInput, FloatInput, BoolInput, DataInput, MessageInput]:\\n            assert issubclass(input_class, CrossModuleModel)\\n\\n    def test_input_instances_work_across_modules(self):\\n        \\\"\\\"\\\"Test that input instances work with duck-typing.\\\"\\\"\\\"\\n        from lfx.inputs.inputs import MessageInput\\n\\n        # Create with lfx Message\\n        lfx_msg = LfxMessage(text=\\\"hello\\\")\\n        input1 = MessageInput(name=\\\"test1\\\", value=lfx_msg)\\n\\n        # Create with langflow Message\\n        langflow_msg = LangflowMessage(text=\\\"world\\\")\\n        input2 = MessageInput(name=\\\"test2\\\", value=langflow_msg)\\n\\n        # Both should work\\n        assert input1.value.text == \\\"hello\\\"\\n        assert input2.value.text == \\\"world\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/schema/test_human_input_content_block.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"298dce3d39c830618f21d2e3781dc1263a9d9de0ee6c05243d80a59386b1e790\",\"content\":\"\\\"\\\"\\\"Contract: the `human_input` content type must validate in BOTH ContentType unions.\\n\\nlangflow-base and lfx each define a mirrored `ContentType` union. MessageRead uses\\none of them; the durable card uses the other. If a tag is added to one union but not\\nthe other, persisting the card fails at read-back with `union_tag_invalid`. This test\\nguards that drift for the HITL card.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom langflow.schema.content_block import ContentBlock as LangflowContentBlock\\nfrom lfx.schema.content_block import ContentBlock as LfxContentBlock\\n\\n_RAW = {\\n    \\\"type\\\": \\\"human_input\\\",\\n    \\\"request_id\\\": \\\"HumanInput-x:job-1\\\",\\n    \\\"job_id\\\": \\\"job-1\\\",\\n    \\\"prompt\\\": \\\"Approve refund?\\\",\\n    \\\"options\\\": [{\\\"action_id\\\": \\\"approve\\\", \\\"label\\\": \\\"Approve\\\"}],\\n    \\\"allowed_decisions\\\": [\\\"approve\\\"],\\n}\\n\\n\\n@pytest.mark.parametrize(\\\"content_block_cls\\\", [LangflowContentBlock, LfxContentBlock])\\ndef test_human_input_content_validates_in_both_unions(content_block_cls):\\n    block = content_block_cls(title=\\\"Human input required\\\", contents=[dict(_RAW)])\\n    content = block.contents[0]\\n    assert content.type == \\\"human_input\\\"\\n    assert content.request_id == \\\"HumanInput-x:job-1\\\"\\n    assert content.options[0][\\\"action_id\\\"] == \\\"approve\\\"\\n\\n\\n@pytest.mark.parametrize(\\\"content_block_cls\\\", [LangflowContentBlock, LfxContentBlock])\\ndef test_human_input_content_round_trips_through_json(content_block_cls):\\n    block = content_block_cls(title=\\\"Human input required\\\", contents=[dict(_RAW)])\\n    restored = content_block_cls.model_validate(block.model_dump())\\n    assert restored.contents[0].type == \\\"human_input\\\"\\n    assert restored.contents[0].submitted_action is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/schema/test_timestamp_validators.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"034e885267ab558ced676c1fdafabbd936b9a1707ab1738305ddd15c2518664a\",\"content\":\"\\\"\\\"\\\"Unit tests for timestamp validator functions in both langflow and lfx schemas.\\\"\\\"\\\"\\n\\nfrom datetime import datetime, timezone\\n\\nimport langflow.schema.validators as lf_validators\\nimport lfx.schema.validators as lfx_validators\\nimport pytest\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _utc(year, month, day, hour, minute, second, microsecond=0):\\n    return datetime(year, month, day, hour, minute, second, microsecond, tzinfo=timezone.utc)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Parametrize over both implementations so every test runs for both\\n# ---------------------------------------------------------------------------\\n\\nVALIDATOR_MODULES = [\\n    pytest.param(lf_validators, id=\\\"langflow\\\"),\\n    pytest.param(lfx_validators, id=\\\"lfx\\\"),\\n]\\n\\n\\n@pytest.mark.parametrize(\\\"mod\\\", VALIDATOR_MODULES)\\nclass TestTimestampToStr:\\n    \\\"\\\"\\\"timestamp_to_str converts various inputs to the canonical string format.\\\"\\\"\\\"\\n\\n    def test_datetime_with_microseconds_preserved(self, mod):\\n        dt = _utc(2024, 1, 15, 10, 30, 45, 123456)\\n        result = mod.timestamp_to_str(dt)\\n        assert result == \\\"2024-01-15 10:30:45.123456 UTC\\\"\\n\\n    def test_datetime_without_microseconds_zero_padded(self, mod):\\n        dt = _utc(2024, 6, 1, 0, 0, 0, 0)\\n        result = mod.timestamp_to_str(dt)\\n        assert result == \\\"2024-06-01 00:00:00.000000 UTC\\\"\\n\\n    def test_datetime_naive_treated_as_utc(self, mod):\\n        dt = datetime(2024, 3, 10, 8, 0, 0, 500000)  # noqa: DTZ001 \u2014 intentionally naive to test the fallback\\n        result = mod.timestamp_to_str(dt)\\n        assert result == \\\"2024-03-10 08:00:00.500000 UTC\\\"\\n\\n    def test_string_old_format_no_microseconds(self, mod):\\n        \\\"\\\"\\\"Backward compat: old format without microseconds must still parse.\\\"\\\"\\\"\\n        result = mod.timestamp_to_str(\\\"2024-06-15 10:30:00 UTC\\\")\\n        assert result == \\\"2024-06-15 10:30:00.000000 UTC\\\"\\n\\n    def test_string_new_format_with_microseconds(self, mod):\\n        result = mod.timestamp_to_str(\\\"2024-01-15 10:30:45.123456 UTC\\\")\\n        assert result == \\\"2024-01-15 10:30:45.123456 UTC\\\"\\n\\n    def test_string_iso_with_numeric_tz_offset_positive(self, mod):\\n        \\\"\\\"\\\"Non-UTC numeric offset must be converted correctly, not silently corrupted.\\\"\\\"\\\"\\n        # +05:00 means real UTC is 05:30:45\\n        result = mod.timestamp_to_str(\\\"2024-01-15T10:30:45+05:00\\\")\\n        assert result == \\\"2024-01-15 05:30:45.000000 UTC\\\"\\n\\n    def test_string_iso_with_numeric_tz_offset_negative(self, mod):\\n        # -03:00 means real UTC is 13:30:45\\n        result = mod.timestamp_to_str(\\\"2024-01-15T10:30:45-03:00\\\")\\n        assert result == \\\"2024-01-15 13:30:45.000000 UTC\\\"\\n\\n    def test_string_invalid_format_raises(self, mod):\\n        with pytest.raises(ValueError, match=\\\"Invalid timestamp format\\\"):\\n            mod.timestamp_to_str(\\\"not-a-date\\\")\\n\\n\\n@pytest.mark.parametrize(\\\"mod\\\", VALIDATOR_MODULES)\\nclass TestStrToTimestamp:\\n    \\\"\\\"\\\"str_to_timestamp converts strings (and datetimes) back to datetime objects.\\\"\\\"\\\"\\n\\n    def test_new_format_with_microseconds(self, mod):\\n        result = mod.str_to_timestamp(\\\"2024-01-15 10:30:45.123456 UTC\\\")\\n        assert result == _utc(2024, 1, 15, 10, 30, 45, 123456)\\n\\n    def test_old_format_without_microseconds_backward_compat(self, mod):\\n        \\\"\\\"\\\"Old-format strings must parse without crashing.\\\"\\\"\\\"\\n        result = mod.str_to_timestamp(\\\"2024-06-15 10:30:00 UTC\\\")\\n        assert result == _utc(2024, 6, 15, 10, 30, 0, 0)\\n\\n    def test_iso_with_numeric_tz_offset(self, mod):\\n        result = mod.str_to_timestamp(\\\"2024-01-15T10:30:45+05:00\\\")\\n        assert result == _utc(2024, 1, 15, 5, 30, 45, 0)\\n\\n    def test_passthrough_for_datetime_object(self, mod):\\n        dt = _utc(2024, 5, 20, 12, 0, 0, 999)\\n        assert mod.str_to_timestamp(dt) is dt\\n\\n    def test_invalid_string_raises(self, mod):\\n        with pytest.raises(ValueError, match=\\\"Invalid timestamp format\\\"):\\n            mod.str_to_timestamp(\\\"not-a-date\\\")\\n\\n\\n@pytest.mark.parametrize(\\\"mod\\\", VALIDATOR_MODULES)\\nclass TestRoundtrip:\\n    \\\"\\\"\\\"timestamp_to_str \u2194 str_to_timestamp must be lossless for microseconds.\\\"\\\"\\\"\\n\\n    def test_microseconds_survive_roundtrip(self, mod):\\n        original = _utc(2024, 11, 3, 22, 59, 59, 999999)\\n        as_str = mod.timestamp_to_str(original)\\n        recovered = mod.str_to_timestamp(as_str)\\n        assert recovered == original\\n\\n    def test_zero_microseconds_survive_roundtrip(self, mod):\\n        original = _utc(2024, 1, 1, 0, 0, 0, 0)\\n        as_str = mod.timestamp_to_str(original)\\n        recovered = mod.str_to_timestamp(as_str)\\n        assert recovered == original\\n\\n\\n@pytest.mark.parametrize(\\\"mod\\\", VALIDATOR_MODULES)\\nclass TestMessageOrdering:\\n    \\\"\\\"\\\"Two messages differing only by microseconds must maintain correct order.\\\"\\\"\\\"\\n\\n    def test_sub_second_ordering(self, mod):\\n        earlier = _utc(2024, 6, 15, 12, 0, 0, 1)\\n        later = _utc(2024, 6, 15, 12, 0, 0, 999999)\\n\\n        earlier_str = mod.timestamp_to_str(earlier)\\n        later_str = mod.timestamp_to_str(later)\\n\\n        # String comparison must preserve chronological order\\n        assert earlier_str < later_str\\n\\n        # And roundtrip back to datetime must also preserve order\\n        assert mod.str_to_timestamp(earlier_str) < mod.str_to_timestamp(later_str)\\n\\n\\nclass TestEncoderCompatibility:\\n    \\\"\\\"\\\"encode_datetime output must be parseable by both validator chains.\\\"\\\"\\\"\\n\\n    def test_encode_datetime_parseable_by_langflow_str_to_timestamp(self):\\n        from langflow.schema.encoders import encode_datetime\\n\\n        dt = _utc(2024, 8, 20, 14, 0, 0, 654321)\\n        encoded = encode_datetime(dt)\\n        recovered = lf_validators.str_to_timestamp(encoded)\\n        assert recovered == dt\\n\\n    def test_encode_datetime_parseable_by_lfx_str_to_timestamp(self):\\n        from langflow.schema.encoders import encode_datetime\\n\\n        dt = _utc(2024, 8, 20, 14, 0, 0, 654321)\\n        encoded = encode_datetime(dt)\\n        recovered = lfx_validators.str_to_timestamp(encoded)\\n        assert recovered == dt\\n\\n    def test_encode_datetime_includes_microseconds(self):\\n        from langflow.schema.encoders import encode_datetime\\n\\n        dt = _utc(2024, 1, 1, 0, 0, 0, 123456)\\n        result = encode_datetime(dt)\\n        assert \\\"123456\\\" in result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/scripts/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/scripts/test_migrate_secret_key.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a602a365e0e3fcdce9e73fadbd25141271de7be9d9452c354926c2c3f251c02\",\"content\":\"\\\"\\\"\\\"Tests for the secret key migration script.\\\"\\\"\\\"\\n\\nimport importlib.util\\nimport json\\nimport secrets\\nimport sys\\nimport tempfile\\nfrom pathlib import Path\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom cryptography.exceptions import InvalidTag\\nfrom cryptography.fernet import Fernet\\nfrom httpx import AsyncClient\\nfrom langflow.services.deps import get_settings_service\\nfrom langflow.services.variable.constants import CREDENTIAL_TYPE\\nfrom sqlalchemy import create_engine, text\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef migrate_module():\\n    \\\"\\\"\\\"Load the migrate_secret_key module from scripts directory.\\\"\\\"\\\"\\n    # Test file is at: src/backend/tests/unit/scripts/test_migrate_secret_key.py\\n    # Script is at: scripts/migrate_secret_key.py\\n    # Need to go up 5 levels to repo root, then into scripts/\\n    test_file = Path(__file__).resolve()\\n    repo_root = test_file.parents[5]  # Goes to langflow repo root\\n    script_path = repo_root / \\\"scripts\\\" / \\\"migrate_secret_key.py\\\"\\n\\n    if not script_path.exists():\\n        pytest.skip(f\\\"migrate_secret_key.py script not found at {script_path}\\\")\\n\\n    spec = importlib.util.spec_from_file_location(\\\"migrate_secret_key\\\", script_path)\\n    module = importlib.util.module_from_spec(spec)\\n    sys.modules[\\\"migrate_secret_key\\\"] = module\\n    spec.loader.exec_module(module)\\n    return module\\n\\n\\n@pytest.fixture\\ndef old_key():\\n    \\\"\\\"\\\"Generate a valid old secret key.\\\"\\\"\\\"\\n    return secrets.token_urlsafe(32)\\n\\n\\n@pytest.fixture\\ndef new_key():\\n    \\\"\\\"\\\"Generate a valid new secret key.\\\"\\\"\\\"\\n    return secrets.token_urlsafe(32)\\n\\n\\n@pytest.fixture\\ndef short_old_key():\\n    \\\"\\\"\\\"A short key that triggers the seed-based generation.\\\"\\\"\\\"\\n    return \\\"short-key\\\"\\n\\n\\n@pytest.fixture\\ndef short_new_key():\\n    \\\"\\\"\\\"A different short key.\\\"\\\"\\\"\\n    return \\\"other-short\\\"\\n\\n\\n@pytest.fixture\\ndef sqlite_db():\\n    \\\"\\\"\\\"Create an in-memory SQLite database with the required tables.\\\"\\\"\\\"\\n    engine = create_engine(\\\"sqlite:///:memory:\\\")\\n    with engine.connect() as conn:\\n        conn.execute(\\n            text(\\\"\\\"\\\"\\n            CREATE TABLE \\\"user\\\" (\\n                id TEXT PRIMARY KEY,\\n                store_api_key TEXT\\n            )\\n        \\\"\\\"\\\")\\n        )\\n        conn.execute(\\n            text(\\\"\\\"\\\"\\n            CREATE TABLE variable (\\n                id TEXT PRIMARY KEY,\\n                name TEXT,\\n                value TEXT,\\n                type TEXT\\n            )\\n        \\\"\\\"\\\")\\n        )\\n        conn.execute(\\n            text(\\\"\\\"\\\"\\n            CREATE TABLE folder (\\n                id TEXT PRIMARY KEY,\\n                name TEXT,\\n                auth_settings TEXT\\n            )\\n        \\\"\\\"\\\")\\n        )\\n        conn.execute(\\n            text(\\\"\\\"\\\"\\n            CREATE TABLE sso_config (\\n                id TEXT PRIMARY KEY,\\n                client_secret_encrypted TEXT\\n            )\\n        \\\"\\\"\\\")\\n        )\\n        conn.commit()\\n    return engine\\n\\n\\nclass TestEnsureValidKey:\\n    \\\"\\\"\\\"Tests for ensure_valid_key function.\\\"\\\"\\\"\\n\\n    def test_long_key_padded(self, migrate_module, old_key):\\n        \\\"\\\"\\\"Long keys should be padded to valid base64.\\\"\\\"\\\"\\n        result = migrate_module.ensure_valid_key(old_key)\\n        assert isinstance(result, bytes)\\n        Fernet(result)\\n\\n    def test_short_key_generates_valid_key(self, migrate_module, short_old_key):\\n        \\\"\\\"\\\"Short keys should generate a valid Fernet key via seeding.\\\"\\\"\\\"\\n        result = migrate_module.ensure_valid_key(short_old_key)\\n        assert isinstance(result, bytes)\\n        Fernet(result)\\n\\n    def test_same_short_key_produces_same_result(self, migrate_module, short_old_key):\\n        \\\"\\\"\\\"Same short key should always produce the same Fernet key.\\\"\\\"\\\"\\n        result1 = migrate_module.ensure_valid_key(short_old_key)\\n        result2 = migrate_module.ensure_valid_key(short_old_key)\\n        assert result1 == result2\\n\\n    def test_different_short_keys_produce_different_results(self, migrate_module, short_old_key, short_new_key):\\n        \\\"\\\"\\\"Different short keys should produce different Fernet keys.\\\"\\\"\\\"\\n        result1 = migrate_module.ensure_valid_key(short_old_key)\\n        result2 = migrate_module.ensure_valid_key(short_new_key)\\n        assert result1 != result2\\n\\n\\nclass TestEncryptDecrypt:\\n    \\\"\\\"\\\"Tests for encrypt_with_key and decrypt_with_key functions.\\\"\\\"\\\"\\n\\n    def test_encrypt_decrypt_roundtrip(self, migrate_module, old_key):\\n        \\\"\\\"\\\"Encrypting then decrypting should return original value.\\\"\\\"\\\"\\n        plaintext = \\\"my-secret-api-key-12345\\\"\\n        encrypted = migrate_module.encrypt_with_key(plaintext, old_key)\\n        decrypted = migrate_module.decrypt_with_key(encrypted, old_key)\\n        assert decrypted == plaintext\\n\\n    def test_encrypt_produces_different_output(self, migrate_module, old_key):\\n        \\\"\\\"\\\"Encryption should produce ciphertext different from plaintext.\\\"\\\"\\\"\\n        plaintext = \\\"my-secret-api-key-12345\\\"\\n        encrypted = migrate_module.encrypt_with_key(plaintext, old_key)\\n        assert encrypted != plaintext\\n        assert encrypted.startswith(\\\"gAAAAAB\\\")\\n\\n    def test_decrypt_with_wrong_key_fails(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"Decrypting with wrong key should raise an error.\\\"\\\"\\\"\\n        from cryptography.fernet import InvalidToken\\n\\n        plaintext = \\\"my-secret-api-key-12345\\\"\\n        encrypted = migrate_module.encrypt_with_key(plaintext, old_key)\\n        with pytest.raises(InvalidToken):\\n            migrate_module.decrypt_with_key(encrypted, new_key)\\n\\n    def test_sso_secret_rewrap_uses_replacement_key(self, migrate_module, old_key, new_key):\\n        plaintext = \\\"oidc-client-secret\\\"\\n        encrypted = migrate_module.encrypt_sso_secret_with_key(plaintext, old_key)\\n\\n        migrated = migrate_module.migrate_sso_secret(encrypted, old_key, new_key)\\n\\n        assert migrated is not None\\n        assert migrated != encrypted\\n        assert migrate_module.decrypt_sso_secret_with_key(migrated, new_key) == plaintext\\n        with pytest.raises(InvalidTag):\\n            migrate_module.decrypt_sso_secret_with_key(migrated, old_key)\\n\\n    @pytest.mark.parametrize(\\\"payload_index\\\", [4, 5], ids=[\\\"nonce\\\", \\\"ciphertext\\\"])\\n    @pytest.mark.parametrize(\\\"invalid_character\\\", [\\\"!\\\", \\\"+\\\", \\\"/\\\"])\\n    def test_sso_secret_rewrap_rejects_non_base64url_payload_characters(\\n        self,\\n        migrate_module,\\n        old_key,\\n        new_key,\\n        payload_index,\\n        invalid_character,\\n    ):\\n        encrypted = migrate_module.encrypt_sso_secret_with_key(\\\"oidc-client-secret\\\", old_key)\\n        parts = encrypted.split(\\\":\\\")\\n        parts[payload_index] = f\\\"{invalid_character}{parts[payload_index][1:]}\\\"\\n        malformed_envelope = \\\":\\\".join(parts)\\n\\n        with pytest.raises(ValueError, match=\\\"Invalid base64url data\\\"):\\n            migrate_module._decode_sso_envelope(malformed_envelope)\\n        assert migrate_module.migrate_sso_secret(malformed_envelope, old_key, new_key) is None\\n\\n    def test_encrypt_decrypt_with_short_keys(self, migrate_module, short_old_key):\\n        \\\"\\\"\\\"Short keys should work for encryption/decryption.\\\"\\\"\\\"\\n        plaintext = \\\"secret-value\\\"\\n        encrypted = migrate_module.encrypt_with_key(plaintext, short_old_key)\\n        decrypted = migrate_module.decrypt_with_key(encrypted, short_old_key)\\n        assert decrypted == plaintext\\n\\n\\nclass TestMigrateValue:\\n    \\\"\\\"\\\"Tests for migrate_value function.\\\"\\\"\\\"\\n\\n    def test_migrate_value_success(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"Successfully migrate a value from old key to new key.\\\"\\\"\\\"\\n        plaintext = \\\"original-secret\\\"\\n        old_encrypted = migrate_module.encrypt_with_key(plaintext, old_key)\\n\\n        new_encrypted = migrate_module.migrate_value(old_encrypted, old_key, new_key)\\n\\n        assert new_encrypted is not None\\n        assert new_encrypted != old_encrypted\\n        decrypted = migrate_module.decrypt_with_key(new_encrypted, new_key)\\n        assert decrypted == plaintext\\n\\n    def test_migrate_value_wrong_old_key(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"Migration should return None if old key doesn't decrypt.\\\"\\\"\\\"\\n        plaintext = \\\"original-secret\\\"\\n        encrypted = migrate_module.encrypt_with_key(plaintext, old_key)\\n        wrong_key = secrets.token_urlsafe(32)\\n\\n        result = migrate_module.migrate_value(encrypted, wrong_key, new_key)\\n        assert result is None\\n\\n    def test_migrate_value_invalid_ciphertext(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"Migration should return None for invalid ciphertext.\\\"\\\"\\\"\\n        result = migrate_module.migrate_value(\\\"not-valid-ciphertext\\\", old_key, new_key)\\n        assert result is None\\n\\n\\nclass TestMigrateAuthSettings:\\n    \\\"\\\"\\\"Tests for migrate_auth_settings function.\\\"\\\"\\\"\\n\\n    def test_migrate_oauth_client_secret(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"oauth_client_secret should be re-encrypted.\\\"\\\"\\\"\\n        secret = \\\"my-oauth-secret\\\"  # noqa: S105  # pragma: allowlist secret\\n        auth_settings = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_client_id\\\": \\\"client-123\\\",\\n            \\\"oauth_client_secret\\\": migrate_module.encrypt_with_key(secret, old_key),\\n        }\\n\\n        migrated, failed_fields = migrate_module.migrate_auth_settings(auth_settings, old_key, new_key)\\n\\n        assert failed_fields == []\\n        assert migrated[\\\"auth_type\\\"] == \\\"oauth\\\"\\n        assert migrated[\\\"oauth_client_id\\\"] == \\\"client-123\\\"\\n        assert migrated[\\\"oauth_client_secret\\\"] != auth_settings[\\\"oauth_client_secret\\\"]\\n        decrypted = migrate_module.decrypt_with_key(migrated[\\\"oauth_client_secret\\\"], new_key)\\n        assert decrypted == secret\\n\\n    def test_migrate_api_key_field(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"api_key field should be re-encrypted.\\\"\\\"\\\"\\n        api_key = \\\"sk-test-key\\\"  # pragma: allowlist secret\\n        auth_settings = {\\n            \\\"auth_type\\\": \\\"api\\\",\\n            \\\"api_key\\\": migrate_module.encrypt_with_key(api_key, old_key),\\n        }\\n\\n        migrated, failed_fields = migrate_module.migrate_auth_settings(auth_settings, old_key, new_key)\\n\\n        assert failed_fields == []\\n        decrypted = migrate_module.decrypt_with_key(migrated[\\\"api_key\\\"], new_key)\\n        assert decrypted == api_key\\n\\n    def test_migrate_preserves_non_sensitive_fields(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"Non-sensitive fields should be preserved unchanged.\\\"\\\"\\\"\\n        auth_settings = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": 3000,\\n            \\\"oauth_client_id\\\": \\\"my-client\\\",\\n            \\\"oauth_client_secret\\\": migrate_module.encrypt_with_key(\\\"secret\\\", old_key),\\n        }\\n\\n        migrated, failed_fields = migrate_module.migrate_auth_settings(auth_settings, old_key, new_key)\\n\\n        assert failed_fields == []\\n        assert migrated[\\\"auth_type\\\"] == auth_settings[\\\"auth_type\\\"]\\n        assert migrated[\\\"oauth_host\\\"] == auth_settings[\\\"oauth_host\\\"]\\n        assert migrated[\\\"oauth_port\\\"] == auth_settings[\\\"oauth_port\\\"]\\n        assert migrated[\\\"oauth_client_id\\\"] == auth_settings[\\\"oauth_client_id\\\"]\\n\\n    def test_migrate_empty_sensitive_fields(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"Empty/None sensitive fields should be handled gracefully.\\\"\\\"\\\"\\n        auth_settings = {\\n            \\\"auth_type\\\": \\\"api\\\",\\n            \\\"api_key\\\": None,\\n            \\\"oauth_client_secret\\\": \\\"\\\",\\n        }\\n\\n        migrated, failed_fields = migrate_module.migrate_auth_settings(auth_settings, old_key, new_key)\\n\\n        assert failed_fields == []\\n        assert migrated[\\\"api_key\\\"] is None\\n        assert migrated[\\\"oauth_client_secret\\\"] == \\\"\\\"\\n\\n    def test_migrate_returns_failed_fields_for_invalid_encryption(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"Invalid encrypted fields should be reported in failed_fields.\\\"\\\"\\\"\\n        auth_settings = {\\n            \\\"auth_type\\\": \\\"api\\\",\\n            \\\"api_key\\\": \\\"not-valid-encrypted-data\\\",  # Invalid ciphertext  # pragma: allowlist secret\\n            \\\"oauth_client_secret\\\": migrate_module.encrypt_with_key(\\\"valid-secret\\\", old_key),\\n        }\\n\\n        migrated, failed_fields = migrate_module.migrate_auth_settings(auth_settings, old_key, new_key)\\n\\n        assert \\\"api_key\\\" in failed_fields\\n        assert \\\"oauth_client_secret\\\" not in failed_fields\\n        # oauth_client_secret should still be migrated\\n        decrypted = migrate_module.decrypt_with_key(migrated[\\\"oauth_client_secret\\\"], new_key)\\n        assert decrypted == \\\"valid-secret\\\"\\n\\n\\nclass TestDatabaseMigrationUnit:\\n    \\\"\\\"\\\"Unit tests for database migration with in-memory SQLite.\\\"\\\"\\\"\\n\\n    def test_migrate_user_store_api_key(self, migrate_module, sqlite_db, old_key, new_key):\\n        \\\"\\\"\\\"Test migrating user.store_api_key column.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        original_value = \\\"langflow-store-api-key\\\"\\n        encrypted_value = migrate_module.encrypt_with_key(original_value, old_key)\\n\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text('INSERT INTO \\\"user\\\" (id, store_api_key) VALUES (:id, :key)'),\\n                {\\\"id\\\": user_id, \\\"key\\\": encrypted_value},\\n            )\\n            conn.commit()\\n\\n            users = conn.execute(\\n                text('SELECT id, store_api_key FROM \\\"user\\\" WHERE store_api_key IS NOT NULL')\\n            ).fetchall()\\n\\n            for uid, encrypted_key in users:\\n                new_encrypted = migrate_module.migrate_value(encrypted_key, old_key, new_key)\\n                assert new_encrypted is not None\\n                conn.execute(\\n                    text('UPDATE \\\"user\\\" SET store_api_key = :val WHERE id = :id'),\\n                    {\\\"val\\\": new_encrypted, \\\"id\\\": uid},\\n                )\\n            conn.commit()\\n\\n            result = conn.execute(text('SELECT store_api_key FROM \\\"user\\\" WHERE id = :id'), {\\\"id\\\": user_id}).fetchone()\\n            decrypted = migrate_module.decrypt_with_key(result[0], new_key)\\n            assert decrypted == original_value\\n\\n    def test_migrate_variable_values(self, migrate_module, sqlite_db, old_key, new_key):\\n        \\\"\\\"\\\"Test migrating variable.value column.\\\"\\\"\\\"\\n        var_id = str(uuid4())\\n        original_value = \\\"my-openai-api-key\\\"\\n        encrypted_value = migrate_module.encrypt_with_key(original_value, old_key)\\n\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text(\\\"INSERT INTO variable (id, name, value, type) VALUES (:id, :name, :value, :type)\\\"),\\n                {\\\"id\\\": var_id, \\\"name\\\": \\\"OPENAI_API_KEY\\\", \\\"value\\\": encrypted_value, \\\"type\\\": \\\"Credential\\\"},\\n            )\\n            conn.commit()\\n\\n            variables = conn.execute(text(\\\"SELECT id, name, value FROM variable\\\")).fetchall()\\n\\n            for vid, _, encrypted_val in variables:\\n                if encrypted_val:\\n                    new_encrypted = migrate_module.migrate_value(encrypted_val, old_key, new_key)\\n                    assert new_encrypted is not None\\n                    conn.execute(\\n                        text(\\\"UPDATE variable SET value = :val WHERE id = :id\\\"),\\n                        {\\\"val\\\": new_encrypted, \\\"id\\\": vid},\\n                    )\\n            conn.commit()\\n\\n            result = conn.execute(text(\\\"SELECT value FROM variable WHERE id = :id\\\"), {\\\"id\\\": var_id}).fetchone()\\n            decrypted = migrate_module.decrypt_with_key(result[0], new_key)\\n            assert decrypted == original_value\\n\\n    def test_migrate_folder_auth_settings(self, migrate_module, sqlite_db, old_key, new_key):\\n        \\\"\\\"\\\"Test migrating folder.auth_settings JSON column.\\\"\\\"\\\"\\n        folder_id = str(uuid4())\\n        oauth_secret = \\\"my-oauth-secret\\\"  # noqa: S105  # pragma: allowlist secret\\n        auth_settings = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_client_id\\\": \\\"client-123\\\",\\n            \\\"oauth_client_secret\\\": migrate_module.encrypt_with_key(oauth_secret, old_key),\\n        }\\n\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text(\\\"INSERT INTO folder (id, name, auth_settings) VALUES (:id, :name, :settings)\\\"),\\n                {\\\"id\\\": folder_id, \\\"name\\\": \\\"My Project\\\", \\\"settings\\\": json.dumps(auth_settings)},\\n            )\\n            conn.commit()\\n\\n            folders = conn.execute(\\n                text(\\\"SELECT id, name, auth_settings FROM folder WHERE auth_settings IS NOT NULL\\\")\\n            ).fetchall()\\n\\n            for fid, _, settings_json in folders:\\n                settings_dict = json.loads(settings_json)\\n                new_settings, failed_fields = migrate_module.migrate_auth_settings(settings_dict, old_key, new_key)\\n                assert failed_fields == []\\n                conn.execute(\\n                    text(\\\"UPDATE folder SET auth_settings = :val WHERE id = :id\\\"),\\n                    {\\\"val\\\": json.dumps(new_settings), \\\"id\\\": fid},\\n                )\\n            conn.commit()\\n\\n            result = conn.execute(text(\\\"SELECT auth_settings FROM folder WHERE id = :id\\\"), {\\\"id\\\": folder_id}).fetchone()\\n            migrated_settings = json.loads(result[0])\\n            decrypted_secret = migrate_module.decrypt_with_key(migrated_settings[\\\"oauth_client_secret\\\"], new_key)\\n            assert decrypted_secret == oauth_secret\\n            assert migrated_settings[\\\"oauth_client_id\\\"] == \\\"client-123\\\"\\n\\n\\nclass TestKeyFileManagement:\\n    \\\"\\\"\\\"Tests for secret key file read/write operations.\\\"\\\"\\\"\\n\\n    def test_read_secret_key_from_file(self, migrate_module):\\n        \\\"\\\"\\\"Test reading secret key from config directory.\\\"\\\"\\\"\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            config_dir = Path(tmpdir)\\n            secret_file = config_dir / \\\"secret_key\\\"\\n            test_key = \\\"test-secret-key-12345\\\"\\n            secret_file.write_text(test_key)\\n\\n            result = migrate_module.read_secret_key_from_file(config_dir)\\n            assert result == test_key\\n\\n    def test_read_secret_key_strips_whitespace(self, migrate_module):\\n        \\\"\\\"\\\"Test that reading strips whitespace from key.\\\"\\\"\\\"\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            config_dir = Path(tmpdir)\\n            secret_file = config_dir / \\\"secret_key\\\"\\n            secret_file.write_text(\\\"  test-key-with-spaces  \\\\n\\\")\\n\\n            result = migrate_module.read_secret_key_from_file(config_dir)\\n            assert result == \\\"test-key-with-spaces\\\"\\n\\n    def test_read_secret_key_returns_none_if_missing(self, migrate_module):\\n        \\\"\\\"\\\"Test that reading returns None if file doesn't exist.\\\"\\\"\\\"\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            config_dir = Path(tmpdir)\\n            result = migrate_module.read_secret_key_from_file(config_dir)\\n            assert result is None\\n\\n    def test_write_secret_key_creates_file(self, migrate_module):\\n        \\\"\\\"\\\"Test writing secret key creates file with correct content.\\\"\\\"\\\"\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            config_dir = Path(tmpdir)\\n            test_key = \\\"new-secret-key-67890\\\"\\n\\n            migrate_module.write_secret_key_to_file(config_dir, test_key)\\n\\n            secret_file = config_dir / \\\"secret_key\\\"\\n            assert secret_file.exists()\\n            assert secret_file.read_text() == test_key\\n\\n    def test_write_secret_key_creates_parent_dirs(self, migrate_module):\\n        \\\"\\\"\\\"Test writing creates parent directories if needed.\\\"\\\"\\\"\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            config_dir = Path(tmpdir) / \\\"nested\\\" / \\\"config\\\"\\n            test_key = \\\"nested-key\\\"\\n\\n            migrate_module.write_secret_key_to_file(config_dir, test_key)\\n\\n            secret_file = config_dir / \\\"secret_key\\\"\\n            assert secret_file.exists()\\n\\n    def test_write_secret_key_custom_filename(self, migrate_module):\\n        \\\"\\\"\\\"Test writing with custom filename for backups.\\\"\\\"\\\"\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            config_dir = Path(tmpdir)\\n            test_key = \\\"backup-key\\\"\\n\\n            migrate_module.write_secret_key_to_file(config_dir, test_key, \\\"secret_key.backup\\\")\\n\\n            backup_file = config_dir / \\\"secret_key.backup\\\"\\n            assert backup_file.exists()\\n            assert backup_file.read_text() == test_key\\n\\n    def test_get_config_dir_default(self, migrate_module, monkeypatch):\\n        \\\"\\\"\\\"Test default config directory uses platformdirs.\\\"\\\"\\\"\\n        from platformdirs import user_cache_dir\\n\\n        monkeypatch.delenv(\\\"LANGFLOW_CONFIG_DIR\\\", raising=False)\\n        result = migrate_module.get_config_dir()\\n        expected = Path(user_cache_dir(\\\"langflow\\\", \\\"langflow\\\"))\\n        assert result == expected\\n\\n    def test_get_config_dir_from_env(self, migrate_module, monkeypatch):\\n        \\\"\\\"\\\"Test config directory from environment variable.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_CONFIG_DIR\\\", \\\"/custom/config\\\")\\n        result = migrate_module.get_config_dir()\\n        assert result == Path(\\\"/custom/config\\\")\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nclass TestMigrationWithRealDatabase:\\n    \\\"\\\"\\\"Integration tests using real Langflow database fixtures.\\\"\\\"\\\"\\n\\n    async def test_credential_variable_stored_encrypted(\\n        self,\\n        migrate_module,  # noqa: ARG002\\n        client: AsyncClient,\\n        active_user,  # noqa: ARG002\\n        logged_in_headers,\\n    ):\\n        \\\"\\\"\\\"Test that credential variables are stored encrypted in the database.\\n\\n        The API returns None for credential values (for security), so we verify\\n        that the value is different from the original - which means it's encrypted.\\n\\n        The migration script handles these encrypted values and re-encrypts them\\n        with a new key - this is tested in the unit tests.\\n        \\\"\\\"\\\"\\n        client.follow_redirects = True\\n\\n        # Create a credential variable via API\\n        var_name = f\\\"TEST_API_KEY_{uuid4().hex[:8]}\\\"\\n        credential_variable = {\\n            \\\"name\\\": var_name,\\n            \\\"value\\\": \\\"sk-test-secret-value-12345\\\",\\n            \\\"type\\\": CREDENTIAL_TYPE,\\n            \\\"default_fields\\\": [],\\n        }\\n        response = await client.post(\\\"api/v1/variables/\\\", json=credential_variable, headers=logged_in_headers)\\n        assert response.status_code == 201\\n        created_var = response.json()\\n\\n        # Read the variable back\\n        response = await client.get(\\\"api/v1/variables/\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        all_vars = response.json()\\n\\n        # Find our variable\\n        our_var = next((v for v in all_vars if v[\\\"name\\\"] == var_name), None)\\n        assert our_var is not None\\n\\n        # For credentials, the API returns None for security (value is encrypted in DB)\\n        # This is expected behavior - the migration script works on the raw DB values\\n        assert our_var[\\\"value\\\"] is None or our_var[\\\"value\\\"] != credential_variable[\\\"value\\\"]\\n\\n        # Cleanup\\n        await client.delete(f\\\"api/v1/variables/{created_var['id']}\\\", headers=logged_in_headers)\\n\\n    async def test_create_folder_via_api(\\n        self,\\n        migrate_module,  # noqa: ARG002\\n        client: AsyncClient,\\n        active_user,  # noqa: ARG002\\n        logged_in_headers,\\n    ):\\n        \\\"\\\"\\\"Test that folders can be created via API.\\\"\\\"\\\"\\n        client.follow_redirects = True\\n\\n        project_data = {\\n            \\\"name\\\": f\\\"Test Project {uuid4().hex[:8]}\\\",\\n            \\\"description\\\": \\\"Test project for migration\\\",\\n        }\\n        response = await client.post(\\\"api/v1/folders/\\\", json=project_data, headers=logged_in_headers)\\n        assert response.status_code == 201\\n        created_folder = response.json()\\n\\n        # Cleanup\\n        await client.delete(f\\\"api/v1/folders/{created_folder['id']}\\\", headers=logged_in_headers)\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nclass TestMigrationCompatibility:\\n    \\\"\\\"\\\"Test that migration script is compatible with Langflow's encryption.\\\"\\\"\\\"\\n\\n    def test_script_encryption_matches_langflow(self, migrate_module):\\n        \\\"\\\"\\\"Verify migration script produces same results as Langflow's auth utils.\\\"\\\"\\\"\\n        from langflow.services.auth import utils as auth_utils\\n\\n        settings_service = get_settings_service()\\n        secret_key = settings_service.auth_settings.SECRET_KEY.get_secret_value()\\n\\n        plaintext = \\\"test-api-key-compatibility\\\"\\n\\n        # Encrypt with Langflow\\n        langflow_encrypted = auth_utils.encrypt_api_key(plaintext, settings_service)\\n\\n        # Decrypt with migration script\\n        script_decrypted = migrate_module.decrypt_with_key(langflow_encrypted, secret_key)\\n        assert script_decrypted == plaintext\\n\\n        # Encrypt with migration script\\n        script_encrypted = migrate_module.encrypt_with_key(plaintext, secret_key)\\n\\n        # Decrypt with Langflow\\n        langflow_decrypted = auth_utils.decrypt_api_key(script_encrypted, settings_service)\\n        assert langflow_decrypted == plaintext\\n\\n\\nclass TestTransactionAtomicity:\\n    \\\"\\\"\\\"Tests for atomic transaction behavior.\\\"\\\"\\\"\\n\\n    def test_transaction_rollback_on_error(self, migrate_module, sqlite_db, old_key, new_key):\\n        \\\"\\\"\\\"Test that database changes are rolled back if an error occurs mid-migration.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        original_value = \\\"user-api-key\\\"\\n        encrypted_value = migrate_module.encrypt_with_key(original_value, old_key)\\n\\n        # Insert test data\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text('INSERT INTO \\\"user\\\" (id, store_api_key) VALUES (:id, :key)'),\\n                {\\\"id\\\": user_id, \\\"key\\\": encrypted_value},\\n            )\\n            conn.commit()\\n\\n        # Simulate a failed migration using begin() - any exception causes rollback\\n        try:\\n            with sqlite_db.begin() as conn:\\n                # Update the user's key\\n                new_encrypted = migrate_module.migrate_value(encrypted_value, old_key, new_key)\\n                conn.execute(\\n                    text('UPDATE \\\"user\\\" SET store_api_key = :val WHERE id = :id'),\\n                    {\\\"val\\\": new_encrypted, \\\"id\\\": user_id},\\n                )\\n                # Simulate an error before commit\\n                msg = \\\"Simulated failure\\\"\\n                raise RuntimeError(msg)\\n        except RuntimeError:\\n            pass\\n\\n        # Verify the original value was preserved (transaction was rolled back)\\n        with sqlite_db.connect() as conn:\\n            result = conn.execute(text('SELECT store_api_key FROM \\\"user\\\" WHERE id = :id'), {\\\"id\\\": user_id}).fetchone()\\n            assert result[0] == encrypted_value  # Original value preserved\\n\\n    def test_partial_migration_does_not_persist(self, migrate_module, sqlite_db, old_key, new_key):\\n        \\\"\\\"\\\"Test that partial migrations don't leave database in inconsistent state.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        var_id = str(uuid4())\\n        user_value = \\\"user-secret\\\"\\n        var_value = \\\"var-secret\\\"\\n\\n        # Insert test data\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text('INSERT INTO \\\"user\\\" (id, store_api_key) VALUES (:id, :key)'),\\n                {\\\"id\\\": user_id, \\\"key\\\": migrate_module.encrypt_with_key(user_value, old_key)},\\n            )\\n            encrypted_var = migrate_module.encrypt_with_key(var_value, old_key)\\n            conn.execute(\\n                text(\\\"INSERT INTO variable (id, name, value, type) VALUES (:id, :name, :value, :type)\\\"),\\n                {\\\"id\\\": var_id, \\\"name\\\": \\\"TEST_VAR\\\", \\\"value\\\": encrypted_var, \\\"type\\\": \\\"Credential\\\"},\\n            )\\n            conn.commit()\\n\\n        original_user_key = None\\n        original_var_value = None\\n        with sqlite_db.connect() as conn:\\n            original_user_key = conn.execute(\\n                text('SELECT store_api_key FROM \\\"user\\\" WHERE id = :id'), {\\\"id\\\": user_id}\\n            ).fetchone()[0]\\n            original_var_value = conn.execute(\\n                text(\\\"SELECT value FROM variable WHERE id = :id\\\"), {\\\"id\\\": var_id}\\n            ).fetchone()[0]\\n\\n        # Attempt migration with failure after first table\\n        try:\\n            with sqlite_db.begin() as conn:\\n                # Migrate user table successfully\\n                new_encrypted = migrate_module.migrate_value(original_user_key, old_key, new_key)\\n                conn.execute(\\n                    text('UPDATE \\\"user\\\" SET store_api_key = :val WHERE id = :id'),\\n                    {\\\"val\\\": new_encrypted, \\\"id\\\": user_id},\\n                )\\n                # Fail before variable table\\n                msg = \\\"Simulated failure after partial migration\\\"\\n                raise RuntimeError(msg)\\n        except RuntimeError:\\n            pass\\n\\n        # Both tables should be unchanged\\n        with sqlite_db.connect() as conn:\\n            user_result = conn.execute(\\n                text('SELECT store_api_key FROM \\\"user\\\" WHERE id = :id'), {\\\"id\\\": user_id}\\n            ).fetchone()\\n            var_result = conn.execute(text(\\\"SELECT value FROM variable WHERE id = :id\\\"), {\\\"id\\\": var_id}).fetchone()\\n            assert user_result[0] == original_user_key\\n            assert var_result[0] == original_var_value\\n\\n\\nclass TestErrorHandling:\\n    \\\"\\\"\\\"Tests for error handling scenarios.\\\"\\\"\\\"\\n\\n    def test_migration_handles_invalid_encrypted_data(self, migrate_module, sqlite_db, old_key, new_key):\\n        \\\"\\\"\\\"Test that migration continues when encountering invalid encrypted data.\\\"\\\"\\\"\\n        valid_id = str(uuid4())\\n        invalid_id = str(uuid4())\\n        valid_value = \\\"valid-secret\\\"\\n\\n        with sqlite_db.connect() as conn:\\n            # Insert valid encrypted data\\n            conn.execute(\\n                text('INSERT INTO \\\"user\\\" (id, store_api_key) VALUES (:id, :key)'),\\n                {\\\"id\\\": valid_id, \\\"key\\\": migrate_module.encrypt_with_key(valid_value, old_key)},\\n            )\\n            # Insert invalid/corrupted encrypted data\\n            conn.execute(\\n                text('INSERT INTO \\\"user\\\" (id, store_api_key) VALUES (:id, :key)'),\\n                {\\\"id\\\": invalid_id, \\\"key\\\": \\\"not-valid-encrypted-data\\\"},\\n            )\\n            conn.commit()\\n\\n        # migrate_value returns None for invalid data, allowing migration to continue\\n        with sqlite_db.connect() as conn:\\n            users = conn.execute(text('SELECT id, store_api_key FROM \\\"user\\\"')).fetchall()\\n\\n            migrated_count = 0\\n            failed_count = 0\\n            for _uid, encrypted_key in users:\\n                new_encrypted = migrate_module.migrate_value(encrypted_key, old_key, new_key)\\n                if new_encrypted:\\n                    migrated_count += 1\\n                else:\\n                    failed_count += 1\\n\\n            assert migrated_count == 1  # Valid entry was migrated\\n            assert failed_count == 1  # Invalid entry failed gracefully\\n\\n    def test_migration_handles_null_values(\\n        self,\\n        migrate_module,  # noqa: ARG002\\n        sqlite_db,\\n        old_key,  # noqa: ARG002\\n        new_key,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"Test that migration handles NULL values correctly.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text('INSERT INTO \\\"user\\\" (id, store_api_key) VALUES (:id, NULL)'),\\n                {\\\"id\\\": user_id},\\n            )\\n            conn.commit()\\n\\n        # NULL values should not cause errors\\n        with sqlite_db.connect() as conn:\\n            result = conn.execute(\\n                text('SELECT id, store_api_key FROM \\\"user\\\" WHERE id = :id'), {\\\"id\\\": user_id}\\n            ).fetchone()\\n            assert result[1] is None\\n\\n    def test_migration_handles_empty_auth_settings(self, migrate_module, old_key, new_key):\\n        \\\"\\\"\\\"Test that migration handles empty auth_settings dict.\\\"\\\"\\\"\\n        empty_settings = {}\\n        result, failed_fields = migrate_module.migrate_auth_settings(empty_settings, old_key, new_key)\\n        assert result == {}\\n        assert failed_fields == []\\n\\n    def test_migration_handles_malformed_json_gracefully(\\n        self,\\n        migrate_module,  # noqa: ARG002\\n        sqlite_db,\\n        old_key,  # noqa: ARG002\\n        new_key,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"Test that malformed JSON in auth_settings is handled gracefully.\\\"\\\"\\\"\\n        folder_id = str(uuid4())\\n\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text(\\\"INSERT INTO folder (id, name, auth_settings) VALUES (:id, :name, :settings)\\\"),\\n                {\\\"id\\\": folder_id, \\\"name\\\": \\\"Bad Folder\\\", \\\"settings\\\": \\\"not-valid-json{\\\"},\\n            )\\n            conn.commit()\\n\\n        # Attempting to parse and migrate should raise JSONDecodeError\\n        with sqlite_db.connect() as conn:\\n            result = conn.execute(text(\\\"SELECT auth_settings FROM folder WHERE id = :id\\\"), {\\\"id\\\": folder_id}).fetchone()\\n\\n            with pytest.raises(json.JSONDecodeError):\\n                json.loads(result[0])\\n\\n    def test_key_file_permissions_set_correctly(self, migrate_module):\\n        \\\"\\\"\\\"Test that key file has restrictive permissions on Unix systems.\\\"\\\"\\\"\\n        import platform\\n        import stat\\n\\n        if platform.system() not in {\\\"Linux\\\", \\\"Darwin\\\"}:\\n            pytest.skip(\\\"Permission test only runs on Unix systems\\\")\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            config_dir = Path(tmpdir)\\n            test_key = \\\"secure-key-12345\\\"\\n\\n            migrate_module.write_secret_key_to_file(config_dir, test_key)\\n\\n            secret_file = config_dir / \\\"secret_key\\\"\\n            file_mode = secret_file.stat().st_mode\\n            # Check that only owner has read/write (0o600)\\n            assert stat.S_IMODE(file_mode) == 0o600\\n\\n\\nclass TestDryRunMode:\\n    \\\"\\\"\\\"Tests for dry-run mode behavior.\\\"\\\"\\\"\\n\\n    def test_dry_run_does_not_modify_database(self, migrate_module, sqlite_db, old_key, new_key):\\n        \\\"\\\"\\\"Test that dry run mode doesn't modify the database.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        original_value = \\\"original-secret\\\"\\n        encrypted_value = migrate_module.encrypt_with_key(original_value, old_key)\\n\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text('INSERT INTO \\\"user\\\" (id, store_api_key) VALUES (:id, :key)'),\\n                {\\\"id\\\": user_id, \\\"key\\\": encrypted_value},\\n            )\\n            conn.commit()\\n\\n        # Simulate dry-run behavior: use begin() then rollback\\n        with sqlite_db.begin() as conn:\\n            # Migrate the value\\n            new_encrypted = migrate_module.migrate_value(encrypted_value, old_key, new_key)\\n            conn.execute(\\n                text('UPDATE \\\"user\\\" SET store_api_key = :val WHERE id = :id'),\\n                {\\\"val\\\": new_encrypted, \\\"id\\\": user_id},\\n            )\\n            # Explicitly rollback to simulate dry-run\\n            conn.rollback()\\n\\n        # Verify original value is preserved\\n        with sqlite_db.connect() as conn:\\n            result = conn.execute(text('SELECT store_api_key FROM \\\"user\\\" WHERE id = :id'), {\\\"id\\\": user_id}).fetchone()\\n            assert result[0] == encrypted_value\\n            # Can still decrypt with old key\\n            decrypted = migrate_module.decrypt_with_key(result[0], old_key)\\n            assert decrypted == original_value\\n\\n\\nclass TestVerifyMigration:\\n    \\\"\\\"\\\"Tests for post-migration verification.\\\"\\\"\\\"\\n\\n    def test_verify_migration_success(self, migrate_module, sqlite_db, new_key):\\n        \\\"\\\"\\\"Test verification passes when data is correctly migrated.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        var_id = str(uuid4())\\n        original_value = \\\"test-secret-value\\\"\\n\\n        # Create data encrypted with new key (simulating successful migration)\\n        encrypted_value = migrate_module.encrypt_with_key(original_value, new_key)\\n\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text('INSERT INTO \\\"user\\\" (id, store_api_key) VALUES (:id, :key)'),\\n                {\\\"id\\\": user_id, \\\"key\\\": encrypted_value},\\n            )\\n            conn.execute(\\n                text(\\\"INSERT INTO variable (id, name, value, type) VALUES (:id, :name, :value, :type)\\\"),\\n                {\\\"id\\\": var_id, \\\"name\\\": \\\"test_var\\\", \\\"value\\\": encrypted_value, \\\"type\\\": CREDENTIAL_TYPE},\\n            )\\n            conn.commit()\\n\\n        # Verify migration\\n        with sqlite_db.connect() as conn:\\n            verified, failed = migrate_module.verify_migration(conn, new_key)\\n            assert verified == 2  # 1 user + 1 variable\\n            assert failed == 0\\n\\n    def test_verify_migration_failure(self, migrate_module, sqlite_db, old_key, new_key):\\n        \\\"\\\"\\\"Test verification fails when data is encrypted with wrong key.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        original_value = \\\"test-secret-value\\\"\\n\\n        # Create data encrypted with old key (simulating failed migration)\\n        encrypted_value = migrate_module.encrypt_with_key(original_value, old_key)\\n\\n        with sqlite_db.connect() as conn:\\n            conn.execute(\\n                text('INSERT INTO \\\"user\\\" (id, store_api_key) VALUES (:id, :key)'),\\n                {\\\"id\\\": user_id, \\\"key\\\": encrypted_value},\\n            )\\n            conn.commit()\\n\\n        # Verify migration with new key should fail\\n        with sqlite_db.connect() as conn:\\n            verified, failed = migrate_module.verify_migration(conn, new_key)\\n            assert verified == 0\\n            assert failed == 1\\n\\n    def test_verify_migration_empty_tables(self, migrate_module, sqlite_db, new_key):\\n        \\\"\\\"\\\"Test verification handles empty tables gracefully.\\\"\\\"\\\"\\n        with sqlite_db.connect() as conn:\\n            verified, failed = migrate_module.verify_migration(conn, new_key)\\n            assert verified == 0\\n            assert failed == 0\\n\\n    def test_verify_migration_includes_sso_secrets(self, migrate_module, sqlite_db, new_key):\\n        config_id = str(uuid4())\\n        encrypted = migrate_module.encrypt_sso_secret_with_key(\\\"oidc-secret\\\", new_key)\\n        with sqlite_db.begin() as conn:\\n            conn.execute(\\n                text(\\\"INSERT INTO sso_config (id, client_secret_encrypted) VALUES (:id, :secret)\\\"),\\n                {\\\"id\\\": config_id, \\\"secret\\\": encrypted},\\n            )\\n\\n        with sqlite_db.connect() as conn:\\n            verified, failed = migrate_module.verify_migration(conn, new_key)\\n\\n        assert verified == 1\\n        assert failed == 0\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/serialization/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/serialization/test_serialization.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"effbb5d10d570561c24d5a6b8d83684cf85cd15c8790e672d942a74f5bf69a23\",\"content\":\"from __future__ import annotations\\n\\nimport math\\nfrom datetime import datetime, timezone\\nfrom typing import Any\\n\\nimport numpy as np\\nimport pandas as pd\\nfrom hypothesis import given, settings\\nfrom hypothesis import strategies as st\\nfrom langchain_core.documents import Document\\nfrom langflow.serialization.constants import MAX_ITEMS_LENGTH, MAX_TEXT_LENGTH\\nfrom langflow.serialization.serialization import serialize, serialize_or_str\\nfrom pydantic import BaseModel as PydanticBaseModel\\nfrom pydantic.v1 import BaseModel as PydanticV1BaseModel\\n\\n# Comprehensive hypothesis strategies\\ntext_strategy = st.text(min_size=0, max_size=MAX_TEXT_LENGTH * 3)\\nbytes_strategy = st.binary(min_size=0, max_size=MAX_TEXT_LENGTH * 3)\\ndatetime_strategy = st.datetimes(\\n    min_value=datetime.min,  # noqa: DTZ901 - Hypothesis requires naive datetime bounds\\n    max_value=datetime.max,  # noqa: DTZ901 - Hypothesis requires naive datetime bounds\\n    timezones=st.sampled_from([timezone.utc, None]),\\n)\\ndecimal_strategy = st.decimals(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False, places=10)\\nuuid_strategy = st.uuids()\\nlist_strategy = st.lists(st.one_of(st.integers(), st.text(), st.floats()), min_size=0, max_size=MAX_ITEMS_LENGTH * 3)\\ndict_strategy = st.dictionaries(\\n    keys=st.text(min_size=1),\\n    values=st.one_of(st.integers(), st.floats(), st.text(), st.booleans(), st.none()),\\n    min_size=0,\\n    max_size=MAX_ITEMS_LENGTH,\\n)\\n\\n# Complex nested structure strategy\\nnested_strategy = st.recursive(\\n    st.one_of(st.integers(), st.floats(), st.text(), st.booleans()),\\n    lambda children: st.lists(children) | st.dictionaries(st.text(), children),\\n    max_leaves=10,\\n)\\n\\n\\n# Pydantic models for testing\\nclass ModernModel(PydanticBaseModel):\\n    name: str\\n    value: int\\n\\n\\nclass LegacyModel(PydanticV1BaseModel):\\n    name: str\\n    value: int\\n\\n\\nclass TestSerializationHypothesis:\\n    \\\"\\\"\\\"Hypothesis-based property tests for serialization logic.\\\"\\\"\\\"\\n\\n    @settings(max_examples=100)\\n    @given(text=text_strategy)\\n    def test_string_serialization(self, text: str) -> None:\\n        result: str = serialize(text)\\n        if len(text) > MAX_TEXT_LENGTH:\\n            expected: str = text[:MAX_TEXT_LENGTH] + \\\"...\\\"\\n            assert result == expected\\n        else:\\n            assert result == text\\n\\n    @settings(max_examples=100)\\n    @given(data=bytes_strategy)\\n    def test_bytes_serialization(self, data: bytes) -> None:\\n        result: str = serialize(data)\\n        decoded: str = data.decode(\\\"utf-8\\\", errors=\\\"ignore\\\")\\n        if len(decoded) > MAX_TEXT_LENGTH:\\n            expected: str = decoded[:MAX_TEXT_LENGTH] + \\\"...\\\"\\n            assert result == expected\\n        else:\\n            assert result == decoded\\n\\n    @settings(max_examples=100)\\n    @given(dt=datetime_strategy)\\n    def test_datetime_serialization(self, dt: datetime) -> None:\\n        result: str = serialize(dt)\\n        assert result == dt.replace(tzinfo=timezone.utc).isoformat()\\n\\n    @settings(max_examples=100)\\n    @given(dec=decimal_strategy)\\n    def test_decimal_serialization(self, dec) -> None:\\n        result: float = serialize(dec)\\n        assert result == float(dec)\\n\\n    @settings(max_examples=100)\\n    @given(uid=uuid_strategy)\\n    def test_uuid_serialization(self, uid) -> None:\\n        result: str = serialize(uid)\\n        assert result == str(uid)\\n\\n    @settings(max_examples=100)\\n    @given(lst=list_strategy)\\n    def test_list_truncation(self, lst: list) -> None:\\n        result: list = serialize(lst, max_items=MAX_ITEMS_LENGTH)\\n        if len(lst) > MAX_ITEMS_LENGTH:\\n            assert len(result) == MAX_ITEMS_LENGTH + 1\\n            assert f\\\"... [truncated {len(lst) - MAX_ITEMS_LENGTH} items]\\\" in result\\n        else:\\n            # NaN/Inf floats are sanitized to None, so compare element-wise\\n            assert len(result) == len(lst)\\n            for r, v in zip(result, lst, strict=False):\\n                if isinstance(v, float) and (math.isnan(v) or math.isinf(v)):\\n                    assert r is None\\n                else:\\n                    assert r == v\\n\\n    @settings(max_examples=100)\\n    @given(dct=dict_strategy)\\n    def test_dict_serialization(self, dct: dict) -> None:\\n        result: dict = serialize(dct)\\n        assert isinstance(result, dict)\\n        for k, v in result.items():\\n            assert isinstance(k, str)\\n            assert isinstance(v, int | float | str | bool | type(None))\\n\\n    @settings(max_examples=100)\\n    @given(value=st.integers())\\n    def test_pydantic_modern_model(self, value: int) -> None:\\n        model: ModernModel = ModernModel(name=\\\"test\\\", value=value)\\n        result: dict = serialize(model)\\n        assert result == {\\\"name\\\": \\\"test\\\", \\\"value\\\": value}\\n\\n    @settings(max_examples=100)\\n    @given(value=st.integers())\\n    def test_pydantic_v1_model(self, value: int) -> None:\\n        model: LegacyModel = LegacyModel(name=\\\"test\\\", value=value)\\n        result: dict = serialize(model)\\n        assert result == {\\\"name\\\": \\\"test\\\", \\\"value\\\": value}\\n\\n    def test_async_iterator_handling(self) -> None:\\n        async def async_gen():\\n            yield 1\\n            yield 2\\n\\n        gen = async_gen()\\n        result: str = serialize(gen)\\n        assert result == \\\"Unconsumed Stream\\\"\\n\\n    @settings(max_examples=100)\\n    @given(data=st.one_of(st.integers(), st.floats(allow_nan=True), st.booleans(), st.none()))\\n    def test_primitive_types(self, data: float | bool | None) -> None:  # noqa: FBT001\\n        result: int | float | bool | None = serialize(data)\\n        if isinstance(data, float) and (math.isnan(data) or math.isinf(data)):\\n            assert result is None\\n        else:\\n            assert result == data\\n\\n    @settings(max_examples=100)\\n    @given(nested=nested_strategy)\\n    def test_nested_structures(self, nested: Any) -> None:\\n        result: list | dict | int | float | str | bool = serialize(nested)\\n        assert isinstance(result, list | dict | int | float | str | bool)\\n\\n    @settings(max_examples=100)\\n    @given(text=text_strategy)\\n    def test_max_length_none(self, text: str) -> None:\\n        result: str = serialize(text, max_length=None)\\n        assert result == text\\n\\n    @settings(max_examples=100)\\n    @given(lst=list_strategy)\\n    def test_max_items_none(self, lst: list) -> None:\\n        result: list = serialize(lst, max_items=None)\\n        # NaN/Inf floats are sanitized to None, so compare element-wise\\n        assert len(result) == len(lst)\\n        for r, v in zip(result, lst, strict=False):\\n            if isinstance(v, float) and (math.isnan(v) or math.isinf(v)):\\n                assert r is None\\n            else:\\n                assert r == v\\n\\n    @settings(max_examples=100)\\n    @given(obj=st.builds(object))\\n    def test_fallback_serialization(self, obj: object) -> None:\\n        result: str = serialize_or_str(obj)\\n        assert isinstance(result, str)\\n        assert str(obj) in result\\n\\n    def test_document_serialization(self) -> None:\\n        doc: Document = Document(page_content=\\\"test\\\", metadata={\\\"source\\\": \\\"test\\\"})\\n        result: dict = serialize(doc)\\n        assert isinstance(result, dict)\\n        assert \\\"kwargs\\\" in result\\n        assert \\\"page_content\\\" in result[\\\"kwargs\\\"]\\n        assert result[\\\"kwargs\\\"][\\\"page_content\\\"] == \\\"test\\\"\\n        assert \\\"metadata\\\" in result[\\\"kwargs\\\"]\\n        assert result[\\\"kwargs\\\"][\\\"metadata\\\"] == {\\\"source\\\": \\\"test\\\"}\\n\\n    def test_class_serialization(self) -> None:\\n        class TestClass:\\n            def __init__(self, value: Any) -> None:\\n                self.value = value\\n\\n        result: str = serialize(TestClass)\\n        assert result == str(TestClass)\\n\\n    def test_instance_serialization(self) -> None:\\n        class TestClass:\\n            def __init__(self, value: int) -> None:\\n                self.value = value\\n\\n        instance: TestClass = TestClass(42)\\n        result: str = serialize(instance)\\n        assert result == str(instance)\\n\\n    def test_recursive_string_serialization_returns_sentinel(self) -> None:\\n        class RecursiveString:\\n            def __str__(self) -> str:\\n                return str(self)\\n\\n        obj = RecursiveString()\\n\\n        assert serialize(obj) == \\\"[Unserializable Object]\\\"\\n        assert serialize_or_str(obj) == \\\"[Unserializable Object]\\\"\\n\\n    def test_pydantic_class_serialization(self) -> None:\\n        result: str = serialize(ModernModel)\\n        assert result == repr(ModernModel)\\n\\n    def test_builtin_type_serialization(self) -> None:\\n        result: str = serialize(int)\\n        assert result == repr(int)\\n\\n    def test_none_serialization(self) -> None:\\n        result: None = serialize(None)\\n        assert result is None\\n\\n    def test_custom_type_serialization(self) -> None:\\n        from typing import TypeVar\\n\\n        T = TypeVar(\\\"T\\\")\\n        result: str = serialize(T)\\n        assert result == repr(T)\\n\\n    def test_nested_class_serialization(self) -> None:\\n        class Outer:\\n            class Inner:\\n                pass\\n\\n        result: str = serialize(Outer.Inner)\\n        assert result == str(Outer.Inner)\\n\\n    def test_enum_serialization(self) -> None:\\n        from enum import Enum\\n\\n        class TestEnum(Enum):\\n            A = 1\\n            B = 2\\n\\n        result: str = serialize(TestEnum.A)\\n        assert result == \\\"TestEnum.A\\\"\\n\\n    def test_type_alias_serialization(self) -> None:\\n        IntList = list[int]  # noqa: N806\\n        result: str = serialize(IntList)\\n        assert result == repr(IntList)\\n\\n    def test_generic_type_serialization(self) -> None:\\n        from typing import Generic, TypeVar\\n\\n        T = TypeVar(\\\"T\\\")\\n\\n        class Box(Generic[T]):\\n            pass\\n\\n        result: str = serialize(Box[int])\\n        assert result == repr(Box[int])\\n\\n    def test_numpy_int64_serialization(self) -> None:\\n        \\\"\\\"\\\"Test serialization of numpy.int64 values.\\\"\\\"\\\"\\n        np_int = np.int64(42)\\n        result = serialize(np_int)\\n        assert result == 42\\n        assert isinstance(result, int)\\n\\n    def test_numpy_numeric_serialization(self) -> None:\\n        \\\"\\\"\\\"Test serialization of various numpy numeric types.\\\"\\\"\\\"\\n        # Test integers\\n        assert serialize(np.int64(42)) == 42\\n        assert isinstance(serialize(np.int64(42)), int)\\n\\n        # Test unsigned integers\\n        assert serialize(np.uint64(42)) == 42\\n        assert isinstance(serialize(np.uint64(42)), int)\\n\\n        # Test floats\\n        assert serialize(np.float64(math.pi)) == math.pi\\n        assert isinstance(serialize(np.float64(math.pi)), float)\\n\\n        # Test float32 (need to account for precision differences)\\n        float32_val = serialize(np.float32(math.pi))\\n        assert isinstance(float32_val, float)\\n        assert abs(float32_val - math.pi) < 1e-6  # Check if close enough\\n\\n        # Test bool\\n        assert serialize(np.bool_(True)) is True  # noqa: FBT003\\n        assert isinstance(serialize(np.bool_(True)), bool)  # noqa: FBT003\\n\\n        # Test complex numbers\\n        complex_val = serialize(np.complex64(1 + 2j))\\n        assert isinstance(complex_val, complex)\\n        assert abs(complex_val - (1 + 2j)) < 1e-6\\n\\n        # Test strings\\n        assert serialize(np.str_(\\\"hello\\\")) == \\\"hello\\\"\\n        assert isinstance(serialize(np.str_(\\\"hello\\\")), str)\\n\\n        # Test bytes\\n        bytes_val = np.bytes_(b\\\"world\\\")\\n        assert serialize(bytes_val) == \\\"world\\\"\\n        assert isinstance(serialize(bytes_val), str)\\n\\n        # Test unicode\\n        assert serialize(np.str_(\\\"unicode\\\")) == \\\"unicode\\\"\\n        assert isinstance(serialize(np.str_(\\\"unicode\\\")), str)\\n\\n        # Test object arrays\\n        obj_array = np.array([1, \\\"two\\\", 3.0], dtype=object)\\n        result = serialize(obj_array[0])\\n        assert result == 1\\n        assert isinstance(result, int)\\n\\n        result = serialize(obj_array[1])\\n        assert result == \\\"two\\\"\\n        assert isinstance(result, str)\\n\\n        result = serialize(obj_array[2])\\n        assert result == 3.0\\n        assert isinstance(result, float)\\n\\n    def test_pandas_serialization(self) -> None:\\n        \\\"\\\"\\\"Test serialization of pandas DataFrame.\\\"\\\"\\\"\\n        # Test DataFrame\\n        test_df = pd.DataFrame({\\\"A\\\": [1, 2, 3], \\\"B\\\": [\\\"a\\\", \\\"b\\\", \\\"c\\\"], \\\"C\\\": [1.1, 2.2, 3.3]})\\n        result = serialize(test_df)\\n        assert isinstance(result, list)  # DataFrame is serialized to list of records\\n        assert len(result) == 3\\n        assert all(isinstance(row, dict) for row in result)\\n        assert all(\\\"A\\\" in row and \\\"B\\\" in row and \\\"C\\\" in row for row in result)\\n        assert result[0] == {\\\"A\\\": 1, \\\"B\\\": \\\"a\\\", \\\"C\\\": 1.1}\\n\\n        # Test DataFrame truncation\\n        df_long = pd.DataFrame({\\\"A\\\": range(MAX_ITEMS_LENGTH + 100)})\\n        result = serialize(df_long, max_items=MAX_ITEMS_LENGTH)\\n        assert isinstance(result, list)\\n        assert len(result) == MAX_ITEMS_LENGTH\\n        assert all(\\\"A\\\" in row for row in result)\\n\\n    def test_series_serialization(self) -> None:\\n        \\\"\\\"\\\"Test serialization of pandas Series.\\\"\\\"\\\"\\n        # Test Series\\n        series = pd.Series([1, 2, 3], name=\\\"test\\\")\\n        result = serialize(series)\\n        assert isinstance(result, dict)\\n        assert len(result) == 3\\n        assert all(isinstance(v, int) for v in result.values())\\n\\n    def test_series_truncation(self) -> None:\\n        \\\"\\\"\\\"Test truncation of pandas Series.\\\"\\\"\\\"\\n        # Test Series\\n        series_long = pd.Series(range(MAX_ITEMS_LENGTH + 100), name=\\\"test_long\\\")\\n        result = serialize(series_long, max_items=MAX_ITEMS_LENGTH)\\n        assert isinstance(result, dict)\\n        assert len(result) == MAX_ITEMS_LENGTH\\n        assert all(isinstance(v, int) for v in result.values())\\n\\n    def test_nan_float_serialized_to_none(self) -> None:\\n        \\\"\\\"\\\"NaN floats must not pass through because they are not JSON-compliant.\\\"\\\"\\\"\\n        assert serialize(float(\\\"nan\\\")) is None\\n\\n    def test_inf_float_serialized_to_none(self) -> None:\\n        \\\"\\\"\\\"Inf floats must not pass through because they are not JSON-compliant.\\\"\\\"\\\"\\n        assert serialize(float(\\\"inf\\\")) is None\\n        assert serialize(float(\\\"-inf\\\")) is None\\n\\n    def test_nan_inside_dict_serialized_to_none(self) -> None:\\n        \\\"\\\"\\\"NaN values nested in dicts should also be sanitized.\\\"\\\"\\\"\\n        data = {\\\"score\\\": float(\\\"nan\\\"), \\\"name\\\": \\\"test\\\", \\\"value\\\": 1.5}\\n        result = serialize(data)\\n        assert result[\\\"score\\\"] is None\\n        assert result[\\\"name\\\"] == \\\"test\\\"\\n        assert result[\\\"value\\\"] == 1.5\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/auth/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/auth/test_auth_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7b4f95009d8b8427cd148e94a8459884f34161aef316a5361fc028dc05fb02fe\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport hashlib\\nfrom contextlib import asynccontextmanager\\nfrom datetime import datetime, timedelta, timezone\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, patch\\nfrom uuid import UUID, uuid4\\n\\nimport jwt\\nimport pytest\\nfrom cryptography.fernet import Fernet, InvalidToken\\nfrom fastapi import HTTPException, WebSocketException, status\\nfrom langflow.services.auth.constants import AUTO_LOGIN_ERROR, AUTO_LOGIN_WARNING\\nfrom langflow.services.auth.context import (\\n    AUTH_METHOD_API_KEY,\\n    AUTH_METHOD_AUTO_LOGIN,\\n    AUTH_METHOD_EXTERNAL,\\n    AUTH_METHOD_JWT,\\n    AuthCredentialContext,\\n    clear_current_auth_context,\\n    get_current_auth_context,\\n    set_current_auth_context,\\n)\\nfrom langflow.services.auth.exceptions import (\\n    InactiveUserError,\\n    InvalidCredentialsError,\\n    InvalidTokenError,\\n    MissingCredentialsError,\\n    TokenExpiredError,\\n)\\nfrom langflow.services.auth.service import AuthService\\nfrom langflow.services.database.models.api_key.crud import ApiKeyAuthResult, hash_api_key\\nfrom langflow.services.database.models.api_key.model import ApiKey\\nfrom langflow.services.database.models.user.model import User\\nfrom lfx.services.settings.auth import AuthSettings\\nfrom lfx.services.settings.constants import DEFAULT_SUPERUSER, LEGACY_DEFAULT_SUPERUSER_PASSWORD\\nfrom pydantic import SecretStr\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\nfrom sqlmodel import SQLModel\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\n@pytest.fixture\\ndef auth_settings(tmp_path) -> AuthSettings:\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path))\\n    settings.SECRET_KEY = SecretStr(\\\"MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=\\\")  # pragma: allowlist secret\\n    settings.AUTO_LOGIN = False\\n    settings.WEBHOOK_AUTH_ENABLE = False\\n    settings.ACCESS_TOKEN_EXPIRE_SECONDS = 60\\n    settings.REFRESH_TOKEN_EXPIRE_SECONDS = 120\\n    return settings\\n\\n\\n@pytest.fixture\\ndef auth_service(auth_settings, tmp_path) -> AuthService:\\n    settings_service = SimpleNamespace(\\n        auth_settings=auth_settings,\\n        settings=SimpleNamespace(config_dir=str(tmp_path)),\\n    )\\n    return AuthService(settings_service)\\n\\n\\ndef _dummy_user(user_id: UUID, *, active: bool = True) -> User:\\n    return User(\\n        id=user_id,\\n        username=\\\"tester\\\",\\n        password=\\\"hashed\\\",  # noqa: S106 - test fixture data  # pragma: allowlist secret\\n        is_active=active,\\n        is_superuser=False,\\n    )\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_user_from_access_token_returns_active_user(auth_service: AuthService):\\n    user_id = uuid4()\\n    db = AsyncMock()\\n    token = auth_service.create_token({\\\"sub\\\": str(user_id), \\\"type\\\": \\\"access\\\"}, timedelta(minutes=5))\\n    fake_user = _dummy_user(user_id)\\n\\n    with patch(\\\"langflow.services.auth.service.get_user_by_id\\\", new=AsyncMock(return_value=fake_user)) as mock_get_user:\\n        result = await auth_service.get_current_user_from_access_token(token, db)\\n\\n    assert result is fake_user\\n    mock_get_user.assert_awaited_once_with(db, str(user_id))\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_user_from_access_token_rejects_expired(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    expired = datetime.now(timezone.utc) - timedelta(minutes=1)\\n    token = jwt.encode(\\n        {\\\"sub\\\": str(uuid4()), \\\"type\\\": \\\"access\\\", \\\"exp\\\": int(expired.timestamp())},\\n        auth_settings.SECRET_KEY.get_secret_value(),\\n        algorithm=auth_settings.ALGORITHM,\\n    )\\n\\n    with pytest.raises(TokenExpiredError):\\n        await auth_service.get_current_user_from_access_token(token, AsyncMock())\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_user_from_access_token_rejects_malformed_token(auth_service: AuthService):\\n    \\\"\\\"\\\"CT-010: Malformed Bearer token must raise InvalidTokenError; jwt.decode rejects invalid tokens.\\\"\\\"\\\"\\n    db = AsyncMock()\\n    malformed_tokens = [\\n        \\\"invalid.token.here\\\",  # invalid signature / not a valid JWT\\n        \\\"not-a-jwt\\\",  # not 3 segments, jwt.decode raises\\n    ]\\n    for token in malformed_tokens:\\n        with pytest.raises(InvalidTokenError):\\n            await auth_service.get_current_user_from_access_token(token, db)\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_user_from_access_token_requires_active_user(auth_service: AuthService):\\n    user_id = uuid4()\\n    db = AsyncMock()\\n    token = auth_service.create_token({\\\"sub\\\": str(user_id), \\\"type\\\": \\\"access\\\"}, timedelta(minutes=5))\\n    inactive_user = _dummy_user(user_id, active=False)\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.get_user_by_id\\\", new=AsyncMock(return_value=inactive_user)),\\n        pytest.raises(InactiveUserError),\\n    ):\\n        await auth_service.get_current_user_from_access_token(token, db)\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_with_credentials_missing_creds_raises(\\n    auth_service: AuthService,\\n):\\n    \\\"\\\"\\\"Default config (AUTO_LOGIN off, skip_auth_auto_login off) rejects callers with no creds.\\\"\\\"\\\"\\n    with pytest.raises(MissingCredentialsError):\\n        await auth_service.authenticate_with_credentials(token=None, api_key=None, db=AsyncMock())\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_with_api_key_sets_auth_context(auth_service: AuthService):\\n    user = _dummy_user(uuid4())\\n    api_key_id = uuid4()\\n\\n    with patch(\\n        \\\"langflow.services.auth.service.authenticate_api_key\\\",\\n        new=AsyncMock(\\n            return_value=ApiKeyAuthResult(\\n                user=user,\\n                api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n                api_key_id=api_key_id,\\n            )\\n        ),\\n    ):\\n        try:\\n            result = await auth_service.authenticate_with_credentials(\\n                token=None,\\n                api_key=\\\"sk-test-key\\\",  # pragma: allowlist secret\\n                db=AsyncMock(),\\n            )\\n            context = get_current_auth_context()\\n        finally:\\n            clear_current_auth_context()\\n\\n    assert result.id == user.id\\n    assert context is not None\\n    assert context.method == AUTH_METHOD_API_KEY\\n    assert context.api_key_id == api_key_id\\n    assert context.api_key_source == \\\"db\\\"  # pragma: allowlist secret\\n\\n\\n@pytest.mark.anyio\\nasync def test_inactive_user_api_key_rejection_does_not_persist_usage(\\n    auth_service: AuthService,\\n    tmp_path,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"A rejected inactive-user credential must not record a successful API-key use.\\\"\\\"\\\"\\n    plaintext = \\\"sk-inactive-user\\\"  # pragma: allowlist secret\\n    engine = create_async_engine(f\\\"sqlite+aiosqlite:///{tmp_path / 'inactive-user-api-key.db'}\\\")\\n    try:\\n        async with engine.begin() as connection:\\n            await connection.run_sync(\\n                lambda sync_connection: SQLModel.metadata.create_all(\\n                    sync_connection,\\n                    tables=[User.__table__, ApiKey.__table__],\\n                )\\n            )\\n\\n        inactive_user = _dummy_user(uuid4(), active=False)\\n        inactive_user.username = \\\"inactive-api-key-user\\\"\\n        api_key = ApiKey(\\n            api_key=\\\"encrypted-inactive-user\\\",  # pragma: allowlist secret\\n            api_key_hash=hash_api_key(plaintext),\\n            name=\\\"inactive-user\\\",\\n            user_id=inactive_user.id,\\n            created_at=datetime.now(timezone.utc),\\n        )\\n        async with AsyncSession(engine, expire_on_commit=False) as seed_session:\\n            seed_session.add(inactive_user)\\n            seed_session.add(api_key)\\n            await seed_session.commit()\\n            api_key_id = api_key.id\\n\\n        auth_service.settings.settings.disable_track_apikey_usage = False\\n        monkeypatch.setattr(\\n            \\\"langflow.services.database.models.api_key.crud.get_settings_service\\\",\\n            lambda: auth_service.settings,\\n        )\\n\\n        @asynccontextmanager\\n        async def owned_auth_scope():\\n            async with AsyncSession(engine, expire_on_commit=False) as auth_session:\\n                try:\\n                    yield auth_session\\n                    await auth_session.commit()\\n                except Exception:\\n                    await auth_session.rollback()\\n                    raise\\n\\n        monkeypatch.setattr(\\n            \\\"langflow.services.database.models.api_key.crud.session_scope\\\",\\n            owned_auth_scope,\\n        )\\n        async with AsyncSession(engine, expire_on_commit=False) as caller_session:\\n            with pytest.raises(InvalidCredentialsError):\\n                await auth_service.authenticate_with_credentials(\\n                    token=None,\\n                    api_key=plaintext,\\n                    db=caller_session,\\n                )\\n            await caller_session.rollback()\\n\\n        async with AsyncSession(engine, expire_on_commit=False) as verification_session:\\n            persisted_api_key = await verification_session.get(ApiKey, api_key_id)\\n    finally:\\n        await engine.dispose()\\n\\n    assert persisted_api_key is not None\\n    assert persisted_api_key.total_uses == 0\\n    assert persisted_api_key.last_used_at is None\\n\\n\\n@pytest.mark.anyio\\n@pytest.mark.parametrize(\\\"token\\\", [None, \\\"native-token\\\"], ids=[\\\"external-only\\\", \\\"native-and-external\\\"])\\nasync def test_api_key_fallback_rolls_back_failed_token_and_external_state(\\n    auth_service: AuthService,\\n    async_session,\\n    monkeypatch,\\n    token,\\n):\\n    \\\"\\\"\\\"API-key fallback discards state flushed by every earlier credential attempt.\\\"\\\"\\\"\\n    from sqlmodel import select\\n\\n    api_user = _dummy_user(uuid4())\\n    api_user.username = \\\"api-key-user\\\"\\n    plaintext = \\\"sk-valid-fallback-key\\\"  # pragma: allowlist secret\\n    api_key = ApiKey(\\n        api_key=\\\"encrypted-value\\\",  # pragma: allowlist secret\\n        api_key_hash=hash_api_key(plaintext),\\n        name=\\\"fallback\\\",\\n        user_id=api_user.id,\\n        created_at=datetime.now(timezone.utc),\\n    )\\n    async_session.add(api_user)\\n    async_session.add(api_key)\\n    await async_session.commit()\\n    api_user_id = api_user.id\\n\\n    auth_service.settings.settings.disable_track_apikey_usage = False\\n    monkeypatch.setattr(\\n        \\\"langflow.services.database.models.api_key.crud.get_settings_service\\\",\\n        lambda: auth_service.settings,\\n    )\\n\\n    @asynccontextmanager\\n    async def owned_auth_scope():\\n        async with AsyncSession(bind=async_session.bind, expire_on_commit=False) as auth_session:\\n            try:\\n                yield auth_session\\n                await auth_session.commit()\\n            except Exception:\\n                await auth_session.rollback()\\n                raise\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.services.database.models.api_key.crud.session_scope\\\",\\n        owned_auth_scope,\\n    )\\n\\n    failed_token_user = _dummy_user(uuid4())\\n    failed_token_user.username = \\\"failed-token-user\\\"\\n    failed_external_user = _dummy_user(uuid4())\\n    failed_external_user.username = \\\"failed-external-user\\\"\\n\\n    async def stage_user_then_fail(_token: str, db) -> None:\\n        db.add(failed_token_user)\\n        await db.flush()\\n        msg = \\\"external reconciliation failed\\\"\\n        raise RuntimeError(msg)\\n\\n    async def stage_user_then_decline(_token: str, db) -> None:\\n        db.add(failed_external_user)\\n        await db.flush()\\n\\n    with (\\n        patch.object(auth_service, \\\"_authenticate_with_token\\\", new=stage_user_then_fail),\\n        patch.object(auth_service, \\\"_authenticate_with_external_token\\\", new=stage_user_then_decline),\\n    ):\\n        result = await auth_service.authenticate_with_credentials(\\n            token=token,\\n            api_key=plaintext,\\n            db=async_session,\\n            external_token=\\\"external-token\\\",  # noqa: S106\\n        )\\n\\n    persisted_failed_token_user = (\\n        await async_session.exec(select(User).where(User.id == failed_token_user.id))\\n    ).first()\\n    persisted_failed_external_user = (\\n        await async_session.exec(select(User).where(User.id == failed_external_user.id))\\n    ).first()\\n    await async_session.refresh(api_key)\\n\\n    assert result.id == api_user_id\\n    assert persisted_failed_token_user is None\\n    assert persisted_failed_external_user is None\\n    assert api_key.total_uses == 1\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_with_credentials_auto_login_alone_still_rejects(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"AUTO_LOGIN without skip_auth_auto_login must still require credentials.\\n\\n    Without this guard the AUTO_LOGIN security-tightening from #8513 would\\n    silently regress for every ``get_current_user``-protected endpoint.\\n    \\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = False\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n\\n    with pytest.raises(MissingCredentialsError):\\n        await auth_service.authenticate_with_credentials(token=None, api_key=None, db=AsyncMock())\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_with_credentials_auto_login_skip_returns_superuser(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"With AUTO_LOGIN + skip_auth_auto_login, missing creds fall back to the superuser.\\n\\n    Restores parity with ``api_key_security`` so ``CurrentActiveUser``-protected\\n    endpoints (e.g. ``GET /api/v1/flows/``) work for ADK/dev environments that\\n    relied on the v1.7.1 behavior.\\n    \\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = True\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n    superuser = _dummy_user(uuid4())\\n\\n    with (\\n        patch(\\n            \\\"langflow.services.auth.service.get_user_by_username\\\",\\n            new=AsyncMock(return_value=superuser),\\n        ) as mock_lookup,\\n        patch(\\\"langflow.services.auth.service.logger\\\") as mock_logger,\\n    ):\\n        result = await auth_service.authenticate_with_credentials(token=None, api_key=None, db=AsyncMock())\\n\\n    assert result is superuser\\n    mock_lookup.assert_awaited_once()\\n    mock_logger.warning.assert_called_once_with(AUTO_LOGIN_WARNING)\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_with_credentials_auto_login_skip_missing_superuser_raises(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"AUTO_LOGIN + skip_auth_auto_login with no superuser row in the DB rejects.\\n\\n    Mirrors the safety check inside ``_api_key_security_impl`` when the\\n    configured superuser is absent from the database.\\n    \\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = True\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n\\n    from langflow.services.auth.exceptions import InvalidCredentialsError\\n\\n    with (\\n        patch(\\n            \\\"langflow.services.auth.service.get_user_by_username\\\",\\n            new=AsyncMock(return_value=None),\\n        ),\\n        pytest.raises(InvalidCredentialsError),\\n    ):\\n        await auth_service.authenticate_with_credentials(token=None, api_key=None, db=AsyncMock())\\n\\n\\n@pytest.mark.anyio\\nasync def test_auto_login_longterm_token_is_short_lived_with_refresh(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"auto_login must not mint a 365-day superuser token.\\n\\n    Regression for GHSA-fjgc-vj2f-77hm: create_user_longterm_token\\n    previously issued a 365-day access token with no refresh token. It must now\\n    issue a normally-scoped access token (ACCESS_TOKEN_EXPIRE_SECONDS) plus a\\n    refresh token.\\n    \\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n    superuser = _dummy_user(uuid4())\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.get_user_by_username\\\", new=AsyncMock(return_value=superuser)),\\n        patch(\\\"langflow.services.auth.service.update_user_last_login_at\\\", new=AsyncMock()),\\n    ):\\n        user_id, tokens = await auth_service.create_user_longterm_token(AsyncMock())\\n\\n    assert user_id == superuser.id\\n    # A refresh token is now issued (previously None).\\n    assert tokens[\\\"refresh_token\\\"]\\n\\n    # The access token lifetime is bounded by ACCESS_TOKEN_EXPIRE_SECONDS (60 in\\n    # the fixture), nowhere near a year.\\n    claims = jwt.decode(tokens[\\\"access_token\\\"], options={\\\"verify_signature\\\": False})\\n    lifetime = claims[\\\"exp\\\"] - int(datetime.now(timezone.utc).timestamp())\\n    assert lifetime > 0\\n    assert lifetime <= auth_settings.ACCESS_TOKEN_EXPIRE_SECONDS + 5\\n    assert lifetime < 60 * 60 * 24  # far below a day, definitely not 365 days\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_with_credentials_auto_login_skip_empty_superuser_config_raises():\\n    \\\"\\\"\\\"AUTO_LOGIN + skip_auth_auto_login with an empty SUPERUSER config rejects without a DB lookup.\\n\\n    The ``if not auth_settings.SUPERUSER:`` guard at the top of the bypass branch\\n    must fire before ``get_user_by_username`` is called. Uses SimpleNamespace to\\n    bypass Pydantic model validation so SUPERUSER can be set to an empty string.\\n    \\\"\\\"\\\"\\n    from langflow.services.auth.exceptions import InvalidCredentialsError\\n\\n    settings_service = SimpleNamespace(\\n        auth_settings=SimpleNamespace(\\n            AUTO_LOGIN=True,\\n            skip_auth_auto_login=True,\\n            SUPERUSER=\\\"\\\",\\n        )\\n    )\\n    service = AuthService(settings_service)\\n\\n    with pytest.raises(InvalidCredentialsError):\\n        await service.authenticate_with_credentials(token=None, api_key=None, db=AsyncMock())\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_with_credentials_auto_login_skip_rejects_inactive_superuser(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"AUTO_LOGIN fallback must enforce ``is_active`` like token/API-key paths.\\n\\n    ``CurrentActiveUser`` re-checks this for HTTP routes, but SSE/websocket\\n    dependencies delegate directly to ``authenticate_with_credentials``, so\\n    the active-user guard must live in this method.\\n    \\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = True\\n    inactive_superuser = _dummy_user(uuid4(), active=False)\\n\\n    with (\\n        patch(\\n            \\\"langflow.services.auth.service.get_user_by_username\\\",\\n            new=AsyncMock(return_value=inactive_superuser),\\n        ),\\n        pytest.raises(InactiveUserError),\\n    ):\\n        await auth_service.authenticate_with_credentials(token=None, api_key=None, db=AsyncMock())\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_user_rejects_legacy_default_password_in_auto_login(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.SUPERUSER = DEFAULT_SUPERUSER\\n    legacy_password = LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value()\\n    default_superuser = User(\\n        id=uuid4(),\\n        username=DEFAULT_SUPERUSER,\\n        password=auth_service.get_password_hash(legacy_password),\\n        is_active=True,\\n        is_superuser=True,\\n    )\\n\\n    with patch(\\\"langflow.services.auth.service.get_user_by_username\\\", new=AsyncMock(return_value=default_superuser)):\\n        result = await auth_service.authenticate_user(DEFAULT_SUPERUSER, legacy_password, AsyncMock())\\n\\n    assert result is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_user_rejects_legacy_default_password_when_auto_login_false(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    auth_settings.AUTO_LOGIN = False\\n    auth_settings.SUPERUSER = DEFAULT_SUPERUSER\\n    legacy_password = LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value()\\n    default_superuser = User(\\n        id=uuid4(),\\n        username=DEFAULT_SUPERUSER,\\n        password=auth_service.get_password_hash(legacy_password),\\n        is_active=True,\\n        is_superuser=True,\\n    )\\n\\n    with patch(\\\"langflow.services.auth.service.get_user_by_username\\\", new=AsyncMock(return_value=default_superuser)):\\n        result = await auth_service.authenticate_user(DEFAULT_SUPERUSER, legacy_password, AsyncMock())\\n\\n    assert result is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_user_rejects_legacy_default_username_after_superuser_override(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.SUPERUSER = \\\"custom_admin\\\"\\n    legacy_password = LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value()\\n    default_superuser = User(\\n        id=uuid4(),\\n        username=DEFAULT_SUPERUSER,\\n        password=auth_service.get_password_hash(legacy_password),\\n        is_active=True,\\n        is_superuser=True,\\n    )\\n\\n    with patch(\\\"langflow.services.auth.service.get_user_by_username\\\", new=AsyncMock(return_value=default_superuser)):\\n        result = await auth_service.authenticate_user(DEFAULT_SUPERUSER, legacy_password, AsyncMock())\\n\\n    assert result is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_create_refresh_token_requires_refresh_type(auth_service: AuthService):\\n    invalid_refresh = auth_service.create_token({\\\"sub\\\": str(uuid4()), \\\"type\\\": \\\"access\\\"}, timedelta(minutes=1))\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await auth_service.create_refresh_token(invalid_refresh, AsyncMock())\\n\\n    assert exc.value.status_code == status.HTTP_401_UNAUTHORIZED\\n\\n\\ndef test_encrypt_and_decrypt_api_key_roundtrip(auth_service: AuthService):\\n    api_key = \\\"super-secret-api-key\\\"  # pragma: allowlist secret\\n\\n    encrypted = auth_service.encrypt_api_key(api_key)\\n    assert encrypted != api_key\\n\\n    decrypted = auth_service.decrypt_api_key(encrypted)\\n    assert decrypted == api_key\\n\\n\\ndef test_add_padding_no_extra_chars_when_divisible_by_4():\\n    \\\"\\\"\\\"add_base64_padding must not add characters when length is already a multiple of 4.\\\"\\\"\\\"\\n    from langflow.services.auth.utils import add_base64_padding\\n\\n    assert add_base64_padding(\\\"ABCD\\\") == \\\"ABCD\\\"\\n    assert add_base64_padding(\\\"ABCDEFGH\\\") == \\\"ABCDEFGH\\\"\\n    assert add_base64_padding(\\\"A\\\" * 44) == \\\"A\\\" * 44\\n\\n\\ndef test_add_padding_pads_correctly():\\n    \\\"\\\"\\\"add_base64_padding must add the right number of = characters.\\\"\\\"\\\"\\n    from langflow.services.auth.utils import add_base64_padding\\n\\n    assert add_base64_padding(\\\"ABC\\\") == \\\"ABC=\\\"\\n    assert add_base64_padding(\\\"AB\\\") == \\\"AB==\\\"\\n    assert add_base64_padding(\\\"A\\\") == \\\"A===\\\"\\n\\n\\ndef test_encrypt_decrypt_roundtrip_with_standard_key(tmp_path):\\n    \\\"\\\"\\\"secrets.token_urlsafe(32) produces a 43-char key that must always work.\\\"\\\"\\\"\\n    import secrets\\n\\n    raw_key = secrets.token_urlsafe(32)  # always 43 chars\\n    assert len(raw_key) == 43\\n\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path))\\n    settings.SECRET_KEY = SecretStr(raw_key)\\n    settings_service = SimpleNamespace(\\n        auth_settings=settings,\\n        settings=SimpleNamespace(config_dir=str(tmp_path)),\\n    )\\n    svc = AuthService(settings_service)\\n\\n    encrypted = svc.encrypt_api_key(\\\"sk-test-key-12345\\\")  # pragma: allowlist secret\\n    assert svc.decrypt_api_key(encrypted) == \\\"sk-test-key-12345\\\"  # pragma: allowlist secret\\n\\n\\ndef test_encrypt_decrypt_roundtrip_with_base64_encoded_32_byte_key(tmp_path):\\n    \\\"\\\"\\\"A base64url-encoded 32-byte key (44 chars) must work after padding fix.\\\"\\\"\\\"\\n    import base64\\n    import os\\n\\n    raw_key = base64.urlsafe_b64encode(os.urandom(32)).decode()  # 44 chars with padding\\n    assert len(raw_key) == 44\\n\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path))\\n    settings.SECRET_KEY = SecretStr(raw_key)\\n    settings_service = SimpleNamespace(\\n        auth_settings=settings,\\n        settings=SimpleNamespace(config_dir=str(tmp_path)),\\n    )\\n    svc = AuthService(settings_service)\\n\\n    encrypted = svc.encrypt_api_key(\\\"sk-test-key-12345\\\")  # pragma: allowlist secret\\n    assert svc.decrypt_api_key(encrypted) == \\\"sk-test-key-12345\\\"  # pragma: allowlist secret\\n\\n\\ndef test_encrypt_decrypt_roundtrip_with_short_key(tmp_path):\\n    \\\"\\\"\\\"Keys shorter than 32 chars use the SHA-256 derivation and must work.\\\"\\\"\\\"\\n    raw_key = \\\"short-key\\\"\\n\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path))\\n    settings.SECRET_KEY = SecretStr(raw_key)\\n    settings_service = SimpleNamespace(\\n        auth_settings=settings,\\n        settings=SimpleNamespace(config_dir=str(tmp_path)),\\n    )\\n    svc = AuthService(settings_service)\\n\\n    encrypted = svc.encrypt_api_key(\\\"sk-test-key-12345\\\")  # pragma: allowlist secret\\n    assert svc.decrypt_api_key(encrypted) == \\\"sk-test-key-12345\\\"  # pragma: allowlist secret\\n\\n\\ndef test_short_key_decrypts_legacy_ciphertext_without_using_legacy_key_for_new_writes(tmp_path):\\n    \\\"\\\"\\\"Short-key upgrades retain read compatibility without regressing new encryption.\\n\\n    Before 1.10.1, ``shortkey123`` produced the fixed Fernet key below via\\n    ``random.seed(secret)`` and 32 calls to ``random.getrandbits(8)``. The\\n    current SHA-256 key must decrypt that legacy ciphertext as a fallback, but\\n    encryption must continue to use the SHA-256-derived primary key.\\n    \\\"\\\"\\\"\\n    from langflow.services.auth.utils import ensure_fernet_key\\n\\n    raw_key = \\\"shortkey123\\\"  # pragma: allowlist secret\\n    legacy_key = b\\\"qeA9wdDv6i0_4s4YpmYkg7mByqBIVqF5L8On7wINNmo=\\\"  # pragma: allowlist secret\\n    plaintext = \\\"credential-written-before-1.10.1\\\"  # pragma: allowlist secret\\n\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path))\\n    settings.SECRET_KEY = SecretStr(raw_key)\\n    settings_service = SimpleNamespace(\\n        auth_settings=settings,\\n        settings=SimpleNamespace(config_dir=str(tmp_path)),\\n    )\\n    svc = AuthService(settings_service)\\n\\n    legacy_ciphertext = Fernet(legacy_key).encrypt(plaintext.encode()).decode()\\n    assert svc.decrypt_api_key(legacy_ciphertext) == plaintext\\n\\n    with patch(\\\"langflow.services.auth.utils._ensure_legacy_fernet_key\\\") as mock_legacy_derivation:\\n        current_ciphertext = svc.encrypt_api_key(plaintext)\\n\\n    mock_legacy_derivation.assert_not_called()\\n    assert Fernet(ensure_fernet_key(raw_key)).decrypt(current_ciphertext.encode()).decode() == plaintext\\n    with pytest.raises(InvalidToken):\\n        Fernet(legacy_key).decrypt(current_ciphertext.encode())\\n\\n\\ndef test_decrypt_api_key_returns_empty_on_undecryptable_token(auth_service: AuthService):\\n    \\\"\\\"\\\"Decryption of an invalid Fernet token must return empty string, not raise.\\\"\\\"\\\"\\n    bad_token = \\\"gAAAAABinvalidtokendata\\\"  # noqa: S105  # pragma: allowlist secret\\n    result = auth_service.decrypt_api_key(bad_token)\\n    assert result == \\\"\\\"\\n\\n\\ndef test_decrypt_api_key_returns_plaintext_as_is(auth_service: AuthService):\\n    \\\"\\\"\\\"Plaintext keys (not starting with gAAAAA) must be returned as-is.\\\"\\\"\\\"\\n    plaintext = \\\"sk-some-plaintext-key\\\"  # pragma: allowlist secret\\n    assert auth_service.decrypt_api_key(plaintext) == plaintext\\n\\n\\ndef test_decrypt_api_key_returns_empty_for_invalid_input(auth_service: AuthService):\\n    \\\"\\\"\\\"Empty or non-string input must return empty string.\\\"\\\"\\\"\\n    assert auth_service.decrypt_api_key(\\\"\\\") == \\\"\\\"\\n\\n\\ndef test_ensure_fernet_key_with_44_char_key():\\n    \\\"\\\"\\\"ensure_fernet_key must handle 44-char keys (len % 4 == 0) correctly.\\\"\\\"\\\"\\n    import base64\\n    import os\\n\\n    from cryptography.fernet import Fernet\\n    from langflow.services.auth.utils import ensure_fernet_key\\n\\n    raw_key = base64.urlsafe_b64encode(os.urandom(32)).decode()  # 44 chars, len % 4 == 0\\n    assert len(raw_key) == 44\\n\\n    fernet = Fernet(ensure_fernet_key(raw_key))\\n    encrypted = fernet.encrypt(b\\\"test-value\\\")\\n    assert fernet.decrypt(encrypted) == b\\\"test-value\\\"\\n\\n\\ndef test_ensure_fernet_key_short_key_uses_sha256_derivation():\\n    \\\"\\\"\\\"Short-key derivation must be the SHA-256 hash, not the old PRNG output.\\n\\n    Regression for GHSA-jxw3-mjmx-3pqm: the key was previously derived with\\n    ``random.seed(secret_key)`` + ``random.getrandbits`` \u2014 a predictable,\\n    non-cryptographic PRNG. The guard that catches that regression is the\\n    SHA-256 equality below: the derived key must equal\\n    ``base64.urlsafe_b64encode(sha256(secret))``, which the old PRNG path could\\n    never produce.\\n\\n    The random-state perturbation between the two calls is only a determinism\\n    sanity check. On its own it would *not* catch the old bug \u2014 the vulnerable\\n    code re-seeded with the secret on every call, so it was deterministic per\\n    secret too; the SHA-256 assertion is what proves the path actually changed.\\n    \\\"\\\"\\\"\\n    import base64\\n    import hashlib\\n    import random\\n\\n    from langflow.services.auth.utils import ensure_fernet_key\\n\\n    raw_key = \\\"short-key\\\"  # < 32 chars -> derivation branch\\n\\n    random.seed(0)\\n    key_a = ensure_fernet_key(raw_key)\\n    random.seed(123456789)\\n    _ = [random.random() for _ in range(100)]  # noqa: S311  # perturb global PRNG state\\n    key_b = ensure_fernet_key(raw_key)\\n\\n    # Determinism sanity check (held under the old impl too \u2014 not the regression guard).\\n    assert key_a == key_b\\n    # Regression guard: the key must be the SHA-256 derivation, not random.getrandbits output.\\n    expected = base64.urlsafe_b64encode(hashlib.sha256(raw_key.encode()).digest())\\n    assert key_a == expected\\n\\n\\ndef test_password_helpers_roundtrip(auth_service: AuthService):\\n    password = \\\"Str0ngP@ssword\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n    hashed = auth_service.get_password_hash(password)\\n    assert hashed != password\\n    assert auth_service.verify_password(password, hashed)\\n\\n\\n# =============================================================================\\n# Token Creation Tests\\n# =============================================================================\\n\\n\\ndef test_create_token_contains_expected_claims(auth_service: AuthService):\\n    \\\"\\\"\\\"Test that created tokens contain the expected claims.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    token = auth_service.create_token(\\n        {\\\"sub\\\": str(user_id), \\\"type\\\": \\\"access\\\", \\\"custom\\\": \\\"value\\\"},\\n        timedelta(minutes=5),\\n    )\\n\\n    # Decode without verification to check claims\\n    claims = jwt.decode(token, options={\\\"verify_signature\\\": False})\\n    assert claims[\\\"sub\\\"] == str(user_id)\\n    assert claims[\\\"type\\\"] == \\\"access\\\"\\n    assert claims[\\\"custom\\\"] == \\\"value\\\"\\n    assert \\\"exp\\\" in claims\\n\\n\\ndef test_get_user_id_from_token_valid(auth_service: AuthService):\\n    \\\"\\\"\\\"Test extracting user ID from a valid token.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    token = auth_service.create_token({\\\"sub\\\": str(user_id), \\\"type\\\": \\\"access\\\"}, timedelta(minutes=5))\\n\\n    result = auth_service.get_user_id_from_token(token)\\n    assert result == user_id\\n\\n\\ndef test_get_user_id_from_token_invalid_returns_zero_uuid(auth_service: AuthService):\\n    \\\"\\\"\\\"Test that invalid token returns zero UUID.\\\"\\\"\\\"\\n    result = auth_service.get_user_id_from_token(\\\"invalid-token\\\")\\n    assert result == UUID(int=0)\\n\\n\\ndef test_create_user_api_key(auth_service: AuthService):\\n    \\\"\\\"\\\"Test API key creation for a user.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    result = auth_service.create_user_api_key(user_id)\\n\\n    assert \\\"api_key\\\" in result\\n    # Verify the token contains expected claims\\n    claims = jwt.decode(result[\\\"api_key\\\"], options={\\\"verify_signature\\\": False})\\n    assert claims[\\\"sub\\\"] == str(user_id)\\n    assert claims[\\\"type\\\"] == \\\"api_key\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_create_user_tokens(auth_service: AuthService):\\n    \\\"\\\"\\\"Test creating access and refresh tokens.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    db = AsyncMock()\\n\\n    result = await auth_service.create_user_tokens(user_id, db, update_last_login=False)\\n\\n    assert \\\"access_token\\\" in result\\n    assert \\\"refresh_token\\\" in result\\n    assert result[\\\"token_type\\\"] == \\\"bearer\\\"  # noqa: S105 - not a password\\n\\n    # Verify access token claims\\n    access_claims = jwt.decode(result[\\\"access_token\\\"], options={\\\"verify_signature\\\": False})\\n    assert access_claims[\\\"sub\\\"] == str(user_id)\\n    assert access_claims[\\\"type\\\"] == \\\"access\\\"\\n\\n    # Verify refresh token claims\\n    refresh_claims = jwt.decode(result[\\\"refresh_token\\\"], options={\\\"verify_signature\\\": False})\\n    assert refresh_claims[\\\"sub\\\"] == str(user_id)\\n    assert refresh_claims[\\\"type\\\"] == \\\"refresh\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_create_user_tokens_updates_last_login(auth_service: AuthService):\\n    \\\"\\\"\\\"Test that create_user_tokens updates last login when requested.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    db = AsyncMock()\\n\\n    with patch(\\\"langflow.services.auth.service.update_user_last_login_at\\\", new=AsyncMock()) as mock_update:\\n        await auth_service.create_user_tokens(user_id, db, update_last_login=True)\\n        mock_update.assert_awaited_once_with(user_id, db)\\n\\n\\n@pytest.mark.anyio\\nasync def test_create_refresh_token_valid(auth_service: AuthService):\\n    \\\"\\\"\\\"Test creating new tokens from a valid refresh token.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    db = AsyncMock()\\n    refresh_token = auth_service.create_token({\\\"sub\\\": str(user_id), \\\"type\\\": \\\"refresh\\\"}, timedelta(minutes=5))\\n    fake_user = _dummy_user(user_id)\\n\\n    with patch(\\\"langflow.services.auth.service.get_user_by_id\\\", new=AsyncMock(return_value=fake_user)):\\n        result = await auth_service.create_refresh_token(refresh_token, db)\\n\\n    assert \\\"access_token\\\" in result\\n    assert \\\"refresh_token\\\" in result\\n\\n\\n@pytest.mark.anyio\\nasync def test_create_refresh_token_user_not_found(auth_service: AuthService):\\n    \\\"\\\"\\\"Test refresh token fails when user doesn't exist.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    db = AsyncMock()\\n    refresh_token = auth_service.create_token({\\\"sub\\\": str(user_id), \\\"type\\\": \\\"refresh\\\"}, timedelta(minutes=5))\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.get_user_by_id\\\", new=AsyncMock(return_value=None)),\\n        pytest.raises(HTTPException) as exc,\\n    ):\\n        await auth_service.create_refresh_token(refresh_token, db)\\n\\n    assert exc.value.status_code == status.HTTP_401_UNAUTHORIZED\\n\\n\\n@pytest.mark.anyio\\nasync def test_create_refresh_token_inactive_user(auth_service: AuthService):\\n    \\\"\\\"\\\"Test refresh token fails for inactive user.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    db = AsyncMock()\\n    refresh_token = auth_service.create_token({\\\"sub\\\": str(user_id), \\\"type\\\": \\\"refresh\\\"}, timedelta(minutes=5))\\n    inactive_user = _dummy_user(user_id, active=False)\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.get_user_by_id\\\", new=AsyncMock(return_value=inactive_user)),\\n        pytest.raises(HTTPException) as exc,\\n    ):\\n        await auth_service.create_refresh_token(refresh_token, db)\\n\\n    assert exc.value.status_code == status.HTTP_401_UNAUTHORIZED\\n    assert \\\"inactive\\\" in exc.value.detail.lower()\\n\\n\\n# =============================================================================\\n# User Validation Tests\\n# =============================================================================\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_active_user_active(auth_service: AuthService):\\n    \\\"\\\"\\\"Test active user passes validation.\\\"\\\"\\\"\\n    user = _dummy_user(uuid4(), active=True)\\n    result = await auth_service.get_current_active_user(user)\\n    assert result is user\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_active_user_inactive(auth_service: AuthService):\\n    \\\"\\\"\\\"Test inactive user returns None.\\\"\\\"\\\"\\n    user = _dummy_user(uuid4(), active=False)\\n\\n    result = await auth_service.get_current_active_user(user)\\n    assert result is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_active_superuser_valid(auth_service: AuthService):\\n    \\\"\\\"\\\"Test active superuser passes validation.\\\"\\\"\\\"\\n    user = User(\\n        id=uuid4(),\\n        username=\\\"admin\\\",\\n        password=\\\"hashed\\\",  # noqa: S106 # pragma: allowlist secret\\n        is_active=True,\\n        is_superuser=True,\\n    )\\n    result = await auth_service.get_current_active_superuser(user)\\n    assert result is user\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_active_superuser_inactive(auth_service: AuthService):\\n    \\\"\\\"\\\"Test inactive superuser returns None.\\\"\\\"\\\"\\n    user = User(\\n        id=uuid4(),\\n        username=\\\"admin\\\",\\n        password=\\\"hashed\\\",  # noqa: S106 # pragma: allowlist secret\\n        is_active=False,\\n        is_superuser=True,\\n    )\\n\\n    result = await auth_service.get_current_active_superuser(user)\\n    assert result is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_active_superuser_not_superuser(auth_service: AuthService):\\n    \\\"\\\"\\\"Test non-superuser returns None.\\\"\\\"\\\"\\n    user = _dummy_user(uuid4(), active=True)  # is_superuser=False by default\\n\\n    result = await auth_service.get_current_active_superuser(user)\\n    assert result is None\\n\\n\\n# =============================================================================\\n# Authenticate User Tests\\n# =============================================================================\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_user_success(auth_service: AuthService):\\n    \\\"\\\"\\\"Test successful authentication.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    password = \\\"correct_password\\\"  # noqa: S105  # pragma: allowlist secret\\n    hashed = auth_service.get_password_hash(password)\\n    user = User(\\n        id=user_id,\\n        username=\\\"testuser\\\",\\n        password=hashed,  # pragma: allowlist secret\\n        is_active=True,\\n        is_superuser=False,\\n    )\\n    db = AsyncMock()\\n\\n    with patch(\\\"langflow.services.auth.service.get_user_by_username\\\", new=AsyncMock(return_value=user)):\\n        result = await auth_service.authenticate_user(\\\"testuser\\\", password, db)\\n\\n    assert result is user\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_user_wrong_password(auth_service: AuthService):\\n    \\\"\\\"\\\"Test authentication fails with wrong password.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    hashed = auth_service.get_password_hash(\\\"correct_password\\\")\\n    user = User(\\n        id=user_id,\\n        username=\\\"testuser\\\",\\n        password=hashed,  # pragma: allowlist secret\\n        is_active=True,\\n        is_superuser=False,\\n    )\\n    db = AsyncMock()\\n\\n    with patch(\\\"langflow.services.auth.service.get_user_by_username\\\", new=AsyncMock(return_value=user)):\\n        result = await auth_service.authenticate_user(\\\"testuser\\\", \\\"wrong_password\\\", db)\\n\\n    assert result is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_user_not_found(auth_service: AuthService):\\n    \\\"\\\"\\\"Test authentication returns None for non-existent user.\\\"\\\"\\\"\\n    db = AsyncMock()\\n\\n    with patch(\\\"langflow.services.auth.service.get_user_by_username\\\", new=AsyncMock(return_value=None)):\\n        result = await auth_service.authenticate_user(\\\"nonexistent\\\", \\\"password\\\", db)\\n\\n    assert result is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_user_inactive_never_logged_in(auth_service: AuthService):\\n    \\\"\\\"\\\"Test inactive user who never logged in gets 'waiting for approval'.\\\"\\\"\\\"\\n    user = User(\\n        id=uuid4(),\\n        username=\\\"testuser\\\",\\n        password=auth_service.get_password_hash(\\\"password\\\"),  # pragma: allowlist secret\\n        is_active=False,\\n        is_superuser=False,\\n        last_login_at=None,\\n    )\\n    db = AsyncMock()\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.get_user_by_username\\\", new=AsyncMock(return_value=user)),\\n        pytest.raises(HTTPException) as exc,\\n    ):\\n        await auth_service.authenticate_user(\\\"testuser\\\", \\\"password\\\", db)\\n\\n    assert exc.value.status_code == status.HTTP_400_BAD_REQUEST\\n    assert \\\"approval\\\" in exc.value.detail.lower()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authenticate_user_inactive_previously_logged_in(auth_service: AuthService):\\n    \\\"\\\"\\\"Test inactive user who previously logged in gets 'inactive user'.\\\"\\\"\\\"\\n    user = User(\\n        id=uuid4(),\\n        username=\\\"testuser\\\",\\n        password=auth_service.get_password_hash(\\\"password\\\"),  # pragma: allowlist secret\\n        is_active=False,\\n        is_superuser=False,\\n        last_login_at=datetime.now(timezone.utc),\\n    )\\n    db = AsyncMock()\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.get_user_by_username\\\", new=AsyncMock(return_value=user)),\\n        pytest.raises(HTTPException) as exc,\\n    ):\\n        await auth_service.authenticate_user(\\\"testuser\\\", \\\"password\\\", db)\\n\\n    assert exc.value.status_code == status.HTTP_401_UNAUTHORIZED\\n    assert \\\"inactive\\\" in exc.value.detail.lower()\\n\\n\\n# =============================================================================\\n# MCP Authentication Tests\\n# =============================================================================\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_active_user_mcp_active(auth_service: AuthService):\\n    \\\"\\\"\\\"Test MCP active user validation passes.\\\"\\\"\\\"\\n    user = _dummy_user(uuid4(), active=True)\\n    result = await auth_service.get_current_active_user_mcp(user)\\n    assert result is user\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_active_user_mcp_inactive(auth_service: AuthService):\\n    \\\"\\\"\\\"Test MCP inactive user validation fails.\\\"\\\"\\\"\\n    user = _dummy_user(uuid4(), active=False)\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await auth_service.get_current_active_user_mcp(user)\\n\\n    assert exc.value.status_code == status.HTTP_401_UNAUTHORIZED\\n\\n\\n# =============================================================================\\n# ws_api_key_security Tests\\n# =============================================================================\\n\\n\\n@asynccontextmanager\\nasync def _mock_session_scope():\\n    yield AsyncMock()\\n\\n\\n@pytest.mark.anyio\\nasync def test_ws_api_key_security_auto_login_skip_rejects_missing_superuser(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"ws_api_key_security must reject with WS_1011 when the superuser row is absent from DB.\\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = True\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.session_scope\\\", _mock_session_scope),\\n        patch(\\n            \\\"langflow.services.auth.service.get_user_by_username\\\",\\n            new=AsyncMock(return_value=None),\\n        ),\\n        pytest.raises(WebSocketException) as exc,\\n    ):\\n        await auth_service.ws_api_key_security(api_key=None)\\n\\n    assert exc.value.code == status.WS_1011_INTERNAL_ERROR\\n\\n\\n@pytest.mark.anyio\\nasync def test_ws_api_key_security_auto_login_skip_rejects_inactive_superuser(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"ws_api_key_security must enforce is_active in the AUTO_LOGIN + skip_auth bypass path.\\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = True\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n    inactive_superuser = _dummy_user(uuid4(), active=False)\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.session_scope\\\", _mock_session_scope),\\n        patch(\\n            \\\"langflow.services.auth.service.get_user_by_username\\\",\\n            new=AsyncMock(return_value=inactive_superuser),\\n        ),\\n        pytest.raises(WebSocketException) as exc,\\n    ):\\n        await auth_service.ws_api_key_security(api_key=None)\\n\\n    assert exc.value.code == status.WS_1008_POLICY_VIOLATION\\n\\n\\n# =============================================================================\\n# _api_key_security_impl Tests\\n# =============================================================================\\n\\n\\n@pytest.mark.anyio\\nasync def test_api_key_security_impl_auto_login_skip_rejects_inactive_superuser(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"_api_key_security_impl must enforce is_active in the AUTO_LOGIN + skip_auth bypass path.\\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = True\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n    inactive_superuser = _dummy_user(uuid4(), active=False)\\n\\n    with (\\n        patch(\\n            \\\"langflow.services.auth.service.get_user_by_username\\\",\\n            new=AsyncMock(return_value=inactive_superuser),\\n        ),\\n        pytest.raises(HTTPException) as exc,\\n    ):\\n        await auth_service._api_key_security_impl(\\n            query_param=None,\\n            header_param=None,\\n            db=AsyncMock(),\\n            settings_service=auth_service.settings,\\n        )\\n\\n    assert exc.value.status_code == status.HTTP_403_FORBIDDEN\\n\\n\\n# =============================================================================\\n# External-user materialization (F1): email is never erased by an email-less token\\n# =============================================================================\\n\\n\\ndef _external_jwt(auth_service: AuthService, claims: dict) -> str:\\n    \\\"\\\"\\\"Encode a trusted external JWT signed with the service secret.\\n\\n    A future ``exp`` is always supplied because the trusted-decode path requires\\n    it (see external._validate_trusted_time_claims).\\n    \\\"\\\"\\\"\\n    secret = auth_service.settings.auth_settings.SECRET_KEY.get_secret_value()\\n    payload = {\\\"exp\\\": datetime.now(timezone.utc) + timedelta(minutes=5), **claims}\\n    return jwt.encode(payload, secret, algorithm=\\\"HS256\\\")\\n\\n\\n@pytest.mark.anyio\\nasync def test_materialize_external_user_preserves_email_when_token_omits_it(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n    async_session,\\n):\\n    \\\"\\\"\\\"A later token without an email claim must not erase the stored email (F1).\\\"\\\"\\\"\\n    from langflow.services.auth.external import identity_from_claims\\n    from langflow.services.database.models.auth import SSOUserProfile\\n    from sqlmodel import select\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_PROVIDER = \\\"external\\\"\\n\\n    # First login carries an email and provisions the user + profile.\\n    identity_with_email = identity_from_claims(\\n        {\\\"sub\\\": \\\"ext-subject-1\\\", \\\"email\\\": \\\"alice@example.com\\\", \\\"preferred_username\\\": \\\"alice\\\"},\\n        auth_settings,\\n    )\\n    user = await auth_service._materialize_external_user(identity_with_email, async_session)\\n    await async_session.flush()\\n\\n    profile = (await async_session.exec(select(SSOUserProfile).where(SSOUserProfile.user_id == user.id))).first()\\n    assert profile is not None\\n    assert profile.email == \\\"alice@example.com\\\"\\n\\n    # Second login with the SAME subject but NO email claim must keep the stored email.\\n    identity_without_email = identity_from_claims(\\n        {\\\"sub\\\": \\\"ext-subject-1\\\", \\\"preferred_username\\\": \\\"alice\\\"},\\n        auth_settings,\\n    )\\n    assert identity_without_email.email is None\\n\\n    same_user = await auth_service._materialize_external_user(identity_without_email, async_session)\\n    await async_session.flush()\\n    await async_session.refresh(profile)\\n\\n    assert same_user.id == user.id\\n    assert profile.email == \\\"alice@example.com\\\"\\n\\n    # A later token that DOES carry an email still updates it.\\n    identity_new_email = identity_from_claims(\\n        {\\\"sub\\\": \\\"ext-subject-1\\\", \\\"email\\\": \\\"alice2@example.com\\\"},\\n        auth_settings,\\n    )\\n    await auth_service._materialize_external_user(identity_new_email, async_session)\\n    await async_session.flush()\\n    await async_session.refresh(profile)\\n    assert profile.email == \\\"alice2@example.com\\\"\\n\\n\\n# =============================================================================\\n# Verified external-group reconciliation\\n# =============================================================================\\n\\n\\nclass _DirectoryAuthorizationStub:\\n    \\\"\\\"\\\"Authorization seam double for verified external-group reconciliation.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        *,\\n        result,\\n        claim_name: str | None = \\\"groups\\\",\\n        claim_path: tuple[str, ...] | None = None,\\n        supports_incomplete: bool = True,\\n    ) -> None:\\n        self.external_groups_claim = AsyncMock(return_value=claim_name)\\n        self.external_groups_claim_path = AsyncMock(\\n            return_value=claim_path if claim_path is not None else ((claim_name,) if claim_name else None)\\n        )\\n        self.ingest_directory_membership_snapshot = AsyncMock(return_value=result)\\n        self.directory_membership_committed = AsyncMock()\\n        self.supports_incomplete_directory_membership_snapshots = AsyncMock(return_value=supports_incomplete)\\n\\n\\ndef _external_identity(claims: dict):\\n    from langflow.services.auth.external import ExternalIdentity\\n\\n    return ExternalIdentity(\\n        provider=\\\"customer-idp\\\",\\n        subject=\\\"external-subject\\\",\\n        username=\\\"external-user\\\",\\n        claims=claims,\\n    )\\n\\n\\n@pytest.mark.anyio\\nasync def test_external_group_reconciliation_normalizes_commits_and_audits(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=True, added=2, removed=1))\\n    audit = AsyncMock()\\n    identity = _external_identity(\\n        {\\n            \\\"iss\\\": \\\" https://issuer.example \\\",\\n            \\\"aud\\\": [\\\"langflow-api\\\"],\\n            \\\"groups\\\": [\\\" reviewers \\\", \\\"engineering\\\", \\\"reviewers\\\"],\\n        }\\n    )\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(identity=identity, user=user, db=db)\\n\\n    snapshot = authz.ingest_directory_membership_snapshot.await_args.kwargs[\\\"snapshot\\\"]\\n    assert snapshot.provider_id == \\\"customer-idp\\\"\\n    assert snapshot.provider_user_id == \\\"external-subject\\\"\\n    assert snapshot.user_id == user.id\\n    assert snapshot.memberships == (\\\"engineering\\\", \\\"reviewers\\\")\\n    assert snapshot.authoritative is True\\n    assert snapshot.complete is True\\n    assert snapshot.claim_state is None\\n    assert snapshot.claim_path == (\\\"groups\\\",)\\n    db.commit.assert_awaited_once()\\n    authz.directory_membership_committed.assert_awaited_once_with(user_id=user.id, changed=True)\\n\\n    audit_details = audit.await_args.kwargs\\n    assert audit_details[\\\"action\\\"] == \\\"directory_membership:reconcile\\\"\\n    assert audit_details[\\\"obj\\\"] == f\\\"user:{user.id}\\\"\\n    assert audit_details[\\\"result\\\"] == \\\"allow\\\"\\n    assert audit_details[\\\"details\\\"] == {\\n        \\\"provider_id\\\": \\\"customer-idp\\\",\\n        \\\"issuer\\\": \\\"https://issuer.example\\\",\\n        \\\"subject\\\": \\\"external-subject\\\",\\n        \\\"audience\\\": [\\\"langflow-api\\\"],\\n        \\\"source\\\": \\\"external_bearer\\\",\\n        \\\"membership_count\\\": 2,\\n        \\\"membership_sha256\\\": hashlib.sha256(b\\\"engineering\\\\0reviewers\\\").hexdigest(),\\n        \\\"changed\\\": True,\\n        \\\"added\\\": 2,\\n        \\\"removed\\\": 1,\\n        \\\"authoritative\\\": True,\\n        \\\"complete\\\": True,\\n    }\\n\\n\\n@pytest.mark.anyio\\nasync def test_external_group_reconciliation_accepts_present_empty_claim(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipClaimState, DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult())\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=AsyncMock()),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({\\\"groups\\\": []}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    snapshot = authz.ingest_directory_membership_snapshot.await_args.kwargs[\\\"snapshot\\\"]\\n    assert snapshot.memberships == ()\\n    assert snapshot.claim_state is DirectoryMembershipClaimState.EMPTY\\n    db.commit.assert_awaited_once()\\n    authz.directory_membership_committed.assert_awaited_once_with(user_id=user.id, changed=False)\\n\\n\\n@pytest.mark.anyio\\nasync def test_external_group_reconciliation_resolves_nested_claim_path(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(\\n        result=DirectoryMembershipIngestResult(),\\n        claim_path=(\\\"realm_access\\\", \\\"groups\\\"),\\n    )\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=AsyncMock()),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({\\\"realm_access\\\": {\\\"groups\\\": [\\\" engineering \\\"]}}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    snapshot = authz.ingest_directory_membership_snapshot.await_args.kwargs[\\\"snapshot\\\"]\\n    assert snapshot.memberships == (\\\"engineering\\\",)\\n    assert snapshot.claim_path == (\\\"realm_access\\\", \\\"groups\\\")\\n    authz.external_groups_claim.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_nested_claim_path_does_not_collide_with_literal_dotted_overage_name(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(\\n        result=DirectoryMembershipIngestResult(),\\n        claim_path=(\\\"realm_access\\\", \\\"groups\\\"),\\n    )\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=AsyncMock()),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity(\\n                {\\n                    \\\"_claim_names\\\": {\\\"realm_access.groups\\\": \\\"src1\\\"},\\n                    \\\"realm_access\\\": {\\\"groups\\\": [\\\"engineering\\\"]},\\n                }\\n            ),\\n            user=user,\\n            db=db,\\n        )\\n\\n    snapshot = authz.ingest_directory_membership_snapshot.await_args.kwargs[\\\"snapshot\\\"]\\n    assert snapshot.memberships == (\\\"engineering\\\",)\\n    assert snapshot.claim_state is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_nested_claim_path_detects_top_level_parent_overage(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipClaimState, DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(\\n        result=DirectoryMembershipIngestResult(),\\n        claim_path=(\\\"realm_access\\\", \\\"groups\\\"),\\n    )\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=AsyncMock()),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({\\\"_claim_names\\\": {\\\"realm_access\\\": \\\"src1\\\"}}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    snapshot = authz.ingest_directory_membership_snapshot.await_args.kwargs[\\\"snapshot\\\"]\\n    assert snapshot.memberships == ()\\n    assert snapshot.claim_state is DirectoryMembershipClaimState.OVERAGE\\n\\n\\n@pytest.mark.anyio\\nasync def test_external_group_reconciliation_marks_invalid_nested_container_malformed(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipClaimState, DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(\\n        result=DirectoryMembershipIngestResult(),\\n        claim_path=(\\\"realm_access\\\", \\\"groups\\\"),\\n    )\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=AsyncMock()),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({\\\"realm_access\\\": \\\"not-an-object\\\"}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    snapshot = authz.ingest_directory_membership_snapshot.await_args.kwargs[\\\"snapshot\\\"]\\n    assert snapshot.claim_state is DirectoryMembershipClaimState.MALFORMED\\n    assert snapshot.authoritative is False\\n    assert snapshot.complete is False\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"claims\\\", \\\"expected_reason\\\"),\\n    [\\n        ({\\\"iss\\\": \\\"https://issuer.example\\\"}, \\\"absent\\\"),\\n        (\\n            {\\\"_claim_names\\\": {\\\"groups\\\": \\\"src1\\\"}, \\\"_claim_sources\\\": {\\\"src1\\\": {\\\"endpoint\\\": \\\"https://graph\\\"}}},\\n            \\\"overage\\\",\\n        ),\\n        ({\\\"groups\\\": {\\\"unexpected\\\": \\\"mapping\\\"}}, \\\"malformed\\\"),\\n        ({\\\"groups\\\": [\\\"engineering\\\", 7]}, \\\"malformed\\\"),\\n        ({\\\"groups\\\": [\\\"   \\\"]}, \\\"malformed\\\"),\\n        ({\\\"groups\\\": [\\\"x\\\" * 257]}, \\\"malformed\\\"),\\n        ({\\\"groups\\\": [f\\\"group-{index}\\\" for index in range(501)]}, \\\"too_many\\\"),\\n    ],\\n    ids=[\\\"absent\\\", \\\"entra-overage\\\", \\\"invalid-type\\\", \\\"non-string\\\", \\\"blank\\\", \\\"overlong\\\", \\\"too-many\\\"],\\n)\\n@pytest.mark.anyio\\nasync def test_incomplete_external_group_claim_skips_authoritative_reconciliation(\\n    auth_service: AuthService,\\n    claims: dict,\\n    expected_reason: str,\\n):\\n    from lfx.services.authorization import DirectoryMembershipClaimState, DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=True))\\n    events: list[str] = []\\n    db.commit.side_effect = lambda: events.append(\\\"commit\\\")\\n    audit = AsyncMock(side_effect=lambda **_kwargs: events.append(\\\"audit\\\"))\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity(claims),\\n            user=user,\\n            db=db,\\n        )\\n\\n    snapshot = authz.ingest_directory_membership_snapshot.await_args.kwargs[\\\"snapshot\\\"]\\n    assert snapshot.memberships == ()\\n    assert snapshot.authoritative is False\\n    assert snapshot.complete is False\\n    assert snapshot.claim_state is DirectoryMembershipClaimState(expected_reason)\\n    assert snapshot.claim_path == (\\\"groups\\\",)\\n    db.commit.assert_awaited_once()\\n    authz.directory_membership_committed.assert_awaited_once_with(user_id=user.id, changed=True)\\n    audit.assert_awaited_once()\\n    assert events == [\\\"commit\\\", \\\"audit\\\"]\\n    audit_call = audit.await_args.kwargs\\n    assert audit_call[\\\"action\\\"] == \\\"directory_membership:reconcile\\\"\\n    assert audit_call[\\\"obj\\\"] == f\\\"user:{user.id}\\\"\\n    assert audit_call[\\\"result\\\"] == \\\"skip\\\"\\n    assert audit_call[\\\"details\\\"] == {\\n        \\\"provider_id\\\": \\\"customer-idp\\\",\\n        \\\"issuer\\\": claims.get(\\\"iss\\\"),\\n        \\\"subject\\\": \\\"external-subject\\\",\\n        \\\"audience\\\": None,\\n        \\\"source\\\": \\\"external_bearer\\\",\\n        \\\"claim_name\\\": \\\"groups\\\",\\n        \\\"reason\\\": expected_reason,\\n        \\\"authoritative\\\": False,\\n        \\\"complete\\\": False,\\n    }\\n\\n\\n@pytest.mark.anyio\\nasync def test_incomplete_external_group_claim_reaches_plugin_before_commit(auth_service: AuthService):\\n    from lfx.services.authorization import AuthorizationMutationRejected\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=None)\\n    authz.ingest_directory_membership_snapshot.side_effect = AuthorizationMutationRejected(\\\"Group claim required\\\")\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=AsyncMock()) as audit,\\n        pytest.raises(InvalidTokenError, match=\\\"Group claim required\\\") as exc_info,\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    authz.ingest_directory_membership_snapshot.assert_awaited_once()\\n    db.commit.assert_not_awaited()\\n    audit.assert_not_awaited()\\n    assert isinstance(exc_info.value.__cause__, AuthorizationMutationRejected)\\n\\n\\n@pytest.mark.anyio\\nasync def test_incomplete_external_group_claim_preserves_legacy_complete_only_plugin_contract(\\n    auth_service: AuthService,\\n):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(\\n        result=DirectoryMembershipIngestResult(changed=True),\\n        supports_incomplete=False,\\n    )\\n    audit = AsyncMock()\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    authz.supports_incomplete_directory_membership_snapshots.assert_awaited_once_with()\\n    authz.ingest_directory_membership_snapshot.assert_not_awaited()\\n    authz.directory_membership_committed.assert_not_awaited()\\n    db.commit.assert_awaited_once()\\n    assert audit.await_args.kwargs[\\\"result\\\"] == \\\"skip\\\"\\n    assert audit.await_args.kwargs[\\\"details\\\"][\\\"reason\\\"] == \\\"absent\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_incomplete_external_group_claim_preserves_duck_typed_legacy_plugin_contract(\\n    auth_service: AuthService,\\n):\\n    \\\"\\\"\\\"A plugin predating the capability method never receives ambiguous empty membership.\\\"\\\"\\\"\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=True))\\n    del authz.supports_incomplete_directory_membership_snapshots\\n    audit = AsyncMock()\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    authz.ingest_directory_membership_snapshot.assert_not_awaited()\\n    authz.directory_membership_committed.assert_not_awaited()\\n    db.commit.assert_awaited_once()\\n    assert audit.await_args.kwargs[\\\"result\\\"] == \\\"skip\\\"\\n    assert audit.await_args.kwargs[\\\"details\\\"][\\\"reason\\\"] == \\\"absent\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_external_group_reconciliation_plugin_opt_out_is_not_a_skip(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(\\n        result=DirectoryMembershipIngestResult(changed=True),\\n        claim_name=None,\\n    )\\n    audit = AsyncMock()\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    authz.ingest_directory_membership_snapshot.assert_not_awaited()\\n    db.commit.assert_not_awaited()\\n    audit.assert_not_awaited()\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"legacy_result\\\",\\n    [None, SimpleNamespace(changed=True)],\\n    ids=[\\\"none\\\", \\\"changed-only\\\"],\\n)\\n@pytest.mark.anyio\\nasync def test_legacy_directory_ingest_result_invalidates_conservatively(\\n    auth_service: AuthService,\\n    legacy_result,\\n):\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=legacy_result)\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=AsyncMock()),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({\\\"groups\\\": [\\\"engineering\\\"]}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    db.commit.assert_awaited_once()\\n    authz.directory_membership_committed.assert_awaited_once_with(user_id=user.id, changed=True)\\n\\n\\n@pytest.mark.anyio\\nasync def test_directory_post_commit_failure_does_not_fail_authentication(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=True, added=1))\\n    authz.directory_membership_committed.side_effect = RuntimeError(\\\"replica unavailable\\\")\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=AsyncMock()),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({\\\"groups\\\": [\\\"engineering\\\"]}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    db.commit.assert_awaited_once()\\n    authz.directory_membership_committed.assert_awaited_once_with(user_id=user.id, changed=True)\\n\\n\\n@pytest.mark.anyio\\nasync def test_directory_post_commit_audit_failure_does_not_fail_authentication(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=True, added=1))\\n    audit = AsyncMock(side_effect=RuntimeError(\\\"audit settings unavailable\\\"))\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({\\\"groups\\\": [\\\"engineering\\\"]}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    db.commit.assert_awaited_once()\\n    audit.assert_awaited_once()\\n    authz.directory_membership_committed.assert_awaited_once_with(user_id=user.id, changed=True)\\n\\n\\n@pytest.mark.anyio\\nasync def test_directory_skip_audit_failure_does_not_fail_authentication(auth_service: AuthService):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=True))\\n    audit = AsyncMock(side_effect=RuntimeError(\\\"audit settings unavailable\\\"))\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    authz.ingest_directory_membership_snapshot.assert_awaited_once()\\n    db.commit.assert_awaited_once()\\n    audit.assert_awaited_once()\\n    authz.directory_membership_committed.assert_awaited_once_with(user_id=user.id, changed=True)\\n\\n\\n# =============================================================================\\n# LE-2109: bearer tokens arrive on every request, so an unchanged directory\\n# state must not be reconciled (and audited) again on every one of them.\\n# =============================================================================\\n\\n\\n@pytest.mark.anyio\\nasync def test_unchanged_directory_state_reconciles_once_per_interval(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 60\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=False))\\n    audit = AsyncMock()\\n    identity = _external_identity({\\\"groups\\\": [\\\"engineering\\\", \\\"reviewers\\\"]})\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        for _ in range(5):\\n            await auth_service._reconcile_verified_external_groups(identity=identity, user=user, db=db)\\n\\n    # One reconciliation and one audit row for five authenticated requests,\\n    # while the JIT/profile bookkeeping of every request is still committed.\\n    authz.ingest_directory_membership_snapshot.assert_awaited_once()\\n    assert audit.await_count == 1\\n    assert db.commit.await_count == 5\\n\\n\\n@pytest.mark.anyio\\nasync def test_changed_group_claim_reconciles_immediately(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 3600\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=False))\\n    audit = AsyncMock()\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({\\\"groups\\\": [\\\"engineering\\\"]}),\\n            user=user,\\n            db=db,\\n        )\\n        await auth_service._reconcile_verified_external_groups(\\n            identity=_external_identity({\\\"groups\\\": [\\\"engineering\\\", \\\"reviewers\\\"]}),\\n            user=user,\\n            db=db,\\n        )\\n\\n    assert authz.ingest_directory_membership_snapshot.await_count == 2\\n    memberships = [\\n        call.kwargs[\\\"snapshot\\\"].memberships for call in authz.ingest_directory_membership_snapshot.await_args_list\\n    ]\\n    assert memberships == [(\\\"engineering\\\",), (\\\"engineering\\\", \\\"reviewers\\\")]\\n\\n\\n@pytest.mark.anyio\\nasync def test_reconciliation_that_changed_state_is_confirmed_before_it_is_cached(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"A pass that wrote something must not hide the next request's retry.\\\"\\\"\\\"\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 3600\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=True, added=1))\\n    audit = AsyncMock()\\n    identity = _external_identity({\\\"groups\\\": [\\\"engineering\\\"]})\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(identity=identity, user=user, db=db)\\n        authz.ingest_directory_membership_snapshot.return_value = DirectoryMembershipIngestResult(changed=False)\\n        await auth_service._reconcile_verified_external_groups(identity=identity, user=user, db=db)\\n        await auth_service._reconcile_verified_external_groups(identity=identity, user=user, db=db)\\n\\n    assert authz.ingest_directory_membership_snapshot.await_count == 2\\n\\n\\n@pytest.mark.anyio\\nasync def test_zero_reconcile_interval_reconciles_every_request(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 0\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=False))\\n    audit = AsyncMock()\\n    identity = _external_identity({\\\"groups\\\": [\\\"engineering\\\"]})\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        for _ in range(3):\\n            await auth_service._reconcile_verified_external_groups(identity=identity, user=user, db=db)\\n\\n    assert authz.ingest_directory_membership_snapshot.await_count == 3\\n\\n\\n@pytest.mark.anyio\\nasync def test_incomplete_claim_skip_is_not_audited_on_every_request(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 60\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(\\n        result=DirectoryMembershipIngestResult(),\\n        supports_incomplete=False,\\n    )\\n    audit = AsyncMock()\\n    identity = _external_identity({})\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        for _ in range(4):\\n            await auth_service._reconcile_verified_external_groups(identity=identity, user=user, db=db)\\n\\n    authz.ingest_directory_membership_snapshot.assert_not_awaited()\\n    assert audit.await_count == 1\\n    assert db.commit.await_count == 4\\n\\n\\n@pytest.mark.anyio\\nasync def test_group_revoked_after_promotion_reconciles_immediately(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"A group set the user moved past must not be served from an earlier cache entry.\\n\\n    LE-2099 QA follow-up: ``[devs]`` reconciled and cached, then a promotion to\\n    ``[admins, devs]``, then the IdP revokes ``admins``. The claim now differs\\n    from the last reconciled state, so it must reconcile on the next request\\n    rather than after the interval expires - privilege removal is the case\\n    that must not be delayed.\\n    \\\"\\\"\\\"\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 3600\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=True, added=1))\\n    audit = AsyncMock()\\n    developer = _external_identity({\\\"groups\\\": [\\\"lf-devs\\\"]})\\n    promoted = _external_identity({\\\"groups\\\": [\\\"lf-admins\\\", \\\"lf-devs\\\"]})\\n    ingest = authz.ingest_directory_membership_snapshot\\n\\n    async def reconcile(identity, *, changed: bool) -> None:\\n        ingest.return_value = DirectoryMembershipIngestResult(changed=changed, added=int(changed))\\n        await auth_service._reconcile_verified_external_groups(identity=identity, user=user, db=db)\\n\\n    def memberships_seen() -> list[tuple[str, ...]]:\\n        return [call.kwargs[\\\"snapshot\\\"].memberships for call in ingest.await_args_list]\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        # 1) first login grants developer, 2) the confirming pass caches [devs]\\n        await reconcile(developer, changed=True)\\n        await reconcile(developer, changed=False)\\n        await reconcile(developer, changed=False)\\n        assert ingest.await_count == 2, \\\"the confirming pass must be cached\\\"\\n\\n        # 3) promotion: a group set never seen before reconciles at once\\n        await reconcile(promoted, changed=True)\\n        assert ingest.await_count == 3\\n\\n        # 4) revocation back to the earlier group set must reconcile immediately,\\n        #    even though [devs] was cached in step 2 and its TTL has not expired.\\n        await reconcile(developer, changed=True)\\n        assert ingest.await_count == 4, \\\"a revoked group kept its role from a stale cache entry\\\"\\n        assert memberships_seen()[-1] == (\\\"lf-devs\\\",)\\n\\n        # The confirming pass caches the reconciled state again and later\\n        # identical requests are still skipped: the cache keeps working.\\n        await reconcile(developer, changed=False)\\n        await reconcile(developer, changed=False)\\n        await reconcile(developer, changed=False)\\n        assert ingest.await_count == 5\\n\\n        # A later promotion is again a change from the last reconciled state.\\n        await reconcile(promoted, changed=True)\\n        assert ingest.await_count == 6\\n\\n    assert memberships_seen() == [\\n        (\\\"lf-devs\\\",),\\n        (\\\"lf-devs\\\",),\\n        (\\\"lf-admins\\\", \\\"lf-devs\\\"),\\n        (\\\"lf-devs\\\",),\\n        (\\\"lf-devs\\\",),\\n        (\\\"lf-admins\\\", \\\"lf-devs\\\"),\\n    ]\\n\\n\\n@pytest.mark.anyio\\nasync def test_revocation_reconciles_even_after_the_promotion_was_confirmed_and_cached(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"Both the promoted and the earlier state were cached; the older one must not win.\\\"\\\"\\\"\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 3600\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=False))\\n    audit = AsyncMock()\\n    developer = _external_identity({\\\"groups\\\": [\\\"lf-devs\\\"]})\\n    promoted = _external_identity({\\\"groups\\\": [\\\"lf-admins\\\", \\\"lf-devs\\\"]})\\n    ingest = authz.ingest_directory_membership_snapshot\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(identity=developer, user=user, db=db)\\n        ingest.return_value = DirectoryMembershipIngestResult(changed=True, added=1)\\n        await auth_service._reconcile_verified_external_groups(identity=promoted, user=user, db=db)\\n        ingest.return_value = DirectoryMembershipIngestResult(changed=False)\\n        await auth_service._reconcile_verified_external_groups(identity=promoted, user=user, db=db)\\n        assert ingest.await_count == 3\\n\\n        # Revocation: [devs] is the state cached first, [admins, devs] the one\\n        # cached last. Neither may hide the change.\\n        ingest.return_value = DirectoryMembershipIngestResult(changed=True, removed=1)\\n        await auth_service._reconcile_verified_external_groups(identity=developer, user=user, db=db)\\n\\n    assert ingest.await_count == 4\\n    assert ingest.await_args_list[-1].kwargs[\\\"snapshot\\\"].memberships == (\\\"lf-devs\\\",)\\n\\n\\n@pytest.mark.anyio\\nasync def test_reconcile_cache_is_scoped_per_user(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"Remembering one user's state must not evict or leak into another user's entry.\\\"\\\"\\\"\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 3600\\n    first_user = _dummy_user(uuid4())\\n    second_user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    authz = _DirectoryAuthorizationStub(result=DirectoryMembershipIngestResult(changed=False))\\n    audit = AsyncMock()\\n    identity = _external_identity({\\\"groups\\\": [\\\"engineering\\\"]})\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        await auth_service._reconcile_verified_external_groups(identity=identity, user=first_user, db=db)\\n        await auth_service._reconcile_verified_external_groups(identity=identity, user=second_user, db=db)\\n        await auth_service._reconcile_verified_external_groups(identity=identity, user=first_user, db=db)\\n        await auth_service._reconcile_verified_external_groups(identity=identity, user=second_user, db=db)\\n\\n    assert authz.ingest_directory_membership_snapshot.await_count == 2\\n\\n\\n@pytest.mark.anyio\\nasync def test_change_landing_after_a_concurrent_noop_pass_evicts_its_entry(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"An old-token no-op pass must not keep serving once an overlapping pass changed the state.\\n\\n    The promotion pass begins first and is held inside the plugin. Meanwhile\\n    the old token's ``[devs]`` pass verifies the still-unchanged state and is\\n    remembered. When the promotion commits, that entry must be evicted, or\\n    the next ``[devs]`` request would be skipped while the user holds admin.\\n    \\\"\\\"\\\"\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 3600\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n    audit = AsyncMock()\\n    developer = _external_identity({\\\"groups\\\": [\\\"lf-devs\\\"]})\\n    promoted = _external_identity({\\\"groups\\\": [\\\"lf-admins\\\", \\\"lf-devs\\\"]})\\n    promotion_in_plugin = asyncio.Event()\\n    release_promotion = asyncio.Event()\\n\\n    async def ingest(*, session, snapshot):  # noqa: ARG001\\n        if snapshot.memberships == (\\\"lf-admins\\\", \\\"lf-devs\\\"):\\n            promotion_in_plugin.set()\\n            await release_promotion.wait()\\n            return DirectoryMembershipIngestResult(changed=True, added=1)\\n        return DirectoryMembershipIngestResult(changed=False)\\n\\n    authz = _DirectoryAuthorizationStub(result=None)\\n    authz.ingest_directory_membership_snapshot = AsyncMock(side_effect=ingest)\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        promotion = asyncio.create_task(\\n            auth_service._reconcile_verified_external_groups(identity=promoted, user=user, db=db)\\n        )\\n        await promotion_in_plugin.wait()\\n        await auth_service._reconcile_verified_external_groups(identity=developer, user=user, db=db)\\n        assert authz.ingest_directory_membership_snapshot.await_count == 2\\n        release_promotion.set()\\n        await promotion\\n\\n        await auth_service._reconcile_verified_external_groups(identity=developer, user=user, db=db)\\n\\n    assert authz.ingest_directory_membership_snapshot.await_count == 3, (\\n        \\\"the [devs] verdict cached before the promotion landed was served after it\\\"\\n    )\\n    assert authz.ingest_directory_membership_snapshot.await_args_list[-1].kwargs[\\\"snapshot\\\"].memberships == (\\\"lf-devs\\\",)\\n\\n\\n@pytest.mark.anyio\\nasync def test_noop_pass_that_verified_a_superseded_state_is_not_remembered(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"A no-op verdict reached before a change landed must be discarded, not cached after it.\\n\\n    The old token's ``[devs]`` pass verifies the state and is held at commit.\\n    The promotion then begins, changes the state and commits. When the held\\n    pass resumes and tries to remember ``[devs]``, its verdict describes a\\n    state the user has moved past and must be dropped.\\n    \\\"\\\"\\\"\\n    from lfx.services.authorization import DirectoryMembershipIngestResult\\n\\n    auth_settings.EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS = 3600\\n    user = _dummy_user(uuid4())\\n    audit = AsyncMock()\\n    developer = _external_identity({\\\"groups\\\": [\\\"lf-devs\\\"]})\\n    promoted = _external_identity({\\\"groups\\\": [\\\"lf-admins\\\", \\\"lf-devs\\\"]})\\n    developer_at_commit = asyncio.Event()\\n    release_developer = asyncio.Event()\\n\\n    async def held_commit() -> None:\\n        developer_at_commit.set()\\n        await release_developer.wait()\\n\\n    held_db = AsyncMock()\\n    held_db.commit = AsyncMock(side_effect=held_commit)\\n    db = AsyncMock()\\n\\n    async def ingest(*, session, snapshot):  # noqa: ARG001\\n        if snapshot.memberships == (\\\"lf-admins\\\", \\\"lf-devs\\\"):\\n            return DirectoryMembershipIngestResult(changed=True, added=1)\\n        return DirectoryMembershipIngestResult(changed=False)\\n\\n    authz = _DirectoryAuthorizationStub(result=None)\\n    authz.ingest_directory_membership_snapshot = AsyncMock(side_effect=ingest)\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch(\\\"langflow.services.authorization.audit.audit_decision\\\", new=audit),\\n    ):\\n        held = asyncio.create_task(\\n            auth_service._reconcile_verified_external_groups(identity=developer, user=user, db=held_db)\\n        )\\n        await developer_at_commit.wait()\\n        await auth_service._reconcile_verified_external_groups(identity=promoted, user=user, db=db)\\n        assert authz.ingest_directory_membership_snapshot.await_count == 2\\n        release_developer.set()\\n        await held\\n\\n        await auth_service._reconcile_verified_external_groups(identity=developer, user=user, db=db)\\n\\n    assert authz.ingest_directory_membership_snapshot.await_count == 3, (\\n        \\\"a stale [devs] verdict was cached after the promotion had already landed\\\"\\n    )\\n\\n\\n# =============================================================================\\n# LE-2099 / BUG-02: a backend outage is not a credential verdict\\n# =============================================================================\\n\\n\\n@pytest.mark.anyio\\nasync def test_transient_database_failure_is_not_reported_as_an_authentication_failure(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"A deadlock victim never judged the token, so it must not answer 401.\\\"\\\"\\\"\\n    from langflow.services.auth.exceptions import AuthBackendUnavailableError\\n    from sqlalchemy.exc import DBAPIError\\n\\n    class _DeadlockDetectedError(Exception):\\n        \\\"\\\"\\\"Stand-in for psycopg's DeadlockDetected (SQLSTATE 40P01).\\\"\\\"\\\"\\n\\n        sqlstate = \\\"40P01\\\"\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    identity = _external_identity({\\\"groups\\\": [\\\"engineering\\\"]})\\n    deadlock = DBAPIError(\\n        \\\"SELECT pg_advisory_xact_lock(%(lock_key)s::BIGINT)\\\",\\n        {},\\n        _DeadlockDetectedError(\\\"deadlock detected\\\"),\\n    )\\n    db = AsyncMock()\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.resolve_external_identity\\\", AsyncMock(return_value=identity)),\\n        patch.object(auth_service, \\\"_materialize_external_user\\\", AsyncMock(return_value=_dummy_user(uuid4()))),\\n        patch.object(\\n            auth_service,\\n            \\\"_reconcile_verified_external_groups\\\",\\n            AsyncMock(side_effect=deadlock),\\n        ),\\n        pytest.raises(AuthBackendUnavailableError) as exc_info,\\n    ):\\n        await auth_service._authenticate_with_external_token(\\\"external-token\\\", db)\\n\\n    assert exc_info.value.error_code == \\\"auth_backend_unavailable\\\"\\n    assert exc_info.value.__cause__ is deadlock\\n\\n\\n@pytest.mark.anyio\\nasync def test_backend_unavailable_short_circuits_the_remaining_credentials(auth_service: AuthService):\\n    \\\"\\\"\\\"A backend outage must not be retried against every other credential.\\\"\\\"\\\"\\n    from langflow.services.auth.exceptions import AuthBackendUnavailableError\\n\\n    db = AsyncMock()\\n    outage = AuthBackendUnavailableError()\\n\\n    with (\\n        patch.object(auth_service, \\\"_authenticate_with_token\\\", side_effect=outage),\\n        patch.object(auth_service, \\\"_authenticate_with_external_token\\\", new=AsyncMock()) as external,\\n        patch.object(auth_service, \\\"_authenticate_with_api_key\\\", new=AsyncMock()) as api_key,\\n        pytest.raises(AuthBackendUnavailableError) as exc_info,\\n    ):\\n        await auth_service.authenticate_with_credentials(\\n            token=\\\"native-token\\\",  # noqa: S106  # pragma: allowlist secret\\n            api_key=\\\"an-api-key\\\",  # pragma: allowlist secret\\n            db=db,\\n            external_token=\\\"external-token\\\",  # noqa: S106  # pragma: allowlist secret\\n        )\\n\\n    assert exc_info.value is outage\\n    external.assert_not_awaited()\\n    api_key.assert_not_awaited()\\n\\n\\ndef test_backend_unavailable_maps_to_a_retryable_503():\\n    from fastapi import status\\n    from langflow.services.auth.exceptions import AuthBackendUnavailableError\\n    from langflow.services.auth.utils import _auth_error_to_http\\n\\n    http_error = _auth_error_to_http(AuthBackendUnavailableError())\\n\\n    assert http_error.status_code == status.HTTP_503_SERVICE_UNAVAILABLE\\n    assert http_error.headers == {\\\"Retry-After\\\": \\\"1\\\"}\\n\\n\\n@pytest.mark.anyio\\nasync def test_a_deadlocked_attempt_is_replayed_before_it_is_reported(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"The victim transaction rolled back, so replaying it is the fix.\\\"\\\"\\\"\\n    from sqlalchemy.exc import DBAPIError\\n\\n    class _DeadlockDetectedError(Exception):\\n        sqlstate = \\\"40P01\\\"\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    identity = _external_identity({\\\"groups\\\": [\\\"engineering\\\"]})\\n    reconcile = AsyncMock(side_effect=[DBAPIError(\\\"stmt\\\", {}, _DeadlockDetectedError(\\\"deadlock detected\\\")), None])\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.resolve_external_identity\\\", AsyncMock(return_value=identity)),\\n        patch.object(auth_service, \\\"_materialize_external_user\\\", AsyncMock(return_value=user)),\\n        patch.object(auth_service, \\\"_reconcile_verified_external_groups\\\", reconcile),\\n    ):\\n        resolved = await auth_service._authenticate_with_external_token(\\\"external-token\\\", db)\\n\\n    assert resolved is user\\n    assert reconcile.await_count == 2\\n    db.rollback.assert_awaited_once()\\n\\n\\n@pytest.mark.anyio\\nasync def test_a_concurrent_assignment_race_is_replayed_not_rejected(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"Two logins racing to create one effective assignment converge on replay.\\\"\\\"\\\"\\n    from sqlalchemy.exc import IntegrityError\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    identity = _external_identity({\\\"groups\\\": [\\\"engineering\\\"]})\\n    race = IntegrityError(\\\"INSERT INTO authz_role_assignment ...\\\", {}, Exception(\\\"UNIQUE constraint failed\\\"))\\n    reconcile = AsyncMock(side_effect=[race, None])\\n    user = _dummy_user(uuid4())\\n    db = AsyncMock()\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.resolve_external_identity\\\", AsyncMock(return_value=identity)),\\n        patch.object(auth_service, \\\"_materialize_external_user\\\", AsyncMock(return_value=user)),\\n        patch.object(auth_service, \\\"_reconcile_verified_external_groups\\\", reconcile),\\n    ):\\n        resolved = await auth_service._authenticate_with_external_token(\\\"external-token\\\", db)\\n\\n    assert resolved is user\\n    assert reconcile.await_count == 2\\n\\n\\ndef test_only_rolled_back_backend_failures_count_as_retryable():\\n    \\\"\\\"\\\"A constraint violation is a real verdict; a deadlock victim is not.\\\"\\\"\\\"\\n    from langflow.services.auth.service import _is_retryable_backend_failure\\n    from sqlalchemy.exc import DBAPIError, IntegrityError, OperationalError\\n\\n    class _OrigError(Exception):\\n        def __init__(self, sqlstate: str) -> None:\\n            super().__init__(sqlstate)\\n            self.sqlstate = sqlstate\\n\\n    assert _is_retryable_backend_failure(DBAPIError(\\\"stmt\\\", {}, _OrigError(\\\"40P01\\\"))) is True\\n    assert _is_retryable_backend_failure(DBAPIError(\\\"stmt\\\", {}, _OrigError(\\\"40001\\\"))) is True\\n    assert _is_retryable_backend_failure(OperationalError(\\\"stmt\\\", {}, _OrigError(\\\"57P01\\\"))) is True\\n    assert _is_retryable_backend_failure(IntegrityError(\\\"stmt\\\", {}, _OrigError(\\\"23505\\\"))) is False\\n    assert _is_retryable_backend_failure(ValueError(\\\"unrelated\\\")) is False\\n\\n    # A transient failure re-raised behind an application error still counts.\\n    wrapped = RuntimeError(\\\"reconciliation failed\\\")\\n    wrapped.__cause__ = DBAPIError(\\\"stmt\\\", {}, _OrigError(\\\"40P01\\\"))\\n    assert _is_retryable_backend_failure(wrapped) is True\\n\\n\\ndef test_credential_errors_keep_their_existing_status_codes():\\n    from fastapi import status\\n    from langflow.services.auth.exceptions import InvalidCredentialsError\\n    from langflow.services.auth.utils import _auth_error_to_http\\n\\n    assert _auth_error_to_http(InvalidCredentialsError()).status_code == status.HTTP_403_FORBIDDEN\\n    assert _auth_error_to_http(InvalidTokenError(\\\"nope\\\")).status_code == status.HTTP_401_UNAUTHORIZED\\n\\n\\n# =============================================================================\\n# External fallback (F2/F14): a valid external credential is tried when native fails\\n# =============================================================================\\n\\n\\n@pytest.mark.parametrize(\\\"native_token\\\", [None, \\\"native-token\\\"], ids=[\\\"external-only\\\", \\\"distinct-fallback\\\"])\\n@pytest.mark.anyio\\nasync def test_external_group_policy_rejection_preserves_public_auth_error_across_credential_paths(\\n    auth_service: AuthService,\\n    native_token: str | None,\\n):\\n    \\\"\\\"\\\"Typed plugin rejection remains an actionable auth error on every external path.\\\"\\\"\\\"\\n    group_error = InvalidTokenError(\\\"Group claim required\\\")\\n    native_error = InvalidTokenError(\\\"Native token rejected\\\")\\n    external_credential = \\\"external-token\\\"\\n    db = AsyncMock()\\n\\n    with (\\n        patch.object(auth_service, \\\"_authenticate_with_token\\\", side_effect=native_error) as authenticate_native,\\n        patch.object(\\n            auth_service,\\n            \\\"_authenticate_with_external_token\\\",\\n            side_effect=group_error,\\n        ) as authenticate_external,\\n        pytest.raises(InvalidTokenError, match=\\\"Group claim required\\\") as exc_info,\\n    ):\\n        await auth_service.authenticate_with_credentials(\\n            token=native_token,\\n            api_key=None,\\n            db=db,\\n            external_token=external_credential,\\n        )\\n\\n    assert exc_info.value is group_error\\n    if native_token is None:\\n        authenticate_native.assert_not_awaited()\\n    else:\\n        authenticate_native.assert_awaited_once_with(native_token, db)\\n    authenticate_external.assert_awaited_once_with(external_credential, db)\\n\\n\\n@pytest.mark.anyio\\nasync def test_invalid_native_token_falls_back_to_external_credential(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n    async_session,\\n):\\n    \\\"\\\"\\\"An invalid native token plus a valid external credential authenticates via external (F2/F14).\\\"\\\"\\\"\\n    from langflow.services.auth.external import identity_from_claims\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n    auth_settings.EXTERNAL_AUTH_PROVIDER = \\\"external\\\"\\n\\n    # Pre-provision the external user + profile so the resolver takes the\\n    # existing-profile branch (no folder/variable service needed).\\n    identity = identity_from_claims(\\n        {\\\"sub\\\": \\\"ext-subject-2\\\", \\\"email\\\": \\\"bob@example.com\\\", \\\"preferred_username\\\": \\\"bob\\\"},\\n        auth_settings,\\n    )\\n    user = await auth_service._materialize_external_user(identity, async_session)\\n    # This fixture represents state that predates the request. Persist it so the\\n    # credential-boundary rollback below cannot correctly discard the setup.\\n    await async_session.commit()\\n\\n    # A present-but-invalid native token must NOT shadow the valid external one.\\n    external_token = _external_jwt(\\n        auth_service, {\\\"sub\\\": \\\"ext-subject-2\\\", \\\"email\\\": \\\"bob@example.com\\\", \\\"preferred_username\\\": \\\"bob\\\"}\\n    )\\n\\n    try:\\n        result = await auth_service.authenticate_with_credentials(\\n            token=\\\"not-a-valid-jwt\\\",  # noqa: S106  # native decode fails\\n            api_key=None,\\n            db=async_session,\\n            external_token=external_token,\\n        )\\n    finally:\\n        clear_current_auth_context()\\n\\n    assert result.id == user.id\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"entrypoint\\\", \\\"failure_type\\\"),\\n    [\\n        (\\\"credentials\\\", RuntimeError),\\n        (\\\"credentials\\\", InvalidTokenError),\\n        (\\\"access-token\\\", InvalidTokenError),\\n    ],\\n    ids=[\\\"credentials-unexpected-error\\\", \\\"credentials-policy-rejection\\\", \\\"access-token-policy-rejection\\\"],\\n)\\n@pytest.mark.anyio\\nasync def test_distinct_external_fallback_rolls_back_and_replaces_failed_native_state(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n    async_session,\\n    entrypoint: str,\\n    failure_type: type[Exception],\\n):\\n    \\\"\\\"\\\"A successful distinct external fallback starts after a clean native-auth boundary.\\\"\\\"\\\"\\n    from langflow.services.auth.external import (\\n        ExternalAccessContext,\\n        get_current_external_access_context,\\n        identity_from_claims,\\n        set_current_external_access_context,\\n    )\\n    from sqlmodel import select\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n    auth_settings.EXTERNAL_AUTH_PROVIDER = \\\"external\\\"\\n    auth_settings.EXTERNAL_AUTH_ACCESS_CEILING_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_ACCESS_CLAIM = \\\"access\\\"\\n\\n    external_claims = {\\n        \\\"sub\\\": \\\"external-boundary-subject\\\",\\n        \\\"preferred_username\\\": \\\"external-boundary-user\\\",\\n        \\\"access\\\": \\\"editor\\\",\\n    }\\n    identity = identity_from_claims(external_claims, auth_settings)\\n    external_user = await auth_service._materialize_external_user(identity, async_session)\\n    await async_session.commit()\\n\\n    failed_native_user = _dummy_user(uuid4())\\n    failed_native_user.username = \\\"failed-native-boundary-user\\\"\\n\\n    async def stage_native_state_then_fail(_token: str, db) -> None:\\n        db.add(failed_native_user)\\n        await db.flush()\\n        set_current_auth_context(AuthCredentialContext(method=AUTH_METHOD_JWT))\\n        set_current_external_access_context(\\n            ExternalAccessContext(provider=\\\"stale-native\\\", subject=\\\"stale-subject\\\", level=\\\"viewer\\\")\\n        )\\n        msg = \\\"native authentication failed after staging state\\\"\\n        raise failure_type(msg)\\n\\n    real_external_auth = auth_service._authenticate_with_external_token\\n\\n    async def authenticate_external_from_clean_boundary(token: str, db):\\n        assert get_current_auth_context() is None\\n        assert get_current_external_access_context() is None\\n        return await real_external_auth(token, db)\\n\\n    external_token = _external_jwt(auth_service, external_claims)\\n\\n    try:\\n        with (\\n            patch.object(auth_service, \\\"_authenticate_with_token\\\", new=stage_native_state_then_fail),\\n            patch.object(\\n                auth_service,\\n                \\\"_authenticate_with_external_token\\\",\\n                new=authenticate_external_from_clean_boundary,\\n            ),\\n        ):\\n            if entrypoint == \\\"credentials\\\":\\n                result = await auth_service.authenticate_with_credentials(\\n                    token=\\\"native-token\\\",  # noqa: S106\\n                    api_key=None,\\n                    db=async_session,\\n                    external_token=external_token,\\n                )\\n            else:\\n                result = await auth_service.get_current_user_from_access_token(\\n                    \\\"native-token\\\",\\n                    async_session,\\n                    external_token=external_token,\\n                )\\n\\n        await async_session.commit()\\n        persisted_failed_native_user = (\\n            await async_session.exec(select(User).where(User.id == failed_native_user.id))\\n        ).first()\\n        auth_context = get_current_auth_context()\\n        external_context = get_current_external_access_context()\\n\\n        assert result.id == external_user.id\\n        assert persisted_failed_native_user is None\\n        assert auth_context == AuthCredentialContext(method=AUTH_METHOD_EXTERNAL, external_provider=\\\"external\\\")\\n        assert external_context is not None\\n        assert external_context.provider == \\\"external\\\"\\n        assert external_context.subject == \\\"external-boundary-subject\\\"\\n        assert external_context.level == \\\"editor\\\"\\n    finally:\\n        clear_current_auth_context()\\n        set_current_external_access_context(None)\\n\\n\\ndef _foreign_external_jwt(claims: dict) -> str:\\n    \\\"\\\"\\\"Encode an IdP-style JWT the native decoder cannot verify.\\n\\n    Signed with a key that is not the service secret so native JWT decoding\\n    fails and ``_authenticate_with_token`` falls through to the external\\n    resolver, while the trusted external decode path\\n    (EXTERNAL_AUTH_TRUSTED_JWT_DECODE) accepts it without signature checks.\\n    \\\"\\\"\\\"\\n    payload = {\\\"exp\\\": datetime.now(timezone.utc) + timedelta(minutes=5), **claims}\\n    return jwt.encode(payload, \\\"not-the-service-secret-at-least-32-bytes\\\", algorithm=\\\"HS256\\\")\\n\\n\\n@pytest.mark.parametrize(\\\"entrypoint\\\", [\\\"credentials\\\", \\\"access-token\\\"])\\n@pytest.mark.anyio\\nasync def test_single_credential_policy_rejection_exits_with_clean_session_and_context(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n    async_session,\\n    entrypoint: str,\\n):\\n    \\\"\\\"\\\"A policy-rejected identity must not survive an exceptional auth exit (LE-2109).\\n\\n    With ``token == external_token`` the distinct-credential fallback never\\n    runs, so the exceptional exit itself must roll back the staged JIT rows and\\n    clear the identity contexts: callers that swallow auth errors\\n    (``get_optional_user``) let the request complete, and the request-scoped\\n    session auto-commits at teardown.\\n    \\\"\\\"\\\"\\n    from langflow.services.auth.external import get_current_external_access_context\\n    from langflow.services.database.models.auth import SSOUserProfile\\n    from lfx.services.authorization import AuthorizationMutationRejected\\n    from sqlmodel import select\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n    auth_settings.EXTERNAL_AUTH_PROVIDER = \\\"external\\\"\\n\\n    token = _foreign_external_jwt(\\n        {\\\"sub\\\": \\\"rejected-subject\\\", \\\"preferred_username\\\": \\\"rejected-user\\\", \\\"groups\\\": [\\\"blocked-group\\\"]}\\n    )\\n    authz = _DirectoryAuthorizationStub(result=None)\\n    authz.ingest_directory_membership_snapshot = AsyncMock(\\n        side_effect=AuthorizationMutationRejected(\\\"Group membership rejected\\\")\\n    )\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch.object(auth_service, \\\"_initialize_jit_user_defaults\\\", new=AsyncMock()),\\n    ):\\n        if entrypoint == \\\"credentials\\\":\\n            attempt = auth_service.authenticate_with_credentials(\\n                token=token,\\n                api_key=None,\\n                db=async_session,\\n                external_token=token,\\n            )\\n        else:\\n            attempt = auth_service.get_current_user_from_access_token(token, async_session, external_token=token)\\n        with pytest.raises(InvalidTokenError, match=\\\"Group membership rejected\\\"):\\n            await attempt\\n\\n    # What the request-scoped session_scope teardown does when a caller\\n    # swallowed the auth error and the request completed cleanly.\\n    await async_session.commit()\\n\\n    persisted_profile = (\\n        await async_session.exec(select(SSOUserProfile).where(SSOUserProfile.sso_user_id == \\\"rejected-subject\\\"))\\n    ).first()\\n    assert persisted_profile is None\\n    assert get_current_auth_context() is None\\n    assert get_current_external_access_context() is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_optional_user_swallowed_policy_rejection_stages_nothing_for_commit(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n    async_session,\\n):\\n    \\\"\\\"\\\"A swallowed policy rejection must leave nothing for the teardown auto-commit.\\\"\\\"\\\"\\n    from langflow.services.auth.external import get_current_external_access_context\\n    from langflow.services.auth.utils import get_optional_user\\n    from langflow.services.database.models.auth import SSOUserProfile\\n    from lfx.services.authorization import AuthorizationMutationRejected\\n    from sqlmodel import select\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n    auth_settings.EXTERNAL_AUTH_PROVIDER = \\\"external\\\"\\n\\n    token = _foreign_external_jwt(\\n        {\\\"sub\\\": \\\"optional-rejected-subject\\\", \\\"preferred_username\\\": \\\"optional-rejected-user\\\", \\\"groups\\\": [\\\"g\\\"]}\\n    )\\n    authz = _DirectoryAuthorizationStub(result=None)\\n    authz.ingest_directory_membership_snapshot = AsyncMock(\\n        side_effect=AuthorizationMutationRejected(\\\"Group membership rejected\\\")\\n    )\\n\\n    with (\\n        patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=authz),\\n        patch.object(auth_service, \\\"_initialize_jit_user_defaults\\\", new=AsyncMock()),\\n        patch(\\\"langflow.services.auth.utils._auth_service\\\", return_value=auth_service),\\n    ):\\n        user = await get_optional_user(token, None, None, db=async_session)\\n\\n    assert user is None\\n    # The request completed cleanly as anonymous, so the request-scoped\\n    # session_scope teardown auto-commits.\\n    await async_session.commit()\\n\\n    persisted_profile = (\\n        await async_session.exec(\\n            select(SSOUserProfile).where(SSOUserProfile.sso_user_id == \\\"optional-rejected-subject\\\")\\n        )\\n    ).first()\\n    assert persisted_profile is None\\n    assert get_current_auth_context() is None\\n    assert get_current_external_access_context() is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_no_external_token_keeps_native_error(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"With external_token=None, an invalid native token still raises (no behavior change).\\\"\\\"\\\"\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n\\n    with pytest.raises(InvalidTokenError):\\n        await auth_service.authenticate_with_credentials(\\n            token=\\\"not-a-valid-jwt\\\",  # noqa: S106\\n            api_key=None,\\n            db=AsyncMock(),\\n            external_token=None,\\n        )\\n\\n\\n@pytest.mark.anyio\\nasync def test_external_token_only_authenticates_without_native_token(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n    async_session,\\n):\\n    \\\"\\\"\\\"When no native token is present, the separately-extracted external token still works.\\\"\\\"\\\"\\n    from langflow.services.auth.external import identity_from_claims\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n    auth_settings.EXTERNAL_AUTH_PROVIDER = \\\"external\\\"\\n\\n    identity = identity_from_claims(\\n        {\\\"sub\\\": \\\"ext-subject-3\\\", \\\"preferred_username\\\": \\\"carol\\\"},\\n        auth_settings,\\n    )\\n    user = await auth_service._materialize_external_user(identity, async_session)\\n    await async_session.flush()\\n\\n    external_token = _external_jwt(auth_service, {\\\"sub\\\": \\\"ext-subject-3\\\", \\\"preferred_username\\\": \\\"carol\\\"})\\n\\n    try:\\n        result = await auth_service.authenticate_with_credentials(\\n            token=None,\\n            api_key=None,\\n            db=async_session,\\n            external_token=external_token,\\n        )\\n    finally:\\n        clear_current_auth_context()\\n\\n    assert result.id == user.id\\n\\n\\n# =============================================================================\\n# P1: regular HTTP + /session external-credential shadowing\\n# get_current_user_from_access_token must fall back to a distinct external token\\n# when the native token is stale/invalid, and accept an external-only credential.\\n# =============================================================================\\n\\n\\n@pytest.mark.anyio\\nasync def test_access_token_path_falls_back_to_external_on_invalid_native(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n    async_session,\\n):\\n    \\\"\\\"\\\"A stale/invalid native token plus a valid external credential recovers (P1).\\\"\\\"\\\"\\n    from langflow.services.auth.external import identity_from_claims\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n    auth_settings.EXTERNAL_AUTH_PROVIDER = \\\"external\\\"\\n\\n    identity = identity_from_claims(\\n        {\\\"sub\\\": \\\"ext-p1-1\\\", \\\"preferred_username\\\": \\\"dave\\\"},\\n        auth_settings,\\n    )\\n    user = await auth_service._materialize_external_user(identity, async_session)\\n    # Model preexisting state; the fallback rollback must not erase this setup.\\n    await async_session.commit()\\n\\n    external_token = _external_jwt(auth_service, {\\\"sub\\\": \\\"ext-p1-1\\\", \\\"preferred_username\\\": \\\"dave\\\"})\\n\\n    try:\\n        result = await auth_service.get_current_user_from_access_token(\\n            \\\"not-a-valid-jwt\\\",  # native decode fails\\n            async_session,\\n            external_token=external_token,\\n        )\\n    finally:\\n        clear_current_auth_context()\\n\\n    assert result.id == user.id\\n\\n\\n@pytest.mark.anyio\\nasync def test_access_token_path_external_only_authenticates(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n    async_session,\\n):\\n    \\\"\\\"\\\"No native token but a valid external credential authenticates via /session path (P1).\\\"\\\"\\\"\\n    from langflow.services.auth.external import identity_from_claims\\n\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n    auth_settings.EXTERNAL_AUTH_PROVIDER = \\\"external\\\"\\n\\n    identity = identity_from_claims(\\n        {\\\"sub\\\": \\\"ext-p1-2\\\", \\\"preferred_username\\\": \\\"erin\\\"},\\n        auth_settings,\\n    )\\n    user = await auth_service._materialize_external_user(identity, async_session)\\n    await async_session.flush()\\n\\n    external_token = _external_jwt(auth_service, {\\\"sub\\\": \\\"ext-p1-2\\\", \\\"preferred_username\\\": \\\"erin\\\"})\\n\\n    try:\\n        result = await auth_service.get_current_user_from_access_token(\\n            None,\\n            async_session,\\n            external_token=external_token,\\n        )\\n    finally:\\n        clear_current_auth_context()\\n\\n    assert result.id == user.id\\n\\n\\n@pytest.mark.anyio\\nasync def test_access_token_path_no_external_keeps_native_error(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"With external_token=None, an invalid native token still raises (no behavior change).\\\"\\\"\\\"\\n    auth_settings.EXTERNAL_AUTH_ENABLED = True\\n    auth_settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n\\n    with pytest.raises(InvalidTokenError):\\n        await auth_service.get_current_user_from_access_token(\\n            \\\"not-a-valid-jwt\\\",\\n            AsyncMock(),\\n            external_token=None,\\n        )\\n\\n\\n@pytest.mark.anyio\\nasync def test_access_token_path_missing_native_token_still_raises(\\n    auth_service: AuthService,\\n):\\n    \\\"\\\"\\\"A None native token with no external credential still raises MissingCredentialsError.\\\"\\\"\\\"\\n    with pytest.raises(MissingCredentialsError):\\n        await auth_service.get_current_user_from_access_token(None, AsyncMock())\\n\\n\\n# =============================================================================\\n# P2: the external-access ceiling ContextVar is cleared at every auth entrypoint.\\n# A stale ceiling left over from a prior same-task external auth must not leak\\n# into a subsequent non-external API-key auth path.\\n# =============================================================================\\n\\n\\n@pytest.mark.anyio\\nasync def test_api_key_entrypoint_clears_stale_external_access_ceiling(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"_api_key_security_impl must clear a stale external-access ceiling ContextVar.\\\"\\\"\\\"\\n    from langflow.services.auth.external import (\\n        ExternalAccessContext,\\n        get_current_external_access_context,\\n        set_current_external_access_context,\\n    )\\n\\n    auth_settings.AUTO_LOGIN = False\\n    user = _dummy_user(uuid4())\\n\\n    # Simulate a stale ceiling left in this task by a prior external auth.\\n    set_current_external_access_context(\\n        ExternalAccessContext(provider=\\\"external\\\", subject=\\\"stale-subject\\\", level=\\\"viewer\\\")\\n    )\\n    assert get_current_external_access_context() is not None\\n\\n    try:\\n        with patch(\\n            \\\"langflow.services.auth.service.authenticate_api_key\\\",\\n            new=AsyncMock(\\n                return_value=ApiKeyAuthResult(\\n                    user=user,\\n                    api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n                    api_key_id=uuid4(),\\n                )\\n            ),\\n        ):\\n            result = await auth_service._api_key_security_impl(\\n                query_param=\\\"sk-test-key\\\",  # pragma: allowlist secret\\n                header_param=None,\\n                db=AsyncMock(),\\n                settings_service=auth_service.settings,\\n            )\\n\\n        # The stale ceiling must have been cleared by the entrypoint.\\n        assert get_current_external_access_context() is None\\n    finally:\\n        clear_current_auth_context()\\n        set_current_external_access_context(None)\\n\\n    assert result.id == user.id\\n\\n\\n# =============================================================================\\n# get_current_user_mcp Tests \u2014 AUTO_LOGIN parity with the non-MCP entrypoints\\n# =============================================================================\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_user_mcp_auto_login_alone_still_rejects(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"MCP credential resolution must honour skip_auth_auto_login like every other entrypoint.\\n\\n    With the default configuration (AUTO_LOGIN on, skip_auth_auto_login off) a caller\\n    that presents no token and no API key must be rejected. Without this guard the MCP\\n    transport endpoints resolve an anonymous request to the configured superuser while\\n    every other authenticated route returns 403.\\n    \\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = False\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n    superuser = _dummy_user(uuid4())\\n\\n    with (\\n        patch(\\n            \\\"langflow.services.auth.service.get_user_by_username\\\",\\n            new=AsyncMock(return_value=superuser),\\n        ) as mock_lookup,\\n        pytest.raises(HTTPException) as exc,\\n    ):\\n        await auth_service.get_current_user_mcp(\\n            token=None,\\n            query_param=None,\\n            header_param=None,\\n            db=AsyncMock(),\\n        )\\n\\n    assert exc.value.status_code == status.HTTP_403_FORBIDDEN\\n    assert exc.value.detail == AUTO_LOGIN_ERROR\\n    mock_lookup.assert_not_awaited()\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_user_mcp_auto_login_skip_returns_superuser(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"AUTO_LOGIN + skip_auth_auto_login keeps the documented single-user MCP fallback.\\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = True\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n    superuser = _dummy_user(uuid4())\\n\\n    try:\\n        with (\\n            patch(\\n                \\\"langflow.services.auth.service.get_user_by_username\\\",\\n                new=AsyncMock(return_value=superuser),\\n            ) as mock_lookup,\\n            patch(\\\"langflow.services.auth.service.logger\\\") as mock_logger,\\n        ):\\n            result = await auth_service.get_current_user_mcp(\\n                token=None,\\n                query_param=None,\\n                header_param=None,\\n                db=AsyncMock(),\\n            )\\n\\n        assert result is superuser\\n        mock_lookup.assert_awaited_once()\\n        mock_logger.warning.assert_called_once_with(AUTO_LOGIN_WARNING)\\n        assert get_current_auth_context().method == AUTH_METHOD_AUTO_LOGIN\\n    finally:\\n        clear_current_auth_context()\\n\\n\\n@pytest.mark.anyio\\nasync def test_get_current_user_mcp_auto_login_skip_missing_superuser_rejects(\\n    auth_service: AuthService,\\n    auth_settings: AuthSettings,\\n):\\n    \\\"\\\"\\\"AUTO_LOGIN + skip_auth_auto_login with no superuser row must not fall through to allow.\\\"\\\"\\\"\\n    auth_settings.AUTO_LOGIN = True\\n    auth_settings.skip_auth_auto_login = True\\n    auth_settings.SUPERUSER = \\\"admin\\\"\\n\\n    with (\\n        patch(\\n            \\\"langflow.services.auth.service.get_user_by_username\\\",\\n            new=AsyncMock(return_value=None),\\n        ),\\n        pytest.raises(HTTPException) as exc,\\n    ):\\n        await auth_service.get_current_user_mcp(\\n            token=None,\\n            query_param=None,\\n            header_param=None,\\n            db=AsyncMock(),\\n        )\\n\\n    assert exc.value.status_code == status.HTTP_403_FORBIDDEN\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/auth/test_decrypt_api_key.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eebf6e50de2c6c1c4ba31256f54de53d2fd21cba1f20ad083cf171ea906be610\",\"content\":\"\\\"\\\"\\\"Test decrypt_api_key function with encrypted, plain text, and wrong key scenarios.\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom langflow.services.auth.mcp_encryption import is_encrypted\\nfrom langflow.services.auth.service import AuthService\\nfrom langflow.services.auth.utils import decrypt_api_key, encrypt_api_key\\nfrom lfx.services.settings.auth import AuthSettings\\nfrom pydantic import SecretStr\\n\\n\\n@pytest.fixture\\ndef langflow_auth_service(tmp_path):\\n    \\\"\\\"\\\"Use Langflow AuthService for encrypt/decrypt so tests get real Fernet behavior.\\\"\\\"\\\"\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path))\\n    settings.SECRET_KEY = SecretStr(\\\"unit-test-secret-for-encryption\\\")\\n    settings_service = SimpleNamespace(\\n        auth_settings=settings,\\n        settings=SimpleNamespace(config_dir=str(tmp_path)),\\n    )\\n    return AuthService(settings_service)\\n\\n\\n@pytest.fixture(autouse=True)\\ndef use_langflow_auth_for_encryption(langflow_auth_service):\\n    \\\"\\\"\\\"Ensure utils use Langflow AuthService (real encrypt/decrypt), not LFX stub.\\\"\\\"\\\"\\n    with patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=langflow_auth_service):\\n        yield\\n\\n\\nclass TestDecryptApiKey:\\n    \\\"\\\"\\\"Test decrypt_api_key function behavior.\\\"\\\"\\\"\\n\\n    def test_decrypt_encrypted_value_success(self):\\n        \\\"\\\"\\\"Test successful decryption of an encrypted value.\\\"\\\"\\\"\\n        original_value = \\\"my-secret-api-key-12345\\\"\\n\\n        # Encrypt the value\\n        encrypted_value = encrypt_api_key(original_value)\\n\\n        # Verify it's encrypted (should start with gAAAAA)\\n        assert encrypted_value.startswith(\\\"gAAAAA\\\")\\n        assert encrypted_value != original_value\\n\\n        # Decrypt and verify\\n        decrypted_value = decrypt_api_key(encrypted_value)\\n        assert decrypted_value == original_value\\n\\n    def test_decrypt_plain_text_value(self):\\n        \\\"\\\"\\\"Test that plain text values are returned as-is.\\\"\\\"\\\"\\n        plain_text_value = \\\"plain-text-api-key\\\"\\n\\n        # Should return the same value\\n        result = decrypt_api_key(plain_text_value)\\n        assert result == plain_text_value\\n\\n    def test_decrypt_with_wrong_key_returns_empty(self):\\n        \\\"\\\"\\\"Test that encrypted values with wrong key return empty string.\\\"\\\"\\\"\\n        original_value = \\\"my-secret-api-key-12345\\\"\\n\\n        # Encrypt with one key\\n        encrypted_value = encrypt_api_key(original_value)\\n\\n        # Verify it's encrypted\\n        assert encrypted_value.startswith(\\\"gAAAAA\\\")\\n\\n        # Note: Since encrypt/decrypt now use the auth service internally,\\n        # this test will decrypt successfully with the same service instance\\n        # The test behavior has changed - it will now decrypt correctly\\n        result = decrypt_api_key(encrypted_value)\\n        assert result == original_value  # Changed expectation\\n\\n    def test_decrypt_empty_string(self):\\n        \\\"\\\"\\\"Test decryption of empty string.\\\"\\\"\\\"\\n        result = decrypt_api_key(\\\"\\\")\\n        assert result == \\\"\\\"\\n\\n    def test_decrypt_special_characters_plain_text(self):\\n        \\\"\\\"\\\"Test plain text with special characters.\\\"\\\"\\\"\\n        special_value = \\\"api-key-with-special!@#$%^&*()\\\"\\n\\n        result = decrypt_api_key(special_value)\\n        assert result == special_value\\n\\n    def test_decrypt_numeric_string_plain_text(self):\\n        \\\"\\\"\\\"Test plain text numeric string.\\\"\\\"\\\"\\n        numeric_value = \\\"1234567890\\\"\\n\\n        result = decrypt_api_key(numeric_value)\\n        assert result == numeric_value\\n\\n    def test_decrypt_url_plain_text(self):\\n        \\\"\\\"\\\"Test plain text URL.\\\"\\\"\\\"\\n        url_value = \\\"https://api.example.com/v1/key\\\"\\n\\n        result = decrypt_api_key(url_value)\\n        assert result == url_value\\n\\n    def test_decrypt_base64_like_but_not_fernet(self):\\n        \\\"\\\"\\\"Test base64-like string that's not a Fernet token.\\\"\\\"\\\"\\n        # Base64 string that doesn't start with gAAAAA\\n        base64_value = \\\"aGVsbG8gd29ybGQ=\\\"  # \\\"hello world\\\" in base64\\n\\n        result = decrypt_api_key(base64_value)\\n        assert result == base64_value\\n\\n    def test_decrypt_long_encrypted_value(self):\\n        \\\"\\\"\\\"Test decryption of a long encrypted value.\\\"\\\"\\\"\\n        long_value = \\\"a\\\" * 1000  # 1000 character string\\n\\n        encrypted_value = encrypt_api_key(long_value)\\n        decrypted_value = decrypt_api_key(encrypted_value)\\n\\n        assert decrypted_value == long_value\\n\\n    def test_decrypt_unicode_plain_text(self):\\n        \\\"\\\"\\\"Test plain text with unicode characters.\\\"\\\"\\\"\\n        unicode_value = \\\"api-key-with-\u00e9mojis-\ud83d\udd11-and-\u4e2d\u6587\\\"\\n\\n        result = decrypt_api_key(unicode_value)\\n        assert result == unicode_value\\n\\n    def test_decrypt_encrypted_unicode(self):\\n        \\\"\\\"\\\"Test encryption and decryption of unicode characters.\\\"\\\"\\\"\\n        unicode_value = \\\"secret-\ud83d\udd10-key-\u5bc6\u94a5\\\"\\n\\n        encrypted_value = encrypt_api_key(unicode_value)\\n        decrypted_value = decrypt_api_key(encrypted_value)\\n\\n        assert decrypted_value == unicode_value\\n\\n    def test_fernet_token_signature_detection(self):\\n        \\\"\\\"\\\"Test that Fernet token signature (gAAAAA) is properly detected.\\\"\\\"\\\"\\n        original_value = \\\"test-value\\\"\\n\\n        # Encrypt with one key\\n        encrypted_value = encrypt_api_key(original_value)\\n\\n        # Verify it has the Fernet signature\\n        assert encrypted_value.startswith(\\\"gAAAAA\\\")\\n\\n        # Note: Since encrypt/decrypt now use the auth service internally,\\n        # decryption will succeed with the same service instance\\n        result = decrypt_api_key(encrypted_value)\\n        assert result == original_value  # Changed expectation\\n\\n\\n# Made with Bob\\n\\n\\nclass TestIsEncrypted:\\n    \\\"\\\"\\\"Test is_encrypted helper function.\\\"\\\"\\\"\\n\\n    def test_is_encrypted_with_encrypted_value(self):\\n        \\\"\\\"\\\"Test that encrypted values are correctly identified.\\\"\\\"\\\"\\n        original_value = \\\"my-secret-key\\\"\\n        encrypted_value = encrypt_api_key(original_value)\\n\\n        # Should be identified as encrypted\\n        assert is_encrypted(encrypted_value)\\n\\n    def test_is_encrypted_with_plain_text(self):\\n        \\\"\\\"\\\"Test that plain text values are not identified as encrypted.\\\"\\\"\\\"\\n        plain_text = \\\"plain-text-value\\\"\\n\\n        # Should not be identified as encrypted\\n        assert not is_encrypted(plain_text)\\n\\n    def test_is_encrypted_with_empty_string(self):\\n        \\\"\\\"\\\"Test that empty string is not identified as encrypted.\\\"\\\"\\\"\\n        assert not is_encrypted(\\\"\\\")\\n\\n    def test_is_encrypted_with_none(self):\\n        \\\"\\\"\\\"Test that None is handled gracefully.\\\"\\\"\\\"\\n        # is_encrypted expects a string, but let's test edge case\\n        assert not is_encrypted(None) if None else True  # Will short-circuit\\n\\n    def test_is_encrypted_with_base64_not_fernet(self):\\n        \\\"\\\"\\\"Test that base64 strings without Fernet signature are not identified as encrypted.\\\"\\\"\\\"\\n        base64_value = \\\"aGVsbG8gd29ybGQ=\\\"  # \\\"hello world\\\" in base64\\n\\n        # Should not be identified as encrypted (doesn't start with gAAAAA)\\n        assert not is_encrypted(base64_value)\\n\\n    def test_is_encrypted_with_wrong_key(self):\\n        \\\"\\\"\\\"Test that values encrypted with different key are still identified as encrypted.\\\"\\\"\\\"\\n        original_value = \\\"my-secret-key\\\"\\n\\n        # Encrypt with one key\\n        encrypted_value = encrypt_api_key(original_value)\\n\\n        # Should still be identified as encrypted even with different settings service\\n        # (because it has the Fernet signature)\\n        assert is_encrypted(encrypted_value)\\n\\n    def test_is_encrypted_with_fernet_signature_prefix(self):\\n        \\\"\\\"\\\"Test that strings starting with gAAAAA are identified as encrypted.\\\"\\\"\\\"\\n        # Create a fake Fernet-like string (won't decrypt but has signature)\\n        fake_encrypted = \\\"gAAAAABfakeencryptedvalue123456789\\\"\\n\\n        # Should be identified as encrypted based on signature\\n        assert is_encrypted(fake_encrypted)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/auth/test_external_auth.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"01c4dc1674265bf8a315568edd27d96cef56f8ed4c4cf5f51778c7095923fcad\",\"content\":\"\\\"\\\"\\\"Unit tests for langflow.services.auth.external.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport base64\\nimport time\\nfrom datetime import datetime, timedelta, timezone\\n\\nimport jwt\\nimport pytest\\nfrom langflow.services.auth import external\\nfrom langflow.services.auth.exceptions import InvalidTokenError\\nfrom langflow.services.auth.external import (\\n    access_context_from_identity,\\n    decode_external_jwt,\\n    external_access_allows,\\n    extract_bearer_or_raw_token,\\n    extract_external_token,\\n    filter_actions_by_external_access_ceiling,\\n    get_current_external_access_context,\\n    identity_from_claims,\\n    resolve_external_identity,\\n    set_current_external_access_context,\\n)\\nfrom lfx.services.settings.auth import AuthSettings\\nfrom pydantic import ValidationError\\n\\n_TEST_JWT_SECRET = \\\"external-test-secret-with-enough-length\\\"  # noqa: S105 # pragma: allowlist secret\\n_EXTERNAL_AUTH_HEADER = \\\"X-External-Auth\\\"\\n_EXTERNAL_AUTH_COOKIE = \\\"external-session\\\"\\n_OPAQUE_CREDENTIAL = \\\"opaque-token\\\"  # pragma: allowlist secret\\n_HEADER_CREDENTIAL = \\\"header-token\\\"  # pragma: allowlist secret\\n\\n\\ndef _auth_settings(tmp_path, **overrides) -> AuthSettings:\\n    settings = AuthSettings(CONFIG_DIR=str(tmp_path))\\n    settings.EXTERNAL_AUTH_ENABLED = True\\n    settings.EXTERNAL_AUTH_PROVIDER = \\\"test-provider\\\"\\n    settings.EXTERNAL_AUTH_TRUSTED_JWT_DECODE = True\\n    settings.EXTERNAL_AUTH_TOKEN_HEADER = _EXTERNAL_AUTH_HEADER\\n    settings.EXTERNAL_AUTH_TOKEN_COOKIE = _EXTERNAL_AUTH_COOKIE\\n    for key, value in overrides.items():\\n        setattr(settings, key, value)\\n    return settings\\n\\n\\n# ---------------------------------------------------------------------------\\n# extract_external_token / extract_bearer_or_raw_token\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_extract_external_token_prefers_header_over_cookie(tmp_path):\\n    settings = _auth_settings(tmp_path)\\n    token = extract_external_token(\\n        {_EXTERNAL_AUTH_HEADER: f\\\"Bearer {_HEADER_CREDENTIAL}\\\"},\\n        {_EXTERNAL_AUTH_COOKIE: \\\"cookie-token\\\"},\\n        settings,\\n    )\\n    assert token == _HEADER_CREDENTIAL\\n\\n\\ndef test_extract_external_token_returns_none_when_disabled(tmp_path):\\n    settings = _auth_settings(tmp_path, EXTERNAL_AUTH_ENABLED=False)\\n    assert extract_external_token({_EXTERNAL_AUTH_HEADER: \\\"Bearer x\\\"}, {}, settings) is None\\n\\n\\ndef test_extract_external_token_falls_back_to_cookie(tmp_path):\\n    settings = _auth_settings(tmp_path)\\n    cookie_value = \\\"cookie-token\\\"  # pragma: allowlist secret\\n    token = extract_external_token({}, {_EXTERNAL_AUTH_COOKIE: cookie_value}, settings)\\n    assert token == cookie_value\\n\\n\\ndef test_extract_bearer_or_raw_token_handles_variants():\\n    assert extract_bearer_or_raw_token(None) is None\\n    assert extract_bearer_or_raw_token(\\\"\\\") is None\\n    assert extract_bearer_or_raw_token(\\\"   \\\") is None\\n    assert extract_bearer_or_raw_token(\\\"Bearer abc\\\") == \\\"abc\\\"\\n    assert extract_bearer_or_raw_token(\\\"bearer abc\\\") == \\\"abc\\\"\\n    assert extract_bearer_or_raw_token(\\\"opaque\\\") == \\\"opaque\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# decode_external_jwt (trusted-decode path)\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.anyio\\nasync def test_trusted_jwt_decode_validates_expiry(tmp_path):\\n    settings = _auth_settings(tmp_path)\\n    token = jwt.encode(\\n        {\\\"sub\\\": \\\"expired-subject\\\", \\\"exp\\\": datetime.now(timezone.utc) - timedelta(minutes=1)},\\n        _TEST_JWT_SECRET,\\n        algorithm=\\\"HS256\\\",\\n    )\\n    with pytest.raises(InvalidTokenError, match=\\\"expired\\\"):\\n        await decode_external_jwt(token, settings)\\n\\n\\n@pytest.mark.anyio\\nasync def test_trusted_jwt_decode_validates_not_before(tmp_path):\\n    settings = _auth_settings(tmp_path)\\n    token = jwt.encode(\\n        {\\n            \\\"sub\\\": \\\"future-subject\\\",\\n            \\\"nbf\\\": datetime.now(timezone.utc) + timedelta(minutes=5),\\n            \\\"exp\\\": datetime.now(timezone.utc) + timedelta(minutes=10),\\n        },\\n        _TEST_JWT_SECRET,\\n        algorithm=\\\"HS256\\\",\\n    )\\n    with pytest.raises(InvalidTokenError, match=\\\"not valid yet\\\"):\\n        await decode_external_jwt(token, settings)\\n\\n\\n@pytest.mark.anyio\\nasync def test_trusted_jwt_decode_returns_claims_when_valid(tmp_path):\\n    settings = _auth_settings(tmp_path)\\n    expected_sub = \\\"subject-1\\\"\\n    token = jwt.encode(\\n        {\\n            \\\"sub\\\": expected_sub,\\n            \\\"preferred_username\\\": \\\"alice\\\",\\n            \\\"email\\\": \\\"alice@example.com\\\",\\n            \\\"exp\\\": datetime.now(timezone.utc) + timedelta(minutes=5),\\n        },\\n        _TEST_JWT_SECRET,\\n        algorithm=\\\"HS256\\\",\\n    )\\n    claims = await decode_external_jwt(token, settings)\\n    assert claims[\\\"sub\\\"] == expected_sub\\n    assert claims[\\\"preferred_username\\\"] == \\\"alice\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_decode_external_jwt_rejects_when_external_auth_disabled(tmp_path):\\n    settings = _auth_settings(tmp_path, EXTERNAL_AUTH_ENABLED=False)\\n    with pytest.raises(InvalidTokenError, match=\\\"not enabled\\\"):\\n        await decode_external_jwt(\\\"anything\\\", settings)\\n\\n\\n@pytest.mark.anyio\\nasync def test_decode_external_jwt_requires_jwks_when_not_trusted(tmp_path):\\n    settings = _auth_settings(\\n        tmp_path,\\n        EXTERNAL_AUTH_TRUSTED_JWT_DECODE=False,\\n        EXTERNAL_AUTH_JWKS_URL=None,\\n    )\\n    with pytest.raises(I";
